/// Open one ordinary EventPump turn for CYW43 child-runtime service.
///
/// EventPump calls this once before any steady network work and once before a
/// separately scheduled bootstrap/recovery turn. All repeated smoltcp poll,
/// tail, and flush calls then share a single central operation claim.
#[cfg(feature = "kernel")]
pub(crate) fn begin_cyw43_outer_event_turn() {
    CYW43_OUTER_EVENT_TURN_ID.fetch_add(1, Ordering::AcqRel);
    CYW43_OUTER_EVENT_TURN_CLAIMED.store(0, Ordering::Release);
    CYW43_OUTER_EVENT_TURN_REJECTED.store(0, Ordering::Release);
    CYW43_OUTER_EVENT_TURN_OPERATIONS.store(0, Ordering::Release);
}

#[cfg(feature = "kernel")]
fn claim_cyw43_outer_event_turn() -> bool {
    #[cfg(test)]
    if CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.load(Ordering::Acquire) == 0 {
        CYW43_OUTER_EVENT_TURN_REJECTED.store(0, Ordering::Release);
        return true;
    }
    let claimed = CYW43_OUTER_EVENT_TURN_CLAIMED
        .compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire)
        .is_ok();
    if claimed {
        CYW43_OUTER_EVENT_TURN_OPERATIONS.store(1, Ordering::Release);
    }
    CYW43_OUTER_EVENT_TURN_REJECTED.store(if claimed { 0 } else { 1 }, Ordering::Release);
    claimed
}

#[cfg(feature = "kernel")]
fn cyw43_outer_event_turn_enforced() -> bool {
    #[cfg(test)]
    {
        CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.load(Ordering::Acquire) != 0
    }
    #[cfg(not(test))]
    {
        true
    }
}

#[cfg(feature = "kernel")]
fn cyw43_outer_event_turn_rejected() -> bool {
    CYW43_OUTER_EVENT_TURN_REJECTED.load(Ordering::Acquire) != 0
}

/// Return whether the current outer turn already executed a CYW43 child op.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_outer_event_turn_operation_claimed() -> bool {
    CYW43_OUTER_EVENT_TURN_CLAIMED.load(Ordering::Acquire) != 0
}

/// Return the number of CYW43 child operations executed in this outer turn.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_outer_event_turn_operation_count() -> u32 {
    CYW43_OUTER_EVENT_TURN_OPERATIONS.load(Ordering::Acquire)
}

/// Return the monotonic EventPump turn identifier used by the shared permit.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_outer_event_turn_id() -> u64 {
    CYW43_OUTER_EVENT_TURN_ID.load(Ordering::Acquire)
}

/// Return whether a sticky linked-pair recovery signal awaits the supervisor.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_recovery_required() -> bool {
    crate::hal::driver_task::cyw43_sdio_pair_restart_required()
        || crate::hal::driver_task::cyw43_sdio_pair_context_replay_required()
}

/// Cooperative service hook used only by the post-prompt CYW43 bootstrap.
///
/// Implementations must not touch the kernel HAL owned by the active
/// bootstrap. The root event pump uses this boundary to service bounded
/// serial/local-seat turns while keeping Wi-Fi debug operations fenced.
pub trait Cyw43BootstrapProgress {
    /// Service one bounded operator turn after the named bootstrap step.
    fn service_operator(&mut self, stage: &'static str);
}

impl<F> Cyw43BootstrapProgress for F
where
    F: FnMut(&'static str),
{
    fn service_operator(&mut self, stage: &'static str) {
        self(stage);
    }
}

fn cyw43_bootstrap_progress_noop(_: &'static str) {}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy)]
struct Cyw43RetainedRecoveryContext {
    config: ConsoleNetConfig,
    bundle: crate::hal::WifiFirmwareBundle<'static>,
}

#[cfg(feature = "kernel")]
impl Cyw43RetainedRecoveryContext {
    fn acquire<H>(hal: &H, config: ConsoleNetConfig) -> Result<Self, DriverTaskNetError>
    where
        H: Hardware<Error = HalError>,
    {
        let bundle = hal
            .wifi_firmware_bundle()
            .map_err(|_| DriverTaskNetError::RuntimeInit("cyw43-firmware-bundle"))?;
        bundle
            .validate()
            .map_err(|_| DriverTaskNetError::RuntimeInit("cyw43-firmware-bundle"))?;
        Ok(Self { config, bundle })
    }
}

#[cfg(feature = "kernel")]
static CYW43_RETAINED_RECOVERY_CONTEXT: Mutex<Option<Cyw43RetainedRecoveryContext>> =
    Mutex::new(None);

/// Result of one retained CYW43 bootstrap supervisor turn.
///
/// `operation_executed` is true only when this turn crossed the production
/// runtime-ring or HAL boundary. Callers must return to the ordinary event
/// pump after every result, including local bookkeeping-only pending turns.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Cyw43BootstrapTurnOutcome {
    /// Bootstrap remains in progress.
    Pending {
        /// Monotonic outer event-turn identifier.
        turn_id: u64,
        /// Stable phase label for diagnostics and adversarial tests.
        stage: &'static str,
        /// Whether this turn executed one child-runtime/HAL action or poll.
        operation_executed: bool,
    },
    /// Firmware, control policy, and linked-runtime owner state are ready.
    Complete,
    /// Bootstrap failed closed.
    Failed(DriverTaskNetError),
}

/// Concise operator-facing frontier for a retained Wi-Fi bootstrap turn.
///
/// This deliberately groups the much finer internal action stages. HDMI needs
/// enough information to show that a long bootstrap is advancing, but must not
/// expose child-runtime implementation jargon or emit one line per action.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum Cyw43BootstrapDisplayFrontier {
    LinkedRuntimes,
    SdioHost,
    Cyw43Runtime,
    PhysicalLifetime,
    CardPath,
    FirmwareUpload,
    FirmwareStart,
    Function2Ready,
    ControlChannel,
    RadioPolicy,
    SecurityPolicy,
    ControlReady,
    PairRecovery,
}

#[cfg(feature = "kernel")]
impl Cyw43BootstrapDisplayFrontier {
    /// Stable, concise HDMI text following the `[drivers] WiFi` prefix.
    #[must_use]
    pub(crate) const fn display_text(self) -> &'static str {
        match self {
            Self::LinkedRuntimes => "preparing linked driver runtimes",
            Self::SdioHost => "initializing the SDIO host",
            Self::Cyw43Runtime => "starting the CYW43/SDIO service",
            Self::PhysicalLifetime => "starting one CYW43/SDIO physical lifetime",
            Self::CardPath => "gates 1-5 of 10: checking power, SDIO card, clock, and backplane",
            Self::FirmwareUpload => "gate 6/10: uploading WiFi firmware",
            Self::FirmwareStart => "gates 6-7 of 10: starting firmware and enabling Function 2",
            Self::Function2Ready => "gate 7/10: firmware running and Function 2 ready",
            Self::ControlChannel => "gate 8/10: configuring the firmware control channel",
            Self::RadioPolicy => "gate 8/10: applying radio and association policy",
            Self::SecurityPolicy => "gate 8/10: applying WiFi security policy",
            Self::ControlReady => "gate 8/10: finalizing linked-runtime ownership",
            Self::PairRecovery => "recovering the CYW43/SDIO driver pair",
        }
    }
}

/// Map an internal retained-turn stage to a material HDMI bootstrap frontier.
///
/// Multiple child stages intentionally collapse to one frontier. The EventPump
/// applies the virtual-time cadence and heartbeat policy; this mapping only
/// owns driver/gate semantics.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_bootstrap_display_frontier(
    stage: &str,
) -> Option<Cyw43BootstrapDisplayFrontier> {
    use Cyw43BootstrapDisplayFrontier as Frontier;

    if stage == "cyw43-outer-event-turn-claimed" {
        return None;
    }
    if stage.starts_with("cyw43-cold-") {
        return Some(Frontier::PhysicalLifetime);
    }
    if stage.contains("pair-restart")
        || stage.contains("context-replay")
        || stage.contains("generation-poisoned")
        || stage.contains("recovery")
        || matches!(
            stage,
            "sdio-priority-cutover-failed"
                | "sdio-priority-cutover-invalidated"
                | "sdio-priority-split-invalidated"
                | "cyw43-priority-cutover-failed"
                | "cyw43-priority-cutover-invalidated"
                | "cyw43-priority-split-invalidated"
        )
    {
        return Some(Frontier::PairRecovery);
    }
    if matches!(
        stage,
        "cyw43-control-plane-ready" | "sdio-priority-cutover" | "cyw43-priority-cutover"
    ) {
        return Some(Frontier::ControlReady);
    }
    if matches!(
        stage,
        "sdio-ring-service-register"
            | "sdio-descriptor-replay"
            | "cyw43-ring-service-register"
            | "cyw43-descriptor-replay"
    ) {
        return Some(Frontier::LinkedRuntimes);
    }
    if stage.starts_with("sdio-") {
        return Some(Frontier::SdioHost);
    }
    if matches!(
        stage,
        "cyw43-engine-init"
            | "cyw43-engine-init-not-issued-retry"
            | "cyw43-sdio-producer-handoff"
            | "cyw43-firmware-bundle"
    ) {
        return Some(Frontier::Cyw43Runtime);
    }
    if stage == "cyw43-transport-init" {
        return Some(Frontier::CardPath);
    }
    if matches!(
        stage,
        "cyw43-firmware-prep" | "cyw43-firmware-chunk" | "cyw43-nvram-chunk" | "cyw43-nvram-tail"
    ) {
        return Some(Frontier::FirmwareUpload);
    }
    if stage == "cyw43-firmware-release" {
        return Some(Frontier::FirmwareStart);
    }
    if matches!(stage, "cyw43-firmware-ready" | "cyw43-owner-state") {
        return Some(Frontier::Function2Ready);
    }
    if stage.starts_with("cyw43-host-eapol")
        || (stage.starts_with("cyw43-control-")
            && (stage.contains("wpa")
                || stage.contains("auth")
                || stage.contains("security")
                || stage.contains("rsn")))
    {
        return Some(Frontier::SecurityPolicy);
    }
    if stage.starts_with("cyw43-control-post-up")
        || stage.starts_with("cyw43-control-pre-join")
        || stage.starts_with("cyw43-control-connect-")
        || matches!(stage, "cyw43-control-up" | "cyw43-control-infra")
    {
        return Some(Frontier::RadioPolicy);
    }
    if stage.starts_with("cyw43-control-") {
        return Some(Frontier::ControlChannel);
    }
    None
}

