#[cfg(feature = "kernel")]
fn cyw43_rx_idle_trace(bytes: &[u8]) -> Option<Cyw43RxIdleTrace> {
    if bytes.len() < CYW43_RX_IDLE_TRACE_BYTES {
        return None;
    }
    if cyw43_read_le_u32(bytes, 0)? != CYW43_RX_IDLE_TRACE_MAGIC {
        return None;
    }
    let version = cyw43_read_le_u16(bytes, 4)?;
    if version != CYW43_RX_IDLE_TRACE_VERSION_V1
        && version != CYW43_RX_IDLE_TRACE_VERSION_V2
        && version != CYW43_RX_IDLE_TRACE_VERSION_V3
        && version != CYW43_RX_IDLE_TRACE_VERSION_V4
        && version != CYW43_RX_IDLE_TRACE_VERSION_V5
        && version != CYW43_RX_IDLE_TRACE_VERSION_V6
        && version != CYW43_RX_IDLE_TRACE_VERSION_V7
        && version != CYW43_RX_IDLE_TRACE_VERSION_V8
        && version != CYW43_RX_IDLE_TRACE_VERSION_V9
        && version != CYW43_RX_IDLE_TRACE_VERSION
    {
        return None;
    }
    if version == CYW43_RX_IDLE_TRACE_VERSION_V2 && bytes.len() < CYW43_RX_IDLE_TRACE_V2_BYTES {
        return None;
    }
    if version == CYW43_RX_IDLE_TRACE_VERSION_V3 && bytes.len() < CYW43_RX_IDLE_TRACE_V3_BYTES {
        return None;
    }
    if version == CYW43_RX_IDLE_TRACE_VERSION_V4 && bytes.len() < CYW43_RX_IDLE_TRACE_V4_BYTES {
        return None;
    }
    if version == CYW43_RX_IDLE_TRACE_VERSION_V5 && bytes.len() < CYW43_RX_IDLE_TRACE_V5_BYTES {
        return None;
    }
    if version == CYW43_RX_IDLE_TRACE_VERSION_V6 && bytes.len() < CYW43_RX_IDLE_TRACE_V6_BYTES {
        return None;
    }
    if version == CYW43_RX_IDLE_TRACE_VERSION_V7 && bytes.len() < CYW43_RX_IDLE_TRACE_V7_BYTES {
        return None;
    }
    if version == CYW43_RX_IDLE_TRACE_VERSION_V8 && bytes.len() < CYW43_RX_IDLE_TRACE_V8_BYTES {
        return None;
    }
    if version == CYW43_RX_IDLE_TRACE_VERSION_V9 && bytes.len() < CYW43_RX_IDLE_TRACE_V9_BYTES {
        return None;
    }
    if version == CYW43_RX_IDLE_TRACE_VERSION && bytes.len() < CYW43_RX_IDLE_TRACE_V10_BYTES {
        return None;
    }
    Some(Cyw43RxIdleTrace {
        valid: true,
        version,
        flags: cyw43_read_le_u16(bytes, 6)?,
        detail: cyw43_read_le_u16(bytes, 8)?,
        probe_len: cyw43_read_le_u16(bytes, 10)?,
        source_result: cyw43_read_le_u32(bytes, 12)?,
        prefix_signature: cyw43_read_le_u32(bytes, 16)?,
        prefix_digest: cyw43_read_le_u32(bytes, 20)?,
        rframe_len: cyw43_read_le_u16(bytes, 24)?,
        firstread_reads: cyw43_read_le_u16(bytes, 26)?,
        block_reads: cyw43_read_le_u16(bytes, 28)?,
        rframe_reads: cyw43_read_le_u16(bytes, 30)?,
        request_len: cyw43_read_le_u16(bytes, 32)?,
        block_size: cyw43_read_le_u16(bytes, 34)?,
        block_count: cyw43_read_le_u16(bytes, 36)?,
        retransmit_sample: cyw43_read_le_u16(bytes, 38)?,
        queue_depth: cyw43_read_le_u16(bytes, 40).unwrap_or(0),
        queue_high_water: cyw43_read_le_u16(bytes, 42).unwrap_or(0),
        cmd53_arg: cyw43_read_le_u32(bytes, 44).unwrap_or(0),
        transfer_result: cyw43_read_le_u32(bytes, 48).unwrap_or(0),
        payload_before_digest: cyw43_read_le_u32(bytes, 52).unwrap_or(0),
        payload_after_digest: cyw43_read_le_u32(bytes, 56).unwrap_or(0),
        pre_source_result: cyw43_read_le_u32(bytes, 60).unwrap_or(0),
        post_source_result: cyw43_read_le_u32(bytes, 64).unwrap_or(0),
        source_flags: cyw43_read_le_u16(bytes, 68).unwrap_or(0),
        first_nonzero_offset: cyw43_read_le_u16(bytes, 70).unwrap_or(u16::MAX),
        first_nonzero_byte: cyw43_read_le_u16(bytes, 72).unwrap_or(0),
        fifo_window_flags: cyw43_read_le_u16(bytes, 74).unwrap_or(0),
        pre_intstatus: cyw43_read_le_u32(bytes, 76).unwrap_or(0),
        post_intstatus: cyw43_read_le_u32(bytes, 80).unwrap_or(0),
        pre_sdhci_status: cyw43_read_le_u32(bytes, 84).unwrap_or(0),
        post_sdhci_status: cyw43_read_le_u32(bytes, 88).unwrap_or(0),
        fifo_window_requested: cyw43_read_le_u32(bytes, 92).unwrap_or(0),
        fifo_window_programmed: cyw43_read_le_u32(bytes, 96).unwrap_or(0),
        fifo_window_readback: cyw43_read_le_u32(bytes, 100).unwrap_or(0),
        source_empty_polls: cyw43_read_le_u32(bytes, 104).unwrap_or(0),
        rx_drain_budget_hits: cyw43_read_le_u32(bytes, 108).unwrap_or(0),
        rx_queue_overflows: cyw43_read_le_u32(bytes, 112).unwrap_or(0),
        rx_max_drained_per_turn: cyw43_read_le_u16(bytes, 116).unwrap_or(0),
        rx_irq_preserve_count: cyw43_read_le_u32(bytes, 120).unwrap_or(0),
        rx_irq_preserve_reason: cyw43_read_le_u16(bytes, 124).unwrap_or(0),
        rx_irq_preserve_int_status: cyw43_read_le_u32(bytes, 128).unwrap_or(0),
        rx_irq_preserve_ack_bits: cyw43_read_le_u32(bytes, 132).unwrap_or(0),
        sequence: cyw43_read_le_u32(bytes, 136).unwrap_or(0),
        start_ticks_lo: cyw43_read_le_u32(bytes, 140).unwrap_or(0),
        pre_sample_delta_ticks: cyw43_read_le_u32(bytes, 144).unwrap_or(0),
        transfer_delta_ticks: cyw43_read_le_u32(bytes, 148).unwrap_or(0),
        post_sample_delta_ticks: cyw43_read_le_u32(bytes, 152).unwrap_or(0),
        service_op: cyw43_read_le_u16(bytes, 156).unwrap_or(0),
        service_reason: cyw43_read_le_u16(bytes, 158).unwrap_or(0),
        service_progress: cyw43_read_le_u32(bytes, 160).unwrap_or(0),
        service_seq_window: cyw43_read_le_u16(bytes, 164).unwrap_or(0),
        service_channel: cyw43_read_le_u16(bytes, 166).unwrap_or(CYW43_SERVICE_CHANNEL_NONE),
        service_credit_observations: cyw43_read_le_u32(bytes, 168).unwrap_or(0),
        rx_irq_episode_preserves: cyw43_read_le_u16(bytes, 172).unwrap_or(0),
        rx_irq_episode_rearms: cyw43_read_le_u32(bytes, 176).unwrap_or(0),
        dpc_events_consumed: cyw43_read_le_u32(bytes, 180).unwrap_or(0),
        dpc_epoch_errors: cyw43_read_le_u32(bytes, 184).unwrap_or(0),
        dpc_sequence_errors: cyw43_read_le_u32(bytes, 188).unwrap_or(0),
        dpc_owner_rearms: cyw43_read_le_u32(bytes, 192).unwrap_or(0),
    })
}

#[cfg(feature = "kernel")]
fn cache_cyw43_dpc_client_counters(trace: Cyw43RxIdleTrace) {
    if trace.version != CYW43_RX_IDLE_TRACE_VERSION {
        return;
    }
    let Some(ring) = crate::hal::driver_task::driver_task_sdio_dpc_ring_snapshot() else {
        return;
    };
    CYW43_DPC_CLIENT_CONSUMED.store(trace.dpc_events_consumed, Ordering::Relaxed);
    CYW43_DPC_CLIENT_REARMS.store(trace.dpc_owner_rearms, Ordering::Relaxed);
    CYW43_DPC_CLIENT_EPOCH_ERRORS.store(trace.dpc_epoch_errors, Ordering::Relaxed);
    CYW43_DPC_CLIENT_SEQUENCE_ERRORS.store(trace.dpc_sequence_errors, Ordering::Relaxed);
    CYW43_DPC_CLIENT_GENERATION.store(ring.epoch, Ordering::Release);
}

#[cfg(feature = "kernel")]
fn cyw43_dpc_client_counters(generation: u32) -> Option<Cyw43DpcClientCounters> {
    if CYW43_DPC_CLIENT_GENERATION.load(Ordering::Acquire) != generation {
        return None;
    }
    let counters = Cyw43DpcClientCounters {
        consumed: CYW43_DPC_CLIENT_CONSUMED.load(Ordering::Relaxed),
        rearms: CYW43_DPC_CLIENT_REARMS.load(Ordering::Relaxed),
        epoch_errors: CYW43_DPC_CLIENT_EPOCH_ERRORS.load(Ordering::Relaxed),
        sequence_errors: CYW43_DPC_CLIENT_SEQUENCE_ERRORS.load(Ordering::Relaxed),
    };
    if CYW43_DPC_CLIENT_GENERATION.load(Ordering::Acquire) == generation {
        Some(counters)
    } else {
        None
    }
}

#[cfg(feature = "kernel")]
fn cyw43_sdio_dpc_diagnostic_from(
    ring: crate::hal::driver_task::DriverTaskSdioDpcRingSnapshot,
    client: Cyw43DpcClientCounters,
) -> Cyw43SdioDpcDiagnostic {
    // The live ring consumer is authoritative for the emitted count. Any
    // mismatch means the completion sample raced the stable ring snapshot and
    // could also omit later client errors, so the proof must be rerun.
    let client_consumer_mismatch = client.consumed != ring.consumer;
    let ring_poisoned = ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED != 0;
    let masked = ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED != 0;
    Cyw43SdioDpcDiagnostic {
        generation: ring.epoch,
        captures: ring.producer.saturating_add(ring.overruns),
        published: ring.producer,
        consumed: ring.consumer,
        sample_consumer: client.consumed,
        // This is the CYW43 runtime's generation-bound owner-rearm signal
        // attempt count, not proof that SDIO consumed each signal or re-enabled
        // CARD_INT. Keeping it independent of the consumer index avoids a
        // tautological Gate-10 comparison; the stable live ring's `masked`
        // state supplies the separate final-rearm proof.
        rearms: client.rearms,
        overruns: ring.overruns,
        epoch_errors: client.epoch_errors,
        sequence_errors: client.sequence_errors,
        ack_failures: ring.ack_failures,
        ring_poisoned,
        client_sample_stale: client_consumer_mismatch,
        poisoned: client_consumer_mismatch || client.epoch_errors != 0 || ring_poisoned,
        masked,
    }
}

/// Return the current isolated SDIO-owner/CYW43-client DPC service proof.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_sdio_dpc_diagnostic() -> Option<Cyw43SdioDpcDiagnostic> {
    #[cfg(test)]
    if let Some(snapshot) = *CYW43_DPC_DIAGNOSTIC_TEST_OVERRIDE.lock() {
        return Some(snapshot);
    }
    let ring = crate::hal::driver_task::driver_task_sdio_dpc_ring_snapshot()?;
    let client = cyw43_dpc_client_counters(ring.epoch)?;
    Some(cyw43_sdio_dpc_diagnostic_from(ring, client))
}

#[cfg(feature = "kernel")]
fn cyw43_sdio_dpc_expected_generation() -> Option<u32> {
    let policy = crate::generated::driver_runtime_image_policy();
    if !policy.required || policy.bus_links.len() != 1 {
        return None;
    }
    let link = policy.bus_links[0];
    if link.channel != "cyw43-sdio"
        || link.client_hot_path != DriverTaskHotPath::Cyw43Wifi.as_str()
        || link.owner_hot_path != DriverTaskHotPath::SdioHost.as_str()
        || link.link_epoch == 0
    {
        return None;
    }
    Some(link.link_epoch)
}

#[cfg(feature = "kernel")]
fn cyw43_sdio_dpc_ring_work_pending(
    ring: crate::hal::driver_task::DriverTaskSdioDpcRingSnapshot,
    expected_generation: Option<u32>,
) -> bool {
    expected_generation.is_some_and(|generation| ring.epoch == generation)
        && ring.overruns == 0
        && ring.ack_failures == 0
        && ring.flags
            & (DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OVERRUN
                | DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED)
            == 0
        && (ring.producer != ring.consumer
            || ring.flags & DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED != 0)
}

#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_DPC: u64 = 1 << 0;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_ROOT_WAKE: u64 = 1 << 1;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_PRE_POLL: u64 = 1 << 2;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_DATA_TX: u64 = 1 << 3;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_ARP_TX: u64 = 1 << 4;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_TX_RX_FAIRNESS: u64 = 1 << 5;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_RUNTIME_DESCRIPTOR: u64 = 1 << 6;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_ROOT_RX: u64 = 1 << 7;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_CONTROL_REPLY: u64 = 1 << 8;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_LOGICAL_OWNER: u64 = 1 << 9;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_TERMINAL_DRAIN: u64 = 1 << 10;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_HOST_EAPOL: u64 = 1 << 11;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_HAL_LEASE: u64 = 1 << 12;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_PROMPT: u64 = 1 << 13;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_MAINTENANCE: u64 = 1 << 14;
#[cfg(feature = "kernel")]
const CYW43_SERVICE_WORK_RECOVERY: u64 = 1 << 15;

/// Passive source predicates used to compose the CYW43 durable-work level.
///
/// Keeping this composition explicit makes it possible to prove that every
/// production source has one distinct reason bit without advancing any owner
/// cursor merely to inspect its state.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
struct Cyw43ServiceWorkInputs {
    dpc: bool,
    root_wake: bool,
    pre_poll: bool,
    data_tx: bool,
    arp_tx: bool,
    tx_rx_fairness: bool,
    runtime_descriptor: bool,
    root_rx: bool,
    control_reply: bool,
    logical_owner: bool,
    terminal_drain: bool,
    host_eapol: bool,
    hal_lease: bool,
    prompt: bool,
    maintenance: bool,
    recovery: bool,
}

#[cfg(feature = "kernel")]
impl Cyw43ServiceWorkInputs {
    #[must_use]
    const fn reason_mask(self) -> u64 {
        let mut reason_mask = 0u64;
        if self.dpc {
            reason_mask |= CYW43_SERVICE_WORK_DPC;
        }
        if self.root_wake {
            reason_mask |= CYW43_SERVICE_WORK_ROOT_WAKE;
        }
        if self.pre_poll {
            reason_mask |= CYW43_SERVICE_WORK_PRE_POLL;
        }
        if self.data_tx {
            reason_mask |= CYW43_SERVICE_WORK_DATA_TX;
        }
        if self.arp_tx {
            reason_mask |= CYW43_SERVICE_WORK_ARP_TX;
        }
        if self.tx_rx_fairness {
            reason_mask |= CYW43_SERVICE_WORK_TX_RX_FAIRNESS;
        }
        if self.runtime_descriptor {
            reason_mask |= CYW43_SERVICE_WORK_RUNTIME_DESCRIPTOR;
        }
        if self.root_rx {
            reason_mask |= CYW43_SERVICE_WORK_ROOT_RX;
        }
        if self.control_reply {
            reason_mask |= CYW43_SERVICE_WORK_CONTROL_REPLY;
        }
        if self.logical_owner {
            reason_mask |= CYW43_SERVICE_WORK_LOGICAL_OWNER;
        }
        if self.terminal_drain {
            reason_mask |= CYW43_SERVICE_WORK_TERMINAL_DRAIN;
        }
        if self.host_eapol {
            reason_mask |= CYW43_SERVICE_WORK_HOST_EAPOL;
        }
        if self.hal_lease {
            reason_mask |= CYW43_SERVICE_WORK_HAL_LEASE;
        }
        if self.prompt {
            reason_mask |= CYW43_SERVICE_WORK_PROMPT;
        }
        if self.maintenance {
            reason_mask |= CYW43_SERVICE_WORK_MAINTENANCE;
        }
        if self.recovery {
            reason_mask |= CYW43_SERVICE_WORK_RECOVERY;
        }
        reason_mask
    }
}

/// Passive identity and level-triggered work state for the sole CYW43 lane.
///
/// The snapshot is deliberately incapable of polling either linked runtime or
/// advancing a HAL request. EventPump may retain it across phase boundaries,
/// but only while the connection generation, pair epoch, and completed
/// physical SDIO lifetime still match.
#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) struct Cyw43ServiceWorkSnapshot {
    generation: u32,
    pair_epoch: u64,
    physical_lifetime_epoch: u32,
    bound_physical_lifetime_epoch: u32,
    reason_mask: u64,
}

#[cfg(all(feature = "kernel", test))]
static CYW43_SERVICE_WORK_SNAPSHOT_TEST_OVERRIDE: Mutex<Option<Cyw43ServiceWorkSnapshot>> =
    Mutex::new(None);

#[cfg(all(feature = "kernel", test))]
static CYW43_SERVICE_PHYSICAL_LIFETIME_EPOCH_TEST_OVERRIDE: Mutex<Option<u32>> = Mutex::new(None);

#[cfg(feature = "kernel")]
impl Cyw43ServiceWorkSnapshot {
    #[must_use]
    pub(crate) const fn generation(self) -> u32 {
        self.generation
    }

    #[must_use]
    pub(crate) const fn pair_epoch(self) -> u64 {
        self.pair_epoch
    }

    #[must_use]
    pub(crate) const fn physical_lifetime_epoch(self) -> u32 {
        self.physical_lifetime_epoch
    }

    #[must_use]
    pub(crate) const fn more_work(self) -> bool {
        self.reason_mask != 0
    }

    /// Return whether this snapshot can authorize ordinary EventPump Network
    /// service.
    ///
    /// Recovery remains visible in the passive reason mask so the bootstrap
    /// supervisor can diagnose and consume it. It is never authority for a
    /// steady-state child turn. Likewise, an absent, active, or failed
    /// physical lifetime is represented by epoch zero and must fail closed.
    #[must_use]
    pub(crate) const fn ordinary_network_admissible(self) -> bool {
        self.physical_lifetime_epoch != 0
            && self.physical_lifetime_epoch == self.bound_physical_lifetime_epoch
            && self.reason_mask & CYW43_SERVICE_WORK_RECOVERY == 0
    }

    #[must_use]
    pub(crate) const fn schedulable_network_work(self) -> bool {
        self.ordinary_network_admissible() && self.more_work()
    }

    #[must_use]
    pub(crate) const fn reason_mask(self) -> u64 {
        self.reason_mask
    }

    #[cfg(test)]
    pub(crate) const fn for_test(
        generation: u32,
        pair_epoch: u64,
        physical_lifetime_epoch: u32,
        reason_mask: u64,
    ) -> Self {
        Self {
            generation,
            pair_epoch,
            physical_lifetime_epoch,
            bound_physical_lifetime_epoch: physical_lifetime_epoch,
            reason_mask,
        }
    }

    #[cfg(test)]
    pub(crate) const fn for_test_with_bound_lifetime(
        generation: u32,
        pair_epoch: u64,
        physical_lifetime_epoch: u32,
        bound_physical_lifetime_epoch: u32,
        reason_mask: u64,
    ) -> Self {
        Self {
            generation,
            pair_epoch,
            physical_lifetime_epoch,
            bound_physical_lifetime_epoch,
            reason_mask,
        }
    }

    #[cfg(test)]
    pub(crate) const fn recovery_for_test(
        generation: u32,
        pair_epoch: u64,
        physical_lifetime_epoch: u32,
    ) -> Self {
        Self::for_test(
            generation,
            pair_epoch,
            physical_lifetime_epoch,
            CYW43_SERVICE_WORK_RECOVERY,
        )
    }
}

#[cfg(all(feature = "kernel", test))]
pub(crate) fn set_cyw43_service_work_snapshot_test_override(
    snapshot: Option<Cyw43ServiceWorkSnapshot>,
) {
    *CYW43_SERVICE_WORK_SNAPSHOT_TEST_OVERRIDE.lock() = snapshot;
}

#[cfg(all(feature = "kernel", test))]
pub(crate) fn set_cyw43_service_physical_lifetime_epoch_test_override(epoch: Option<u32>) {
    debug_assert!(epoch.is_none_or(|value| value != 0));
    *CYW43_SERVICE_PHYSICAL_LIFETIME_EPOCH_TEST_OVERRIDE.lock() = epoch;
    CYW43_BOUND_PHYSICAL_LIFETIME_EPOCH.store(epoch.unwrap_or(0), Ordering::Release);
}

#[cfg(feature = "kernel")]
fn cyw43_completed_physical_lifetime_epoch_from_record(
    lifetime: Option<pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord>,
) -> u32 {
    lifetime
        .filter(|lifetime| {
            lifetime.valid()
                && lifetime.begun_epoch != 0
                && lifetime.completed_epoch == lifetime.begun_epoch
                && lifetime.failed_epoch != lifetime.begun_epoch
                && !lifetime.active()
        })
        .map_or(0, |lifetime| lifetime.begun_epoch)
}

#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_owner_physical_lifetime_snapshot(
) -> Option<pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord> {
    #[cfg(test)]
    if let Some(epoch) = *CYW43_SERVICE_PHYSICAL_LIFETIME_EPOCH_TEST_OVERRIDE.lock() {
        return Some(pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
            begun_epoch: epoch,
            completed_epoch: epoch,
            ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
        });
    }
    crate::hal::driver_task::driver_task_sdio_physical_lifetime_snapshot()
}

#[cfg(feature = "kernel")]
fn cyw43_completed_physical_lifetime_epoch() -> u32 {
    cyw43_completed_physical_lifetime_epoch_from_record(cyw43_owner_physical_lifetime_snapshot())
}

#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_bound_physical_lifetime_current() -> bool {
    let epoch = CYW43_BOUND_PHYSICAL_LIFETIME_EPOCH.load(Ordering::Acquire);
    epoch != 0
        && cyw43_owner_physical_lifetime_snapshot().is_some_and(|lifetime| {
            lifetime.valid()
                && !lifetime.active()
                && lifetime.begun_epoch == epoch
                && lifetime.completed_epoch == epoch
                && lifetime.failed_epoch != epoch
        })
}

/// Return one passive, current-identity CYW43 service snapshot.
///
/// A notification is only an urgency hint. This level is the authoritative
/// proof that bounded Network service must resume after EventPump has rotated
/// through the physical operator lanes.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_service_work_snapshot() -> Cyw43ServiceWorkSnapshot {
    #[cfg(test)]
    if let Some(snapshot) = *CYW43_SERVICE_WORK_SNAPSHOT_TEST_OVERRIDE.lock() {
        return snapshot;
    }
    let generation = CYW43_CONNECTION_EPOCH.load(Ordering::Acquire);
    let pair_epoch = CYW43_PAIR_SCRUB_EPOCH.load(Ordering::Acquire);
    let physical_lifetime_epoch = cyw43_completed_physical_lifetime_epoch();
    let expected_dpc_generation = cyw43_sdio_dpc_expected_generation();
    #[cfg(test)]
    let dpc_override = *CYW43_DPC_DIAGNOSTIC_TEST_OVERRIDE.lock();
    #[cfg(test)]
    let dpc_pending = dpc_override.map_or_else(
        || {
            crate::hal::driver_task::driver_task_sdio_dpc_ring_snapshot()
                .is_some_and(|ring| cyw43_sdio_dpc_ring_work_pending(ring, expected_dpc_generation))
        },
        |snapshot| cyw43_sdio_dpc_diagnostic_work_pending(snapshot, expected_dpc_generation),
    );
    #[cfg(not(test))]
    let dpc_pending = crate::hal::driver_task::driver_task_sdio_dpc_ring_snapshot()
        .is_some_and(|ring| cyw43_sdio_dpc_ring_work_pending(ring, expected_dpc_generation));

    let maintenance = {
        let maintenance = CYW43_MAINTENANCE_CURSOR.lock();
        maintenance.generation == generation
            && (maintenance.requested != 0 || maintenance.action.is_some())
    };
    let data_tx = CYW43_PENDING_DATA_TX
        .lock()
        .is_some_and(|pending| pending.generation == generation);
    let arp_tx = !CYW43_PENDING_ARP_TX.lock().is_empty();
    let root_rx = CYW43_PENDING_RX_QUEUE
        .lock()
        .iter()
        .any(|pending| pending.sampled_generation == generation);
    let control_reply = !CYW43_PENDING_CONTROL_REPLY_QUEUE.lock().is_empty();
    let logical_owner = CYW43_LOGICAL_CONTROL_OWNER
        .lock()
        .is_some_and(|owner| owner.generation == generation);
    let terminal_drain = CYW43_TERMINAL_DRAIN_CURSOR
        .lock()
        .is_some_and(|cursor| cursor.generation() == generation);
    let host_eapol = cyw43_host_eapol_runtime_work_pending()
        || CYW43_HOST_EAPOL_ACTIVE.load(Ordering::Acquire) != 0;
    let hal_lease = crate::hal::driver_task::active_driver_task_retained_request(
        CYW43_WIFI_DRIVER_TASK_CONTRACT,
    )
    .is_some();
    let prompt = CYW43_PENDING_PROMPT_POLL
        .lock()
        .is_some_and(|pending| pending.generation == generation);
    let inputs = Cyw43ServiceWorkInputs {
        dpc: dpc_pending,
        root_wake: crate::hal::driver_task::cyw43_root_wake_pending(),
        pre_poll: cyw43_net_data_pre_poll_continuation_pending(CYW43_WIFI_DRIVER_TASK_CONTRACT),
        data_tx,
        arp_tx,
        tx_rx_fairness: cyw43_current_generation_data_tx_rx_fairness_due(),
        runtime_descriptor: cyw43_active_runtime_descriptor(CYW43_WIFI_DRIVER_TASK_CONTRACT)
            .is_some(),
        root_rx,
        control_reply,
        logical_owner,
        terminal_drain,
        host_eapol,
        hal_lease,
        prompt,
        maintenance,
        recovery: CYW43_GENERATION_RECOVERY_ACTIVE.load(Ordering::Acquire) != 0
            || crate::hal::driver_task::cyw43_sdio_pair_restart_required()
            || crate::hal::driver_task::cyw43_sdio_pair_context_replay_required(),
    };

    Cyw43ServiceWorkSnapshot {
        generation,
        pair_epoch,
        physical_lifetime_epoch,
        bound_physical_lifetime_epoch: CYW43_BOUND_PHYSICAL_LIFETIME_EPOCH.load(Ordering::Acquire),
        reason_mask: inputs.reason_mask(),
    }
}

#[cfg(all(feature = "kernel", test))]
fn cyw43_sdio_dpc_diagnostic_work_pending(
    snapshot: Cyw43SdioDpcDiagnostic,
    expected_generation: Option<u32>,
) -> bool {
    expected_generation.is_some_and(|generation| snapshot.generation == generation)
        && snapshot.overruns == 0
        && snapshot.epoch_errors == 0
        && snapshot.sequence_errors == 0
        && snapshot.ack_failures == 0
        && !snapshot.ring_poisoned
        && !snapshot.client_sample_stale
        && !snapshot.poisoned
        && snapshot.sample_consumer == snapshot.consumed
        && (snapshot.published != snapshot.consumed || snapshot.masked)
}

/// Return whether the isolated SDIO/CYW43 pipeline has current steady-state
/// work that needs another bounded Network turn.
///
/// This is a passive ownership snapshot. It never polls either child or
/// advances a retained request. The EventPump uses it only to retain its
/// existing one-operation Network phase for up to the configured burst cap,
/// matching Linux DPC urgency without creating a second issuer.
#[cfg(feature = "kernel")]
#[must_use]
pub(crate) fn cyw43_steady_network_work_pending(contract: DriverTaskContract) -> bool {
    contract == CYW43_WIFI_DRIVER_TASK_CONTRACT
        && cyw43_service_work_snapshot().schedulable_network_work()
}

#[cfg(all(feature = "kernel", test))]
pub(crate) fn set_cyw43_sdio_dpc_diagnostic_test_override(
    snapshot: Option<Cyw43SdioDpcDiagnostic>,
) {
    *CYW43_DPC_DIAGNOSTIC_TEST_OVERRIDE.lock() = snapshot;
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_retransmit_action(sample: u16) -> u16 {
    sample & CYW43_RX_IDLE_TRACE_RETRANSMIT_ACTION_MASK
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_retransmit_action_name(sample: u16) -> &'static str {
    match cyw43_rx_trace_retransmit_action(sample) {
        CYW43_RX_IDLE_TRACE_RETRANSMIT_ACTION_BLOCK => "block",
        CYW43_RX_IDLE_TRACE_RETRANSMIT_ACTION_CLEAR_STALE => "clear-stale",
        CYW43_RX_IDLE_TRACE_RETRANSMIT_ACTION_READ_ASSERTED_ZERO => "read-asserted-zero",
        CYW43_RX_IDLE_TRACE_RETRANSMIT_ACTION_READ_RFRAME_READY => "read-rframe-ready",
        CYW43_RX_IDLE_TRACE_RETRANSMIT_ACTION_READ_SOURCE_ASSERTED => "read-source-asserted",
        _ => "none",
    }
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_cmd53_write(arg: u32) -> bool {
    arg & (1 << 31) != 0
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_cmd53_function(arg: u32) -> u8 {
    ((arg >> 28) & 0x7) as u8
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_cmd53_block_mode(arg: u32) -> bool {
    arg & (1 << 27) != 0
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_cmd53_increment(arg: u32) -> bool {
    arg & (1 << 26) != 0
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_cmd53_addr(arg: u32) -> u32 {
    (arg >> 9) & 0x1ffff
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_cmd53_count(arg: u32) -> u16 {
    if arg == 0 {
        return 0;
    }
    let raw_count = (arg & 0x01ff) as u16;
    if !cyw43_rx_trace_cmd53_block_mode(arg) && raw_count == 0 {
        512
    } else {
        raw_count
    }
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_cmd53_mode(arg: u32) -> &'static str {
    if arg == 0 {
        "none"
    } else if cyw43_rx_trace_cmd53_block_mode(arg) {
        "block"
    } else if cyw43_rx_trace_cmd53_count(arg) == 512 {
        "byte512"
    } else {
        "byte"
    }
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_pre_source_asserted(trace: Cyw43RxIdleTrace) -> bool {
    trace.source_flags & CYW43_RX_IDLE_TRACE_SOURCE_FLAG_PRE_ASSERTED != 0
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_post_source_asserted(trace: Cyw43RxIdleTrace) -> bool {
    trace.source_flags & CYW43_RX_IDLE_TRACE_SOURCE_FLAG_POST_ASSERTED != 0
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_pre_source_fresh(trace: Cyw43RxIdleTrace) -> bool {
    trace.source_flags & CYW43_RX_IDLE_TRACE_SOURCE_FLAG_PRE_FRESH != 0
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_post_source_fresh(trace: Cyw43RxIdleTrace) -> bool {
    trace.source_flags & CYW43_RX_IDLE_TRACE_SOURCE_FLAG_POST_FRESH != 0
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_pre_source_failed(trace: Cyw43RxIdleTrace) -> bool {
    trace.source_flags & CYW43_RX_IDLE_TRACE_SOURCE_FLAG_PRE_FAILED != 0
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_post_source_failed(trace: Cyw43RxIdleTrace) -> bool {
    trace.source_flags & CYW43_RX_IDLE_TRACE_SOURCE_FLAG_POST_FAILED != 0
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_source_asserted_ever(trace: Cyw43RxIdleTrace) -> bool {
    trace.source_flags & CYW43_RX_IDLE_TRACE_SOURCE_FLAG_EVER_ASSERTED != 0
}

#[cfg(feature = "kernel")]
fn cyw43_rx_trace_source_asserts_pending_frame(trace: Cyw43RxIdleTrace) -> bool {
    cyw43_rx_trace_pre_source_asserted(trace)
        || cyw43_rx_trace_post_source_asserted(trace)
        || cyw43_rx_trace_source_asserted_ever(trace)
        || cyw43_rx_source_result(trace.pre_source_result)
            .is_some_and(cyw43_rx_source_asserts_pending_frame)
        || cyw43_rx_source_result(trace.post_source_result)
            .is_some_and(cyw43_rx_source_asserts_pending_frame)
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_fifo_window_ok(trace: Cyw43RxIdleTrace) -> bool {
    trace.fifo_window_flags
        & (CYW43_RX_IDLE_TRACE_FIFO_FLAG_SET_OK
            | CYW43_RX_IDLE_TRACE_FIFO_FLAG_READBACK_OK
            | CYW43_RX_IDLE_TRACE_FIFO_FLAG_READBACK_MATCH)
        == (CYW43_RX_IDLE_TRACE_FIFO_FLAG_SET_OK
            | CYW43_RX_IDLE_TRACE_FIFO_FLAG_READBACK_OK
            | CYW43_RX_IDLE_TRACE_FIFO_FLAG_READBACK_MATCH)
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_trace_first_nonzero_desc(trace: Cyw43RxIdleTrace) -> &'static str {
    if trace.first_nonzero_offset == u16::MAX {
        "none"
    } else {
        "present"
    }
}

#[cfg(feature = "kernel")]
fn cyw43_completion_rx_idle_trace(
    contract: DriverTaskContract,
    completion: DriverTaskCompletionRecord,
) -> Option<Cyw43RxIdleTrace> {
    let bytes = crate::hal::driver_task::driver_task_ring_frame_bytes(contract, completion.frame)?;
    let trace = cyw43_rx_idle_trace(bytes)?;
    cache_cyw43_dpc_client_counters(trace);
    Some(trace)
}

#[cfg(feature = "kernel")]
fn cyw43_rx_source_result(result: u32) -> Option<Cyw43RxSourceResult> {
    if result & DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_MAGIC == 0 {
        return None;
    }
    Some(Cyw43RxSourceResult {
        probe_len: (result & DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_PROBE_LEN_MASK) as u16,
        interrupt_enable: ((result & DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_IEN_MASK)
            >> DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_IEN_SHIFT) as u8,
        frame_indicated: result & DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_FRAME_INDICATED != 0,
        host_interrupt: result & DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_HOST_INTERRUPT != 0,
        card_interrupt: result & DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_CARD_INTERRUPT != 0,
        function2_ready: result & DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_FUNCTION2_READY != 0,
        passive: result & DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_PASSIVE != 0,
        cached: result & DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_CACHED != 0,
    })
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_source_mode(source: Option<Cyw43RxSourceResult>) -> &'static str {
    match source {
        Some(source) if source.passive => "passive-sdio-bus-link",
        Some(source) if source.cached => "owner-card-sampled-cached",
        Some(_) => "owner-card-sampled",
        None => "unreported",
    }
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_source_is_passive(source: Option<Cyw43RxSourceResult>) -> bool {
    match source {
        Some(source) => source.passive,
        None => false,
    }
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_source_owner_state_missing(source: Option<Cyw43RxSourceResult>) -> bool {
    match source {
        Some(source) => {
            !source.passive
                && (!source.function2_ready || source.interrupt_enable != CYW43_SDIO_EXPECTED_IENX)
        }
        None => false,
    }
}

#[cfg(feature = "kernel")]
const fn cyw43_rx_source_asserts_pending_frame(source: Cyw43RxSourceResult) -> bool {
    !source.passive
        && !source.cached
        && source.function2_ready
        && (source.frame_indicated || source.host_interrupt || source.card_interrupt)
}

#[cfg(feature = "kernel")]
fn cyw43_host_eapol_source_asserted(progress: &Cyw43HostEapolProgress) -> bool {
    if let Some(source) = progress.last_rx_source {
        if cyw43_rx_source_asserts_pending_frame(source) {
            return true;
        }
    }
    if let Some(source) = progress.last_control_rx_source {
        if cyw43_rx_source_asserts_pending_frame(source) {
            return true;
        }
    }
    cyw43_rx_source_result(progress.last_rx_trace.source_result)
        .is_some_and(cyw43_rx_source_asserts_pending_frame)
        || cyw43_rx_source_result(progress.last_control_rx_trace.source_result)
            .is_some_and(cyw43_rx_source_asserts_pending_frame)
        || cyw43_rx_trace_source_asserts_pending_frame(progress.last_rx_trace)
        || cyw43_rx_trace_source_asserts_pending_frame(progress.last_control_rx_trace)
}

#[cfg(feature = "kernel")]
fn cyw43_rx_idle_trace_has_service_activity(trace: Cyw43RxIdleTrace) -> bool {
    trace.valid
        && (trace.queue_depth != 0
            || trace.rframe_len != 0
            || trace.service_progress != 0
            || trace.service_credit_observations != 0
            || trace.rx_max_drained_per_turn != 0
            || trace.rx_drain_budget_hits != 0
            || trace.rx_queue_overflows != 0
            || cyw43_rx_trace_source_asserts_pending_frame(trace))
}

#[cfg(feature = "kernel")]
fn cyw43_poll_completion_made_service_progress(
    completion: DriverTaskCompletionRecord,
    trace: Option<Cyw43RxIdleTrace>,
) -> bool {
    (completion.code == DriverTaskCompletionCode::Progress.as_u16() && completion.result != 0)
        || trace.is_some_and(cyw43_rx_idle_trace_has_service_activity)
}

