struct Cyw43HostEapolStatusThrottle {
    last_key: Option<Cyw43HostEapolStatusKey>,
    suppressed: u32,
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Cyw43HostEapolStatusLogDecision {
    emit_full: bool,
    suppressed_before: u32,
}

#[cfg(feature = "kernel")]
const CYW43_HOST_EAPOL_STATUS_SUPPRESS_MILESTONE: u32 = 64;

#[cfg(feature = "kernel")]
static CYW43_HOST_EAPOL_STATUS_THROTTLE: Mutex<Cyw43HostEapolStatusThrottle> =
    Mutex::new(Cyw43HostEapolStatusThrottle {
        last_key: None,
        suppressed: 0,
    });

#[cfg(feature = "kernel")]
fn cyw43_host_eapol_status_suppressible(status: &'static str) -> bool {
    matches!(status, "pending" | "required" | "secure-awaiting-carrier")
}

#[cfg(feature = "kernel")]
fn cyw43_host_eapol_status_key(
    status: &'static str,
    reason: &'static str,
    next_action: &'static str,
    starts: u32,
    tx_retries: u32,
    progress: &Cyw43HostEapolProgress,
) -> Cyw43HostEapolStatusKey {
    Cyw43HostEapolStatusKey {
        status,
        reason,
        next_action,
        starts,
        tx_retries,
        data_rx: progress.data_rx,
        eapol_rx: progress.eapol_rx,
        non_eapol_rx: progress.non_eapol_rx,
        event_rx: progress.event_rx,
        control_rx: progress.control_rx,
        associated: progress.associated,
        link_up: progress.link_up,
        assoc_event: progress.association_event.unwrap_or("none"),
        assoc_probe: progress.assoc_probe_status.unwrap_or("none"),
        assoc_probe_result: progress.assoc_probe_result,
        assoc_join_rescue: progress.assoc_join_rescue_attempted,
        firstread_class: cyw43_host_eapol_firstread_class(progress),
        rx_idle_detail: progress.last_rx_idle_detail,
        rx_idle_result: progress.last_rx_idle_result,
        control_rx_idle_detail: progress.last_control_rx_idle_detail,
        control_rx_idle_result: progress.last_control_rx_idle_result,
        rx_source: progress.last_rx_source,
        control_rx_source: progress.last_control_rx_source,
        rx_trace: progress.last_rx_trace.into(),
        control_rx_trace: progress.last_control_rx_trace.into(),
        eapol_error: progress.eapol_error,
        last_assoc_event_type: progress.last_assoc_event_type,
        last_assoc_event_status: progress.last_assoc_event_status,
        last_assoc_event_reason: progress.last_assoc_event_reason,
        last_assoc_event_auth: progress.last_assoc_event_auth,
        last_flags: progress.last_flags,
        last_len: progress.last_len,
        last_ethertype: progress.last_ethertype,
        last_ethertype_valid: progress.last_ethertype_valid,
    }
}

#[cfg(feature = "kernel")]
fn cyw43_host_eapol_status_log_decision(
    throttle: &mut Cyw43HostEapolStatusThrottle,
    key: Cyw43HostEapolStatusKey,
) -> Cyw43HostEapolStatusLogDecision {
    if cyw43_host_eapol_status_suppressible(key.status) && throttle.last_key == Some(key) {
        let next_suppressed = throttle.suppressed.saturating_add(1);
        if next_suppressed < CYW43_HOST_EAPOL_STATUS_SUPPRESS_MILESTONE {
            throttle.suppressed = next_suppressed;
            return Cyw43HostEapolStatusLogDecision {
                emit_full: false,
                suppressed_before: 0,
            };
        }
    }

    let suppressed_before = throttle.suppressed;
    throttle.last_key = Some(key);
    throttle.suppressed = 0;
    Cyw43HostEapolStatusLogDecision {
        emit_full: true,
        suppressed_before,
    }
}

#[cfg(feature = "kernel")]
fn clear_cyw43_host_eapol_status_throttle() {
    *CYW43_HOST_EAPOL_STATUS_THROTTLE.lock() = Cyw43HostEapolStatusThrottle::default();
}

#[cfg(feature = "kernel")]
impl Cyw43HostEapolProgress {
    fn record_data_frame(&mut self, flags: u16, len: usize, ethertype: Option<u16>) {
        self.data_rx = self.data_rx.saturating_add(1);
        self.last_flags = flags;
        self.last_len = len.min(u16::MAX as usize) as u16;
        if let Some(ethertype) = ethertype {
            self.last_ethertype = ethertype;
            self.last_ethertype_valid = true;
            if ethertype == ETH_P_EAPOL {
                self.eapol_rx = self.eapol_rx.saturating_add(1);
            } else {
                self.non_eapol_rx = self.non_eapol_rx.saturating_add(1);
            }
        } else {
            self.last_ethertype = 0;
            self.last_ethertype_valid = false;
            self.non_eapol_rx = self.non_eapol_rx.saturating_add(1);
        }
    }

    fn record_control_frame(&mut self, flags: u16, len: usize) {
        self.control_rx = self.control_rx.saturating_add(1);
        self.last_flags = flags;
        self.last_len = len.min(u16::MAX as usize) as u16;
    }

    fn record_event_frame(
        &mut self,
        flags: u16,
        len: usize,
        event: Cyw43EventFrame,
        poll: usize,
        apply_state: bool,
    ) {
        self.event_rx = self.event_rx.saturating_add(1);
        self.last_flags = flags;
        self.last_len = len.min(u16::MAX as usize) as u16;
        if apply_state {
            if cyw43_host_eapol_join_event_type(event.event_type) {
                self.last_assoc_event_type = event.event_type;
                self.last_assoc_event_status = event.status;
                self.last_assoc_event_reason = event.reason;
                self.last_assoc_event_auth = event.auth_type;
                if event.event_type == CYW43_EVENT_AUTH
                    && event.status == CYW43_EVENT_STATUS_TIMEOUT
                {
                    self.auth_timeout_seen = true;
                }
                if event.event_type == CYW43_EVENT_SET_SSID
                    && event.status != CYW43_EVENT_STATUS_SUCCESS
                {
                    self.set_ssid_failure_seen = true;
                }
            }
            if let Some(associated) = cyw43_event_association_state_update(event) {
                self.associated = associated;
            }
            if let Some(link_up) = cyw43_event_link_state_update(event) {
                self.link_up = link_up;
            }
            if let Some(label) = cyw43_host_eapol_disconnect_event_label(event) {
                self.association_event = Some(label);
                self.association_poll = (poll as u32).saturating_add(1);
            } else if self.association_event.is_none() {
                if let Some(label) = cyw43_host_eapol_post_assoc_event_label(event, self.associated)
                {
                    self.association_event = Some(label);
                    self.association_poll = (poll as u32).saturating_add(1);
                }
            }
            CYW43_ASSOCIATED.store(if self.associated { 1 } else { 0 }, Ordering::Release);
            CYW43_LINK_UP.store(if self.link_up { 1 } else { 0 }, Ordering::Release);
        }
    }

    fn record_empty_poll(&mut self) {
        self.empty_polls = self.empty_polls.saturating_add(1);
    }

    fn record_assoc_probe(&mut self, status: &'static str, result: u32) {
        self.assoc_probe_status = Some(status);
        self.assoc_probe_result = result;
        if status == "not-associated" {
            self.assoc_probe_not_associated = true;
        } else if status == "valid-bssid" {
            self.assoc_probe_not_associated = false;
        }
    }

    fn record_assoc_join_rescue_attempt(&mut self) {
        self.assoc_join_rescue_attempted = true;
    }

    fn record_eapol_error(&mut self, error: &'static str) {
        self.eapol_error = Some(error);
    }

    fn record_eapol_association_proof(&mut self, label: &'static str, poll: usize) {
        self.associated = true;
        if self.association_event.is_none() {
            self.association_event = Some(label);
            self.association_poll = poll.min(u32::MAX as usize) as u32;
        }
        CYW43_ASSOCIATED.store(1, Ordering::Release);
    }

    fn record_rx_idle_completion(&mut self, completion: DriverTaskCompletionRecord) {
        self.record_rx_idle_completion_with_trace(completion, None, 0, 0);
    }

    fn record_rx_idle_completion_with_trace(
        &mut self,
        completion: DriverTaskCompletionRecord,
        trace: Option<Cyw43RxIdleTrace>,
        poll: usize,
        flags: u16,
    ) {
        self.last_rx_idle_detail = completion.detail;
        self.last_rx_idle_result = completion.result;
        self.last_rx_trace = trace.unwrap_or_default();
        self.last_rx_probe_poll = poll.min(u32::MAX as usize) as u32;
        self.last_rx_probe_flags = flags;
        self.last_rx_source = if completion.detail
            == DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_EMPTY
            || completion.detail
                == DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_SOURCE_ASSERTED_EMPTY
        {
            cyw43_rx_source_result(completion.result)
        } else {
            None
        };
        match completion.detail {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_EMPTY
            | DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_SOURCE_ASSERTED_EMPTY => {
                self.rx_firstread_attempts = self.rx_firstread_attempts.saturating_add(1);
                self.rx_firstread_empty = self.rx_firstread_empty.saturating_add(1);
            }
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_INVALID_SDPCM => {
                self.rx_firstread_attempts = self.rx_firstread_attempts.saturating_add(1);
                self.rx_firstread_invalid = self.rx_firstread_invalid.saturating_add(1);
            }
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_FAILED => {
                self.rx_firstread_attempts = self.rx_firstread_attempts.saturating_add(1);
                self.rx_firstread_failed = self.rx_firstread_failed.saturating_add(1);
            }
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_REMAINDER_FAILED
            | DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_REMAINDER_TOO_LARGE => {
                self.rx_firstread_attempts = self.rx_firstread_attempts.saturating_add(1);
                self.rx_firstread_remainder_failed =
                    self.rx_firstread_remainder_failed.saturating_add(1);
            }
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_NEXT_FRAME_READAHEAD_RETRY => {
                self.rx_firstread_failed = self.rx_firstread_failed.saturating_add(1);
            }
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_SDPCM_DECODE_MISS => {
                self.rx_firstread_decode_miss = self.rx_firstread_decode_miss.saturating_add(1);
            }
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_F2_READ_FAILED => {
                self.rx_firstread_failed = self.rx_firstread_failed.saturating_add(1);
            }
            _ => {}
        }
    }

    fn record_control_rx_idle_completion(&mut self, completion: DriverTaskCompletionRecord) {
        self.record_control_rx_idle_completion_with_trace(completion, None, 0, 0);
    }

    fn record_control_rx_idle_completion_with_trace(
        &mut self,
        completion: DriverTaskCompletionRecord,
        trace: Option<Cyw43RxIdleTrace>,
        poll: usize,
        flags: u16,
    ) {
        self.last_control_rx_idle_detail = completion.detail;
        self.last_control_rx_idle_result = completion.result;
        self.last_control_rx_trace = trace.unwrap_or_default();
        self.last_control_rx_probe_poll = poll.min(u32::MAX as usize) as u32;
        self.last_control_rx_probe_flags = flags;
        self.last_control_rx_source = if completion.detail
            == DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_EMPTY
            || completion.detail
                == DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_SOURCE_ASSERTED_EMPTY
        {
            cyw43_rx_source_result(completion.result)
        } else {
            None
        };
        match completion.detail {
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_EMPTY
            | DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_SOURCE_ASSERTED_EMPTY => {
                self.control_rx_firstread_attempts =
                    self.control_rx_firstread_attempts.saturating_add(1);
                self.control_rx_firstread_empty = self.control_rx_firstread_empty.saturating_add(1);
            }
            DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_FAILED
            | DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_INVALID_SDPCM
            | DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_REMAINDER_FAILED
            | DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_REMAINDER_TOO_LARGE
            | DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_NEXT_FRAME_READAHEAD_RETRY
            | DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_SDPCM_DECODE_MISS
            | DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_F2_READ_FAILED => {
                self.control_rx_firstread_attempts =
                    self.control_rx_firstread_attempts.saturating_add(1);
                self.control_rx_firstread_failed =
                    self.control_rx_firstread_failed.saturating_add(1);
            }
            _ => {}
        }
    }
}

#[cfg(feature = "kernel")]
fn cyw43_pending_host_eapol_event_matches(
    pending: Cyw43PendingHostEapolEvent,
    next: Cyw43PendingHostEapolEvent,
) -> bool {
    pending.generation == next.generation
        && pending.state_admitted == next.state_admitted
        && pending.event.event_type == next.event.event_type
        && pending.event.status == next.event.status
        && pending.event.reason == next.event.reason
        && pending.event.auth_type == next.event.auth_type
        && pending.event.addr == next.event.addr
}

#[cfg(feature = "kernel")]
fn cyw43_store_pending_host_eapol_event_record(next: Cyw43PendingHostEapolEvent) {
    let mut queue = CYW43_HOST_EAPOL_PENDING_EVENTS.lock();
    let len = queue.len();
    let mut retained =
        heapless::Deque::<Cyw43PendingHostEapolEvent, CYW43_HOST_EAPOL_PENDING_EVENT_CAP>::new();

    for _ in 0..len {
        let Some(pending) = queue.pop_front() else {
            break;
        };
        if !cyw43_pending_host_eapol_event_matches(pending, next) {
            let _ = retained.push_back(pending);
        }
    }
    while let Some(pending) = retained.pop_front() {
        let _ = queue.push_back(pending);
    }
    if queue.len() == CYW43_HOST_EAPOL_PENDING_EVENT_CAP {
        let _ = queue.pop_front();
    }
    let _ = queue.push_back(next);
}

#[cfg(feature = "kernel")]
fn cyw43_store_pending_host_eapol_event(
    contract: DriverTaskContract,
    stage: &'static str,
    flags: u16,
    len: usize,
    event: Cyw43EventFrame,
) {
    let generation = CYW43_CONNECTION_EPOCH.load(Ordering::Acquire);
    let event_belongs = cyw43_association_events_armed_for_generation(generation);
    let carrier_loss_applies = cyw43_carrier_loss_applies_to_armed_generation(event);
    record_cyw43_association_event_outcome(event, stage);
    let (associated_update, link_update) = if event_belongs {
        (
            cyw43_event_association_state_update(event),
            cyw43_event_link_state_update(event),
        )
    } else {
        (None, None)
    };
    let mut associated = CYW43_ASSOCIATED.load(Ordering::Acquire) != 0;
    let mut link_up = CYW43_LINK_UP.load(Ordering::Acquire) != 0;
    if let Some(next_associated) = associated_update {
        associated = next_associated;
    }
    if let Some(next_link_up) = link_update {
        link_up = next_link_up;
    }
    CYW43_ASSOCIATED.store(if associated { 1 } else { 0 }, Ordering::Release);
    CYW43_LINK_UP.store(if link_up { 1 } else { 0 }, Ordering::Release);
    if associated_update.is_some() || link_update.is_some() {
        record_cyw43_association_progress();
    }
    if carrier_loss_applies {
        request_cyw43_host_eapol_reauthentication(cyw43_host_eapol_action_pending_nonblocking());
    } else if matches!(associated_update, Some(true)) {
        // A positive LINK event is link telemetry, not proof that the
        // current join transaction completed. Keep the rejoin token until
        // SET_SSID proves the open or host-EAPOL join transaction.
        clear_cyw43_rejoin_pending_for_epoch(CYW43_CONNECTION_EPOCH.load(Ordering::Acquire));
    }
    cyw43_admit_open_data_if_ready(contract, "cyw43-open-association-event");

    let event_label = cyw43_host_eapol_event_trace_label(event);
    let relevant = associated_update.is_some()
        || link_update.is_some()
        || cyw43_host_eapol_association_event_label(event).is_some();
    if relevant {
        cyw43_store_pending_host_eapol_event_record(Cyw43PendingHostEapolEvent {
            generation,
            state_admitted: event_belongs,
            event,
            flags,
            len: len.min(u16::MAX as usize) as u16,
        });
    }
    emit_cyw43_host_eapol_event_capture(contract, stage, flags, len, event, event_label, relevant);
}

#[cfg(feature = "kernel")]
fn keep_cyw43_reauthentication_pending() {
    let open_network = CYW43_OPEN_NETWORK_ACTIVE.load(Ordering::Acquire) != 0;
    CYW43_CONTROL_PLANE_READY.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SECURE.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_REQUIRED.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_ACTIVE.store(if open_network { 0 } else { 1 }, Ordering::Release);
    CYW43_POST_SECURE_DATA_RX_ADMITTED.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SCB_AUTH_ATTEMPTED.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SCB_AUTHORIZED.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SCB_AUTH_MAC_HI.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SCB_AUTH_MAC_LO.store(0, Ordering::Release);
    CYW43_ASSIGNED_IPV4_BE.store(0, Ordering::Release);
    clear_cyw43_unproven_tx_window();
}

#[cfg(feature = "kernel")]
const fn cyw43_fault_invalidates_root_generation(detail: u16) -> bool {
    matches!(
        detail,
        CYW43_CONTROL_FRAME_DETAIL | CYW43_ETH_TX_DETAIL | CYW43_TRANSPORT_BUS_LINK_MISSING_DETAIL
    )
}

/// Return the current root-visible CYW43 connection generation.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_connection_generation() -> u32 {
    CYW43_CONNECTION_EPOCH.load(Ordering::Acquire)
}

#[cfg(feature = "kernel")]
fn fence_cyw43_root_admission_for_recovery() {
    // This boundary is safe while a steady-path mutex is held: it touches only
    // atomics. Mutex-owned sessions, queues, and cursors are cleared later by
    // the retained supervisor after the outer EventPump turn has unwound.
    CYW43_LINKED_RUNTIME_READY.store(0, Ordering::Release);
    CYW43_CONTROL_PLANE_READY.store(0, Ordering::Release);
    CYW43_ASSOCIATED.store(0, Ordering::Release);
    CYW43_LINK_UP.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_ACTIVE.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_REQUIRED.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SECURE.store(0, Ordering::Release);
    CYW43_OPEN_NETWORK_ACTIVE.store(0, Ordering::Release);
    CYW43_POST_SECURE_DATA_RX_ADMITTED.store(0, Ordering::Release);
    CYW43_PRIMARY_BSSCFG_JOIN_READY.store(0, Ordering::Release);
    CYW43_PRIMARY_BSSCFG_JOIN_EPOCH_TOKEN.store(0, Ordering::Release);
    CYW43_POST_ASSOC_BSSID_REFRESH_EPOCH_TOKEN.store(0, Ordering::Release);
    CYW43_POST_ASSOC_BSSID_REFRESH_FAILURE_EPOCH_TOKEN.store(0, Ordering::Release);
    CYW43_ASSIGNED_IPV4_BE.store(0, Ordering::Release);
}

#[cfg(feature = "kernel")]
fn latch_cyw43_deferred_recovery(
    generation: u32,
    cause: Cyw43RecoveryCause,
    descriptor: DriverRuntimeCyw43CommandDescriptor,
    payload_digest: Cyw43PayloadDigest,
    ticket_id: u64,
    detail: u16,
    sequence: u32,
) -> Option<Cyw43DeferredRecovery> {
    latch_cyw43_deferred_recovery_for_owner_subphase(
        generation,
        generation,
        cause,
        cause.diagnostic_subphase(),
        descriptor,
        payload_digest,
        ticket_id,
        detail,
        0,
        sequence,
        false,
    )
}

#[cfg(feature = "kernel")]
fn cyw43_deferred_recovery_diagnostic_gate(
    cause: Cyw43RecoveryCause,
    subphase: &'static str,
) -> u8 {
    if cause == Cyw43RecoveryCause::Association
        || subphase.starts_with("cyw43-association-")
        || subphase.starts_with("cyw43-host-eapol-")
    {
        8
    } else {
        0
    }
}

#[cfg(feature = "kernel")]
fn cyw43_deferred_recovery_diagnostic_record(
    recovery: Cyw43DeferredRecovery,
    subphase: &'static str,
) -> Cyw43DeferredRecoveryDiagnostic {
    let descriptor = recovery.descriptor;
    Cyw43DeferredRecoveryDiagnostic {
        cause: recovery.cause.diagnostic_label(),
        subphase,
        generation: recovery.generation,
        owner_generation: recovery.owner_generation,
        descriptor_op: descriptor.op,
        descriptor_flags: descriptor.flags,
        descriptor_target_addr: descriptor.target_addr,
        descriptor_payload_offset: descriptor.payload_offset,
        descriptor_payload_len: descriptor.payload_len,
        descriptor_total_len: descriptor.total_len,
        descriptor_arg0: descriptor.arg0,
        descriptor_arg1: descriptor.arg1,
        ticket_id: recovery.ticket_id,
        completion_detail: recovery.detail,
        completion_result: recovery.result,
        completion_sequence: recovery.sequence,
        terminal_observed: recovery.terminal_observed,
        turn_id: recovery.turn_id,
        gate: cyw43_deferred_recovery_diagnostic_gate(recovery.cause, subphase),
    }
}

#[cfg(feature = "kernel")]
fn retain_first_cyw43_deferred_recovery_diagnostic(
    recovery: Cyw43DeferredRecovery,
    subphase: &'static str,
) {
    let mut slot = CYW43_FIRST_DEFERRED_RECOVERY_DIAGNOSTIC.lock();
    if let Some(existing) = *slot {
        let generic_pair_placeholder = !existing.terminal_observed
            && existing.cause == Cyw43RecoveryCause::PairSignal.diagnostic_label()
            && existing.descriptor_op == 0
            && existing.ticket_id == 0
            && existing.completion_detail == 0
            && existing.completion_result == 0
            && existing.completion_sequence == 0;
        let same_descriptor = existing.descriptor_op == 0
            || (existing.descriptor_op == recovery.descriptor.op
                && existing.descriptor_flags == recovery.descriptor.flags
                && existing.descriptor_target_addr == recovery.descriptor.target_addr
                && existing.descriptor_payload_offset == recovery.descriptor.payload_offset
                && existing.descriptor_payload_len == recovery.descriptor.payload_len
                && existing.descriptor_total_len == recovery.descriptor.total_len
                && existing.descriptor_arg0 == recovery.descriptor.arg0
                && existing.descriptor_arg1 == recovery.descriptor.arg1);
        let exact_terminal_refinement = !existing.terminal_observed
            && recovery.terminal_observed
            && existing.generation == recovery.generation
            && existing.owner_generation == recovery.owner_generation
            && (existing.ticket_id == 0 || existing.ticket_id == recovery.ticket_id)
            && (existing.completion_sequence == 0
                || existing.completion_sequence == recovery.sequence)
            && same_descriptor;
        let generic_terminal_refinement = generic_pair_placeholder
            && existing.generation == recovery.generation
            && recovery.terminal_observed
            && recovery.ticket_id != 0
            && recovery.sequence != 0;
        let generic_owner_refinement = generic_pair_placeholder
            && existing.generation == recovery.generation
            && recovery.descriptor.op != 0;
        if !exact_terminal_refinement && !generic_terminal_refinement && !generic_owner_refinement {
            return;
        }
    }
    *slot = Some(cyw43_deferred_recovery_diagnostic_record(
        recovery, subphase,
    ));
}

#[cfg(feature = "kernel")]
const fn cyw43_active_parent_recovery_cause(
    request: Option<u32>,
    issued: bool,
) -> Cyw43RecoveryCause {
    if cyw43_child_action_accepted(request, issued) {
        Cyw43RecoveryCause::IssuedOwnerUnknown
    } else {
        Cyw43RecoveryCause::PairSignal
    }
}

#[cfg(feature = "kernel")]
fn retain_active_cyw43_recovery_owner_diagnostic(current_generation: u32) {
    if let Some(existing) = *CYW43_FIRST_DEFERRED_RECOVERY_DIAGNOSTIC.lock() {
        let generic_pair_placeholder = !existing.terminal_observed
            && existing.cause == Cyw43RecoveryCause::PairSignal.diagnostic_label()
            && existing.descriptor_op == 0
            && existing.ticket_id == 0
            && existing.completion_detail == 0
            && existing.completion_result == 0
            && existing.completion_sequence == 0;
        if !generic_pair_placeholder {
            return;
        }
    }
    if let Some(owner) =
        (*CYW43_LOGICAL_CONTROL_OWNER.lock()).filter(|owner| owner.generation == current_generation)
    {
        retain_first_cyw43_deferred_recovery_diagnostic(
            Cyw43DeferredRecovery {
                generation: current_generation,
                owner_generation: owner.generation,
                cause: Cyw43RecoveryCause::PairSignal,
                descriptor: owner.descriptor,
                payload_digest: owner.payload_digest,
                ticket_id: u64::from(owner.descriptor.arg1),
                detail: 0,
                result: 0,
                sequence: 0,
                terminal_observed: false,
                turn_id: cyw43_outer_event_turn_id(),
            },
            owner.stage,
        );
        return;
    }
    if let Some(join) = (*CYW43_ASSOCIATION_JOIN_DIAGNOSTIC.lock())
        .filter(|join| join.generation == current_generation)
    {
        retain_first_cyw43_deferred_recovery_diagnostic(
            Cyw43DeferredRecovery {
                generation: current_generation,
                owner_generation: join.generation,
                // This branch observes Join parent context after a
                // runtime-origin pair signal. A Join-owned failure uses the
                // ordinary deferred-ticket path; without that ticket the
                // causal label must remain PairSignal.
                cause: Cyw43RecoveryCause::PairSignal,
                descriptor: join.descriptor,
                payload_digest: Cyw43PayloadDigest {
                    first: 0,
                    last: 0,
                    xor: 0,
                    sum: 0,
                },
                ticket_id: join.ticket_id,
                detail: join.completion_detail,
                result: join.completion_result,
                sequence: if join.completion_sequence != 0 {
                    join.completion_sequence
                } else {
                    join.request.unwrap_or_default()
                },
                terminal_observed: join.terminal_observed,
                turn_id: cyw43_outer_event_turn_id(),
            },
            CYW43_ASSOCIATION_JOIN_STAGE,
        );
        return;
    }
    if let Some(pending) = (*CYW43_PENDING_PROMPT_POLL.lock())
        .filter(|pending| pending.generation == current_generation)
    {
        // The parent cursor existed when the runtime signalled pair recovery,
        // but only the accepted-child predicate may upgrade its cause to
        // issued-owner-unknown.
        let cause = cyw43_active_parent_recovery_cause(pending.request, pending.issued);
        retain_first_cyw43_deferred_recovery_diagnostic(
            Cyw43DeferredRecovery {
                generation: current_generation,
                owner_generation: pending.generation,
                cause,
                descriptor: pending.descriptor,
                payload_digest: Cyw43PayloadDigest {
                    first: 0,
                    last: 0,
                    xor: 0,
                    sum: 0,
                },
                ticket_id: pending.ticket_id,
                detail: 0,
                result: 0,
                sequence: pending.request.unwrap_or_default(),
                terminal_observed: false,
                turn_id: cyw43_outer_event_turn_id(),
            },
            pending.owner.stage(),
        );
        return;
    }
    let session_owner = {
        let session = CYW43_HOST_EAPOL_SESSION.lock();
        session.as_ref().and_then(|session| {
            if let Some(pending) = session
                .pending_key_install
                .as_ref()
                .filter(|pending| pending.connection_epoch == current_generation)
            {
                let retained_terminal = pending.last_completion.filter(|completion| {
                    cyw43_control_exchange_completion_is_proven_terminal(*completion)
                        && pending
                            .request
                            .is_none_or(|request| request == completion.sequence)
                });
                let (detail, result, sequence) = retained_terminal
                    .map_or((0, 0, 0), |completion| {
                        (completion.detail, completion.result, completion.sequence)
                    });
                Some((
                    pending.stage,
                    pending.connection_epoch,
                    cyw43_active_parent_recovery_cause(pending.request, pending.issued),
                    pending.tx_descriptor,
                    u64::from(pending.id),
                    detail,
                    result,
                    if sequence != 0 {
                        sequence
                    } else {
                        pending.request.unwrap_or_default()
                    },
                    retained_terminal.is_some(),
                ))
            } else if let Some(pending) = session
                .pending_tx_submit
                .as_ref()
                .filter(|pending| pending.connection_epoch == current_generation)
            {
                Some((
                    pending.stage,
                    pending.connection_epoch,
                    cyw43_active_parent_recovery_cause(pending.request, pending.issued),
                    cyw43_data_tx_descriptor(usize::from(pending.len)),
                    pending.ticket_id,
                    0,
                    0,
                    pending.request.unwrap_or_default(),
                    false,
                ))
            } else {
                session.pending_tx_drain.as_ref().and_then(|pending| {
                    (pending.connection_epoch == current_generation).then_some((
                        pending.stage,
                        pending.connection_epoch,
                        // A TX-drain cursor has not issued its next child poll;
                        // it is parent context observed at the pair signal.
                        Cyw43RecoveryCause::PairSignal,
                        DriverRuntimeCyw43CommandDescriptor {
                            op: DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL,
                            flags: cyw43_control_split_poll_flags(pending.polls.saturating_add(1)),
                            ..DriverRuntimeCyw43CommandDescriptor::empty()
                        },
                        pending.ticket_id,
                        0,
                        0,
                        0,
                        false,
                    ))
                })
            }
        })
    };
    if let Some((
        subphase,
        owner_generation,
        cause,
        descriptor,
        ticket_id,
        detail,
        result,
        sequence,
        terminal_observed,
    )) = session_owner
    {
        retain_first_cyw43_deferred_recovery_diagnostic(
            Cyw43DeferredRecovery {
                generation: current_generation,
                owner_generation,
                cause,
                descriptor,
                payload_digest: Cyw43PayloadDigest {
                    first: 0,
                    last: 0,
                    xor: 0,
                    sum: 0,
                },
                ticket_id,
                detail,
                result,
                sequence,
                terminal_observed,
                turn_id: cyw43_outer_event_turn_id(),
            },
            subphase,
        );
    }
}

#[cfg(feature = "kernel")]
#[allow(clippy::too_many_arguments)]
fn latch_cyw43_deferred_recovery_for_owner_subphase(
    generation: u32,
    owner_generation: u32,
    cause: Cyw43RecoveryCause,
    subphase: &'static str,
    descriptor: DriverRuntimeCyw43CommandDescriptor,
    payload_digest: Cyw43PayloadDigest,
    ticket_id: u64,
    detail: u16,
    result: u32,
    sequence: u32,
    terminal_observed: bool,
) -> Option<Cyw43DeferredRecovery> {
    let current_generation = CYW43_CONNECTION_EPOCH.load(Ordering::Acquire);
    if generation != current_generation {
        // A completion owned by an older generation is diagnostic only. It
        // cannot fence, clear, restart, or otherwise mutate the replacement.
        return None;
    }
    let proposed = Cyw43DeferredRecovery {
        generation,
        owner_generation,
        cause,
        descriptor,
        payload_digest,
        ticket_id,
        detail,
        result,
        sequence,
        terminal_observed,
        turn_id: cyw43_outer_event_turn_id(),
    };
    let retained = {
        let mut slot = CYW43_DEFERRED_RECOVERY.lock();
        if let Some(existing) = slot.filter(|ticket| ticket.generation == current_generation) {
            let generic_pair_placeholder = !existing.terminal_observed
                && existing.cause == Cyw43RecoveryCause::PairSignal
                && existing.descriptor == DriverRuntimeCyw43CommandDescriptor::empty()
                && existing.ticket_id == 0
                && existing.detail == 0
                && existing.result == 0
                && existing.sequence == 0;
            let same_descriptor = existing.descriptor
                == DriverRuntimeCyw43CommandDescriptor::empty()
                || cyw43_retained_descriptor_fingerprint_matches(
                    existing.descriptor,
                    proposed.descriptor,
                );
            let exact_terminal_refinement = !existing.terminal_observed
                && proposed.terminal_observed
                && existing.owner_generation == proposed.owner_generation
                && (existing.ticket_id == 0 || existing.ticket_id == proposed.ticket_id)
                && (existing.sequence == 0 || existing.sequence == proposed.sequence)
                && same_descriptor;
            let generic_terminal_refinement = generic_pair_placeholder
                && proposed.terminal_observed
                && proposed.ticket_id != 0
                && proposed.sequence != 0;
            if exact_terminal_refinement || generic_terminal_refinement {
                *slot = Some(proposed);
                proposed
            } else {
                // A typed nonterminal or terminal record for a generation is
                // immutable. Only the completely generic pair placeholder may
                // adopt a freshly revalidated exact issued-owner identity.
                existing
            }
        } else {
            *slot = Some(proposed);
            proposed
        }
    };
    if retained == proposed {
        retain_first_cyw43_deferred_recovery_diagnostic(retained, subphase);
    }
    fence_cyw43_root_admission_for_recovery();
    crate::hal::driver_task::request_cyw43_sdio_pair_restart();
    Some(retained)
}

#[cfg(feature = "kernel")]
fn refine_cyw43_pair_signal_with_exact_issued_owner(
    proposed: Cyw43DeferredRecovery,
    subphase: &'static str,
) -> Option<Cyw43DeferredRecovery> {
    let current_generation = CYW43_CONNECTION_EPOCH.load(Ordering::Acquire);
    if proposed.generation != current_generation
        || proposed.cause != Cyw43RecoveryCause::IssuedOwnerUnknown
        || proposed.terminal_observed
        || proposed.ticket_id == 0
        || proposed.sequence == 0
    {
        return None;
    }
    let (retained, replaced) = {
        let mut slot = CYW43_DEFERRED_RECOVERY.lock();
        if let Some(existing) = slot.filter(|ticket| ticket.generation == current_generation) {
            let generic_pair_placeholder = !existing.terminal_observed
                && existing.cause == Cyw43RecoveryCause::PairSignal
                && existing.descriptor == DriverRuntimeCyw43CommandDescriptor::empty()
                && existing.ticket_id == 0
                && existing.detail == 0
                && existing.result == 0
                && existing.sequence == 0;
            if generic_pair_placeholder {
                *slot = Some(proposed);
                (proposed, true)
            } else {
                (existing, false)
            }
        } else {
            *slot = Some(proposed);
            (proposed, true)
        }
    };
    if replaced {
        let mut diagnostic = CYW43_FIRST_DEFERRED_RECOVERY_DIAGNOSTIC.lock();
        let replace_diagnostic = diagnostic.is_none_or(|existing| {
            existing.generation == proposed.generation
                && !existing.terminal_observed
                && existing.cause == Cyw43RecoveryCause::PairSignal.diagnostic_label()
                && existing.descriptor_op == 0
                && existing.ticket_id == 0
                && existing.completion_detail == 0
                && existing.completion_result == 0
                && existing.completion_sequence == 0
        });
        if replace_diagnostic {
            *diagnostic = Some(cyw43_deferred_recovery_diagnostic_record(
                proposed, subphase,
            ));
        }
    }
    fence_cyw43_root_admission_for_recovery();
    crate::hal::driver_task::request_cyw43_sdio_pair_restart();
    Some(retained)
}

/// Return one passive copy of the first deferred recovery identity.
///
/// Reading this snapshot never consumes the authoritative recovery ticket and
/// never performs linked-runtime, HAL, or register work.
#[cfg(feature = "kernel")]
pub(crate) fn cyw43_deferred_recovery_diagnostic() -> Option<Cyw43DeferredRecoveryDiagnostic> {
    *CYW43_FIRST_DEFERRED_RECOVERY_DIAGNOSTIC.lock()
}

#[cfg(feature = "kernel")]
fn latch_cyw43_pair_recovery(generation: u32, cause: Cyw43RecoveryCause) {
    let _ = latch_cyw43_deferred_recovery(
        generation,
        cause,
        DriverRuntimeCyw43CommandDescriptor::empty(),
        Cyw43PayloadDigest {
            first: 0,
            last: 0,
            xor: 0,
            sum: 0,
        },
        0,
        0,
        0,
    );
}

#[cfg(feature = "kernel")]
fn take_cyw43_deferred_recovery() -> Option<Cyw43DeferredRecovery> {
    CYW43_DEFERRED_RECOVERY.lock().take()
}

#[cfg(feature = "kernel")]
fn invalidate_cyw43_root_generation_for_recovery(expected_generation: u32) -> Option<u32> {
    let next_epoch = expected_generation.wrapping_add(1);
    CYW43_CONNECTION_EPOCH
        .compare_exchange(
            expected_generation,
            next_epoch,
            Ordering::AcqRel,
            Ordering::Acquire,
        )
        .ok()?;
    invalidate_cyw43_data_handoff();
    CYW43_REJOIN_PENDING_EPOCH_TOKEN.store(cyw43_epoch_token(next_epoch), Ordering::Release);
    CYW43_LINKED_RUNTIME_READY.store(0, Ordering::Release);
    CYW43_CONTROL_PLANE_READY.store(0, Ordering::Release);
    CYW43_ASSOCIATED.store(0, Ordering::Release);
    CYW43_LINK_UP.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_RX.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_START.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_M1.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_M2.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_M3.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_M4.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_PTK.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_GTK.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_ACTIVE.store(1, Ordering::Release);
    CYW43_HOST_EAPOL_REQUIRED.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SECURE.store(0, Ordering::Release);
    CYW43_OPEN_NETWORK_ACTIVE.store(0, Ordering::Release);
    CYW43_ASSOCIATION_TERMINAL_FAILURE.store(0, Ordering::Release);
    clear_cyw43_association_event_arm();
    CYW43_DEFERRED_CARRIER_REAUTH_EPOCH_TOKEN.store(0, Ordering::Release);
    CYW43_POST_SECURE_DATA_RX_ADMITTED.store(0, Ordering::Release);
    CYW43_PRIMARY_BSSCFG_JOIN_READY.store(0, Ordering::Release);
    CYW43_PRIMARY_BSSCFG_JOIN_EPOCH_TOKEN.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SCB_AUTH_ATTEMPTED.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SCB_AUTHORIZED.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SCB_AUTH_MAC_HI.store(0, Ordering::Release);
    CYW43_HOST_EAPOL_SCB_AUTH_MAC_LO.store(0, Ordering::Release);
    CYW43_ASSIGNED_IPV4_BE.store(0, Ordering::Release);
    CYW43_POST_DHCP_RX_ANY.store(0, Ordering::Release);
    CYW43_POST_DHCP_RX_UNICAST.store(0, Ordering::Release);
    CYW43_POST_DHCP_RX_ASSIGNED_ARP.store(0, Ordering::Release);
    CYW43_POST_DHCP_RX_IPV4.store(0, Ordering::Release);
    CYW43_POST_DHCP_RX_ICMP.store(0, Ordering::Release);
    CYW43_POST_DHCP_RX_TCP.store(0, Ordering::Release);
    CYW43_POST_DHCP_RX_LAST_ETHERTYPE.store(0, Ordering::Release);
    CYW43_POST_DHCP_RX_LAST_LEN.store(0, Ordering::Release);
    CYW43_ARP_TARGET_HW_ZEROED.store(0, Ordering::Release);
    *CYW43_HOST_EAPOL_SESSION.lock() = None;
    CYW43_HOST_EAPOL_PENDING_EVENTS.lock().clear();
    *CYW43_PENDING_DATA_TX.lock() = None;
    CYW43_PENDING_ARP_TX.lock().clear();
    *CYW43_MAINTENANCE_CURSOR.lock() = Cyw43MaintenanceCursor {
        generation: next_epoch,
        ..Cyw43MaintenanceCursor::new()
    };
    clear_cyw43_pending_control_replies();
    clear_cyw43_active_prompt_poll();
    clear_all_cyw43_terminal_drain_cursors();
    clear_cyw43_host_eapol_status_throttle();
    clear_cyw43_unproven_tx_window();
    CYW43_BCDC_IOCTL_ID.store(0, Ordering::Release);

    Some(next_epoch)
}

#[cfg(feature = "kernel")]
fn transition_cyw43_host_eapol_to_reauthentication() {
    if CYW43_HOST_EAPOL_SECURE.load(Ordering::Acquire) == 0
        && CYW43_HOST_EAPOL_ACTIVE.load(Ordering::Acquire) == 0
        && CYW43_HOST_EAPOL_REQUIRED.load(Ordering::Acquire) == 0
        && CYW43_OPEN_NETWORK_ACTIVE.load(Ordering::Acquire) == 0
    {
        return;
    }
    let next_epoch = CYW43_CONNECTION_EPOCH
        .fetch_add(1, Ordering::AcqRel)
        .wrapping_add(1);
    CYW43_DEFERRED_CARRIER_REAUTH_EPOCH_TOKEN.store(0, Ordering::Release);
    invalidate_cyw43_data_handoff();
    clear_cyw43_association_event_arm();
    CYW43_ASSOCIATION_TERMINAL_FAILURE.store(0, Ordering::Release);
    CYW43_REJOIN_PENDING_EPOCH_TOKEN.store(cyw43_epoch_token(next_epoch), Ordering::Release);
    keep_cyw43_reauthentication_pending();
}

#[cfg(feature = "kernel")]
fn request_cyw43_host_eapol_reauthentication(retained_action_pending: bool) {
    if !retained_action_pending {
        transition_cyw43_host_eapol_to_reauthentication();
        return;
    }
    let generation = CYW43_CONNECTION_EPOCH.load(Ordering::Acquire);
    CYW43_DEFERRED_CARRIER_REAUTH_EPOCH_TOKEN
        .store(cyw43_epoch_token(generation), Ordering::Release);
    invalidate_cyw43_data_handoff();
    keep_cyw43_reauthentication_pending();
}

#[cfg(feature = "kernel")]
fn cyw43_generation_owner_is_terminal(expected_generation: u32) -> bool {
    CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) == expected_generation
        && crate::hal::driver_task::active_driver_task_retained_request(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
        )
        .is_none()
        && CYW43_TERMINAL_DRAIN_CURSOR.lock().is_none()
        && !cyw43_recovery_required()
}

#[cfg(feature = "kernel")]
fn complete_deferred_cyw43_host_eapol_reauthentication(session: &Cyw43HostEapolSession) -> bool {
    let generation = CYW43_CONNECTION_EPOCH.load(Ordering::Acquire);
    let token = cyw43_epoch_token(generation);
    if CYW43_DEFERRED_CARRIER_REAUTH_EPOCH_TOKEN.load(Ordering::Acquire) != token
        || cyw43_host_eapol_retained_action_pending(session)
        || !cyw43_generation_owner_is_terminal(generation)
    {
        return false;
    }
    if CYW43_DEFERRED_CARRIER_REAUTH_EPOCH_TOKEN
        .compare_exchange(token, 0, Ordering::AcqRel, Ordering::Acquire)
        .is_err()
    {
        return false;
    }
    transition_cyw43_host_eapol_to_reauthentication();
    true
}

#[cfg(feature = "kernel")]
const fn cyw43_epoch_token(epoch: u32) -> u64 {
    epoch as u64 + 1
}

#[cfg(feature = "kernel")]
fn invalidate_cyw43_data_handoff() {
    // Generation start is not a consumer handoff. Cohesix can admit firmware
    // data while exact post-key work still owns the linked runtime and before
    // root has attached NetStack, unlike Linux's already-live netdev. Leave
    // Gate 8h pending until the explicit consumer-active commit.
    CYW43_DATA_HANDOFF_COMMIT_EPOCH_TOKEN.store(0, Ordering::Release);
    CYW43_DATA_HANDOFF_BASELINE_EPOCH_TOKEN.store(0, Ordering::Release);
    CYW43_GATE8_PUBLICATION_EPOCH_TOKEN.store(0, Ordering::Release);
    clear_cyw43_data_tx_rx_fairness();
    CYW43_PENDING_RX_DROP_EPOCH_TOKEN.store(0, Ordering::Release);
    let mut baseline = CYW43_DATA_HANDOFF_BASELINE.lock();
    let mut queue = CYW43_PENDING_RX_QUEUE.lock();
    let stale = queue.len() as u32;
    queue.clear();
    record_cyw43_stale_rx_purge(CYW43_CONNECTION_EPOCH.load(Ordering::Acquire), stale);
    *CYW43_POSTCOMMIT_FIRST_PENDING_RX_LOSS.lock() = None;
    *baseline = Cyw43DataHandoffBaseline::initial();
}

#[cfg(feature = "kernel")]
fn cyw43_data_handoff_committed_for_generation(expected_generation: u32) -> bool {
    let expected_token = cyw43_epoch_token(expected_generation);
    CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) == expected_generation
        && CYW43_DATA_HANDOFF_BASELINE_EPOCH_TOKEN.load(Ordering::Acquire) == expected_token
        && CYW43_DATA_HANDOFF_COMMIT_EPOCH_TOKEN.load(Ordering::Acquire) == expected_token
        && CYW43_DATA_HANDOFF_BASELINE_EPOCH_TOKEN.load(Ordering::Acquire) == expected_token
        && CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) == expected_generation
}

#[cfg(feature = "kernel")]
fn cyw43_data_consumer_open_for_generation(expected_generation: u32) -> bool {
    let expected_token = cyw43_epoch_token(expected_generation);
    cyw43_data_handoff_committed_for_generation(expected_generation)
        && CYW43_GATE8_PUBLICATION_EPOCH_TOKEN.load(Ordering::Acquire) == expected_token
        && !cyw43_recovery_required()
        && !cyw43_rejoin_pending_for_epoch(expected_generation)
        && CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) == expected_generation
}

#[cfg(feature = "kernel")]
fn cyw43_current_generation_data_consumer_open() -> bool {
    cyw43_data_consumer_open_for_generation(CYW43_CONNECTION_EPOCH.load(Ordering::Acquire))
}

#[cfg(feature = "kernel")]
fn cyw43_data_tx_rx_fairness_due_for_generation(generation: u32) -> bool {
    if CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) != generation {
        return false;
    }
    let mut slot = CYW43_DATA_TX_RX_FAIRNESS.lock();
    let Some(cursor) = *slot else {
        return false;
    };
    if cursor.generation != generation {
        return false;
    }
    match cursor.phase {
        Cyw43DataTxRxFairnessPhase::RequiredPoll => true,
        Cyw43DataTxRxFairnessPhase::Watching { deadline } => {
            if cyw43_poll_deadline_is_open(&deadline) {
                true
            } else {
                // Retire only the expired root-local watch. This passive
                // predicate never advances or replaces a retained HAL parent.
                *slot = None;
                false
            }
        }
    }
}

#[cfg(feature = "kernel")]
fn cyw43_current_generation_data_tx_rx_fairness_due() -> bool {
    cyw43_data_tx_rx_fairness_due_for_generation(CYW43_CONNECTION_EPOCH.load(Ordering::Acquire))
}

#[cfg(feature = "kernel")]
fn cyw43_data_tx_rx_fairness_required_for_generation(generation: u32) -> bool {
    CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) == generation
        && CYW43_DATA_TX_RX_FAIRNESS.lock().is_some_and(|cursor| {
            cursor.generation == generation
                && cursor.phase == Cyw43DataTxRxFairnessPhase::RequiredPoll
        })
}

#[cfg(feature = "kernel")]
fn cyw43_current_generation_data_tx_rx_fairness_required() -> bool {
    cyw43_data_tx_rx_fairness_required_for_generation(
        CYW43_CONNECTION_EPOCH.load(Ordering::Acquire),
    )
}

#[cfg(feature = "kernel")]
fn cyw43_data_tx_rx_fairness_watching_for_generation(generation: u32) -> bool {
    CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) == generation
        && CYW43_DATA_TX_RX_FAIRNESS.lock().is_some_and(|cursor| {
            cursor.generation == generation
                && matches!(
                    cursor.phase,
                    Cyw43DataTxRxFairnessPhase::Watching { deadline }
                        if cyw43_poll_deadline_is_open(&deadline)
                )
        })
}

#[cfg(feature = "kernel")]
fn arm_cyw43_data_tx_rx_fairness(generation: u32) {
    if CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) == generation
        && cyw43_data_consumer_open_for_generation(generation)
    {
        *CYW43_DATA_TX_RX_FAIRNESS.lock() = Some(Cyw43DataTxRxFairness {
            generation,
            phase: Cyw43DataTxRxFairnessPhase::RequiredPoll,
        });
    }
}

#[cfg(feature = "kernel")]
fn clear_cyw43_data_tx_rx_fairness() {
    *CYW43_DATA_TX_RX_FAIRNESS.lock() = None;
}

#[cfg(feature = "kernel")]
fn cyw43_rejoin_pending_for_epoch(epoch: u32) -> bool {
    CYW43_REJOIN_PENDING_EPOCH_TOKEN.load(Ordering::Acquire) == cyw43_epoch_token(epoch)
}

#[cfg(feature = "kernel")]
fn clear_cyw43_rejoin_pending_for_epoch(epoch: u32) -> bool {
    let token = cyw43_epoch_token(epoch);
    CYW43_REJOIN_PENDING_EPOCH_TOKEN
        .compare_exchange(token, 0, Ordering::AcqRel, Ordering::Acquire)
        .is_ok()
}

#[cfg(feature = "kernel")]
fn cyw43_host_eapol_epoch_is_current(progress: &Cyw43HostEapolProgress) -> bool {
    progress.connection_epoch == CYW43_CONNECTION_EPOCH.load(Ordering::Acquire)
}

#[cfg(feature = "kernel")]
fn reject_stale_cyw43_host_eapol_epoch(
    progress: &mut Cyw43HostEapolProgress,
) -> Result<(), DriverTaskNetError> {
    if cyw43_host_eapol_epoch_is_current(progress) {
        return Ok(());
    }
    progress.record_eapol_error("host-eapol-carrier-changed");
    keep_cyw43_reauthentication_pending();
    Err(DriverTaskNetError::RuntimePending(
        "host-eapol-carrier-changed",
    ))
}

#[cfg(feature = "kernel")]
const fn cyw43_event_is_terminal_association_failure(event: Cyw43EventFrame) -> bool {
    match event.event_type {
        CYW43_EVENT_SET_SSID => event.status != CYW43_EVENT_STATUS_SUCCESS,
        CYW43_EVENT_LINK => {
            event.status == CYW43_EVENT_STATUS_NO_NETWORKS || !cyw43_event_has_link_flag(event)
        }
        CYW43_EVENT_DEAUTH | CYW43_EVENT_DEAUTH_IND | CYW43_EVENT_DISASSOC_IND => true,
        _ => false,
    }
}

#[cfg(feature = "kernel")]
fn arm_cyw43_association_events_for_join_request(
    generation: u32,
    request: Option<u32>,
    issued: bool,
    tx_committed: bool,
) -> bool {
    let Some(request) = request.filter(|request| *request != 0) else {
        return false;
    };
    if CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) != generation || !issued || !tx_committed {
        return false;
    }
    let pair_scrub_epoch = CYW43_PAIR_SCRUB_EPOCH.load(Ordering::Acquire);
    *CYW43_ASSOCIATION_JOIN_ARM_RECEIPT.lock() = Some(Cyw43AssociationJoinArmReceipt {
        generation,
        pair_scrub_epoch,
        request,
        issued,
        accepted: cyw43_child_action_accepted(Some(request), issued),
        tx_committed,
    });
    core::sync::atomic::fence(Ordering::Release);
    CYW43_ASSOCIATION_EVENT_ARMED_EPOCH_TOKEN
        .store(cyw43_epoch_token(generation), Ordering::Release);
    if CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) == generation
        && CYW43_PAIR_SCRUB_EPOCH.load(Ordering::Acquire) == pair_scrub_epoch
    {
        return true;
    }
    CYW43_ASSOCIATION_EVENT_ARMED_EPOCH_TOKEN.store(0, Ordering::Release);
    *CYW43_ASSOCIATION_JOIN_ARM_RECEIPT.lock() = None;
    false
}

#[cfg(feature = "kernel")]
fn clear_cyw43_association_event_arm() {
    CYW43_ASSOCIATION_EVENT_ARMED_EPOCH_TOKEN.store(0, Ordering::Release);
    *CYW43_ASSOCIATION_JOIN_ARM_RECEIPT.lock() = None;
}

#[cfg(feature = "kernel")]
fn cyw43_association_events_armed_for_generation(generation: u32) -> bool {
    let pair_scrub_epoch = CYW43_PAIR_SCRUB_EPOCH.load(Ordering::Acquire);
    CYW43_CONNECTION_EPOCH.load(Ordering::Acquire) == generation
        && CYW43_ASSOCIATION_EVENT_ARMED_EPOCH_TOKEN.load(Ordering::Acquire)
            == cyw43_epoch_token(generation)
        && CYW43_ASSOCIATION_JOIN_ARM_RECEIPT
            .lock()
            .is_some_and(|receipt| {
                receipt.generation == generation
                    && receipt.pair_scrub_epoch == pair_scrub_epoch
                    && receipt.request != 0
                    && receipt.issued
                    && receipt.accepted
                    && receipt.tx_committed
            })
}

#[cfg(feature = "kernel")]
fn cyw43_carrier_loss_applies_to_armed_generation(event: Cyw43EventFrame) -> bool {
    if !cyw43_event_is_carrier_loss(event) {
        return false;
    }
    let generation = CYW43_CONNECTION_EPOCH.load(Ordering::Acquire);
    cyw43_association_events_armed_for_generation(generation)
        && (CYW43_ASSOCIATED.load(Ordering::Acquire) != 0
            || CYW43_LINK_UP.load(Ordering::Acquire) != 0)
}

#[cfg(feature = "kernel")]
fn record_cyw43_association_event_outcome(event: Cyw43EventFrame, source_stage: &'static str) {
    let generation = CYW43_CONNECTION_EPOCH.load(Ordering::Acquire);
    if !cyw43_association_events_armed_for_generation(generation) {
        return;
    }
    if cyw43_event_is_terminal_association_failure(event) {
        let join_arm = *CYW43_ASSOCIATION_JOIN_ARM_RECEIPT.lock();
        let mut receipt = CYW43_BOOT_FIRST_ASSOCIATION_TERMINAL_EVENT.lock();
        if receipt.is_none() {
            *receipt = Some(Cyw43AssociationTerminalEventReceipt {
                generation,
                pair_scrub_epoch: join_arm.map_or(0, |arm| arm.pair_scrub_epoch),
                event_type: event.event_type,
                status: event.status,
                reason: event.reason,
                auth_type: event.auth_type,
                join_request: join_arm.map_or(0, |arm| arm.request),
                join_issued: join_arm.is_some_and(|arm| arm.issued),
                join_accepted: join_arm.is_some_and(|arm| arm.accepted),
                join_tx_committed: join_arm.is_some_and(|arm| arm.tx_committed),
                source_stage,
            });
        }
        CYW43_ASSOCIATION_TERMINAL_FAILURE.store(1, Ordering::Release);
        record_cyw43_association_progress();
    }
}

#[cfg(feature = "kernel")]
fn cyw43_apply_pending_host_eapol_event(
    contract: DriverTaskContract,
    session: &mut Cyw43HostEapolSession,
    poll: usize,
) {
    for _ in 0..CYW43_HOST_EAPOL_PENDING_EVENTS_PER_SLICE {
        let pending = CYW43_HOST_EAPOL_PENDING_EVENTS.lock().pop_front();
        let Some(pending) = pending else {
            break;
        };
        session.progress.record_event_frame(
            pending.flags,
            usize::from(pending.len),
            pending.event,
            poll,
            pending.state_admitted
                && pending.generation == session.progress.connection_epoch
                && cyw43_association_events_armed_for_generation(pending.generation),
        );
        emit_cyw43_host_eapol_status(contract, "event-rx", &session.progress);
    }
}

#[cfg(feature = "kernel")]
fn cyw43_capture_event_frame_from_token(
    contract: DriverTaskContract,
    stage: &'static str,
    flags: u16,
    token: &DriverTaskNetRxToken,
) -> bool {
    if cyw43_frame_channel(flags) != DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_EVENT {
        return false;
    }
    let frame = &token.buffer[..token.len];
    let Some(event) = cyw43_parse_control_or_event_frame(frame) else {
        return false;
    };
    cyw43_store_pending_host_eapol_event(contract, stage, flags, frame.len(), event);
    true
}

