#[cfg(feature = "kernel")]
#[derive(Clone, Copy)]
enum Cyw43CommandSubmitError {
    Runtime(DriverTaskNetError),
    Completion(DriverTaskCompletionRecord),
}

#[cfg(feature = "kernel")]
impl Cyw43CommandSubmitError {
    const fn into_net_error(self) -> DriverTaskNetError {
        match self {
            Self::Runtime(err) => err,
            Self::Completion(_) => DriverTaskNetError::RuntimeInit("cyw43-command"),
        }
    }

    fn recoverable_completion(self) -> Option<DriverTaskCompletionRecord> {
        match self {
            Self::Completion(completion)
                if completion.code == DriverTaskCompletionCode::Fault.as_u16()
                    && cyw43_fault_detail_allows_sdio_owner_recovery(completion.detail) =>
            {
                Some(completion)
            }
            _ => None,
        }
    }

    fn not_issued_same_command_retry_completion(self) -> Option<DriverTaskCompletionRecord> {
        match self {
            Self::Completion(completion)
                if completion.code == DriverTaskCompletionCode::Fault.as_u16()
                    && cyw43_completion_allows_same_command_retry(completion) =>
            {
                Some(completion)
            }
            _ => None,
        }
    }
}

#[cfg(feature = "kernel")]
#[derive(Clone, Copy)]
enum Cyw43FirmwareInitError {
    Runtime(DriverTaskNetError),
    Command(Cyw43CommandSubmitError),
    Release(Cyw43CommandSubmitError),
}

#[cfg(feature = "kernel")]
impl Cyw43FirmwareInitError {
    fn into_net_error(self) -> DriverTaskNetError {
        match self {
            Self::Runtime(err) => err,
            Self::Command(err) | Self::Release(err) => err.into_net_error(),
        }
    }

    fn recoverable_completion(self) -> Option<DriverTaskCompletionRecord> {
        match self {
            Self::Command(err) | Self::Release(err) => err.recoverable_completion(),
            _ => None,
        }
    }

    fn same_command_retry_completion(self) -> Option<DriverTaskCompletionRecord> {
        match self {
            Self::Command(Cyw43CommandSubmitError::Completion(completion))
                if completion.code == DriverTaskCompletionCode::Fault.as_u16()
                    && cyw43_completion_allows_same_command_retry(completion) =>
            {
                Some(completion)
            }
            // RELEASE is a composite parent operation. Even when its final
            // nested SDIO child reports a pre-issue inhibit, earlier IOEx,
            // IORx, or core-release work may already have committed. The pair
            // generation is the only safe replay boundary.
            Self::Release(_) => None,
            _ => None,
        }
    }

    fn generation_recovery_completion(self) -> Option<DriverTaskCompletionRecord> {
        match self {
            Self::Command(Cyw43CommandSubmitError::Completion(completion))
                if completion.code == DriverTaskCompletionCode::Fault.as_u16()
                    && completion.detail == CYW43_SDIO_DESCRIPTOR_TRANSFER_FAILED_DETAIL
                    && sdio_transfer_failure_stage(completion.result) != 1 =>
            {
                Some(completion)
            }
            Self::Release(Cyw43CommandSubmitError::Completion(completion))
                if completion.code == DriverTaskCompletionCode::Fault.as_u16()
                    && crate::cyw43_recovery::firmware_release_fault_requires_engine_recovery(
                        DRIVER_RUNTIME_CYW43_OP_RELEASE,
                        completion.detail,
                    ) =>
            {
                Some(completion)
            }
            _ => None,
        }
    }
}

