    unsafe fn cyw43_supervisor_ring_test_service(
        _selector: usize,
        command: DriverTaskCommandRecord,
    ) -> DriverTaskCompletionRecord {
        let op = crate::hal::driver_task::driver_task_ring_frame_bytes(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            command.frame,
        )
        .and_then(decode_cyw43_descriptor)
        .map_or(0, |descriptor| u32::from(descriptor.op));
        CYW43_SUPERVISOR_LAST_OP.store(op, Ordering::Release);
        CYW43_SUPERVISOR_RING_TURNS.fetch_add(1, Ordering::AcqRel);
        let completion = DriverTaskCompletionRecord {
            sequence: command.sequence,
            code: DriverTaskCompletionCode::Idle.as_u16(),
            detail: 0,
            result: 0,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        };
        let fault_detail = CYW43_SUPERVISOR_FAULT_DETAIL.load(Ordering::Acquire) as u16;
        if fault_detail != 0 {
            return DriverTaskCompletionRecord {
                sequence: command.sequence,
                code: DriverTaskCompletionCode::Fault.as_u16(),
                detail: fault_detail,
                result: CYW43_SUPERVISOR_FAULT_RESULT.load(Ordering::Acquire),
                frame: DriverFrameDescriptor {
                    offset: 0,
                    len: 0,
                    flags: 0,
                },
            };
        }
        completion
    }

    unsafe fn cyw43_pair_restart_ring_test_service(
        _selector: usize,
        command: DriverTaskCommandRecord,
    ) -> DriverTaskCompletionRecord {
        if command.aux0 == pi4_driver_abi::DRIVER_RUNTIME_INIT_AUX {
            return DriverTaskCompletionRecord::progress(
                command.sequence,
                DriverTaskHotPath::Cyw43Wifi.as_u32(),
            );
        }
        if command.aux0 == pi4_driver_abi::DRIVER_RUNTIME_ENGINE_INIT_AUX {
            return DriverTaskCompletionRecord::progress(command.sequence, 1);
        }
        DriverTaskCompletionRecord::idle(command.sequence)
    }

    unsafe fn sdio_pair_restart_ring_test_service(
        _selector: usize,
        command: DriverTaskCommandRecord,
    ) -> DriverTaskCompletionRecord {
        if command.aux0 == pi4_driver_abi::DRIVER_RUNTIME_INIT_AUX {
            return DriverTaskCompletionRecord::progress(
                command.sequence,
                DriverTaskHotPath::SdioHost.as_u32(),
            );
        }
        if command.aux0 == pi4_driver_abi::DRIVER_RUNTIME_ENGINE_INIT_AUX {
            let mut completion = DriverTaskCompletionRecord::progress(command.sequence, 1);
            completion.detail = pi4_driver_abi::DRIVER_RUNTIME_SDIO_INIT_DETAIL_READY;
            return completion;
        }
        DriverTaskCompletionRecord::idle(command.sequence)
    }

    unsafe fn cyw43_owner_unknown_ring_test_service(
        _selector: usize,
        command: DriverTaskCommandRecord,
    ) -> DriverTaskCompletionRecord {
        let op = crate::hal::driver_task::driver_task_ring_frame_bytes(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            command.frame,
        )
        .and_then(decode_cyw43_descriptor)
        .map_or(0, |descriptor| u32::from(descriptor.op));
        CYW43_SUPERVISOR_LAST_OP.store(op, Ordering::Release);
        CYW43_SUPERVISOR_RING_TURNS.fetch_add(1, Ordering::AcqRel);
        // Simulate a reciprocal owner that accepted the immutable command but
        // autonomously observed it at sequence commit, before root's deferred
        // exact grant and notification turns. It then loses HAL registration
        // before root can authenticate completion ownership. The command was
        // issued, so production must never replay it; clearing the real
        // controller slot forces that exact boundary.
        crate::hal::driver_task::clear_driver_task_transport(CYW43_WIFI_DRIVER_TASK_CONTRACT);
        DriverTaskCompletionRecord::idle(command.sequence)
    }

    unsafe fn cyw43_maintenance_ring_test_service(
        _selector: usize,
        command: DriverTaskCommandRecord,
    ) -> DriverTaskCompletionRecord {
        let descriptor = crate::hal::driver_task::driver_task_ring_frame_bytes(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            command.frame,
        )
        .and_then(decode_cyw43_descriptor)
        .expect("maintenance test service receives a CYW43 descriptor");
        assert_eq!(descriptor.op, DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE);
        let turn = CYW43_MAINTENANCE_RING_TURNS.fetch_add(1, Ordering::AcqRel) as usize;
        if let Some(slot) = CYW43_MAINTENANCE_COMMANDS.get(turn) {
            slot.store(descriptor.arg0, Ordering::Release);
        }
        let fault_detail = CYW43_MAINTENANCE_FAULT_DETAIL.load(Ordering::Acquire) as u16;
        if fault_detail != 0 {
            return DriverTaskCompletionRecord {
                sequence: command.sequence,
                code: DriverTaskCompletionCode::Fault.as_u16(),
                detail: fault_detail,
                result: CYW43_MAINTENANCE_FAULT_RESULT.load(Ordering::Acquire),
                frame: DriverFrameDescriptor {
                    offset: 0,
                    len: 0,
                    flags: 0,
                },
            };
        }
        DriverTaskCompletionRecord {
            sequence: command.sequence,
            code: DriverTaskCompletionCode::FrameReady.as_u16(),
            detail: 0,
            result: 0,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        }
    }

    unsafe fn cyw43_maintenance_interleaved_ring_test_service(
        _selector: usize,
        command: DriverTaskCommandRecord,
    ) -> DriverTaskCompletionRecord {
        let descriptor = crate::hal::driver_task::driver_task_ring_frame_bytes(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            command.frame,
        )
        .and_then(decode_cyw43_descriptor)
        .expect("maintenance interleave service receives a CYW43 descriptor");
        assert_eq!(descriptor.op, DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE);
        assert_eq!(descriptor.arg0, CYW43_WLC_GET_BSSID);
        let turn = CYW43_MAINTENANCE_RING_TURNS.fetch_add(1, Ordering::AcqRel);
        if turn == 0 {
            return DriverTaskCompletionRecord {
                sequence: command.sequence,
                code: DriverTaskCompletionCode::FrameReady.as_u16(),
                detail: DRIVER_RUNTIME_CYW43_CONTROL_DETAIL_INTERLEAVED_FRAME,
                result: (CYW43_BDC_HEADER_BYTES + CYW43_BRCMF_EVENT_MIN_PACKET_LEN) as u32,
                frame: DriverFrameDescriptor {
                    offset: CYW43_MAINTENANCE_INTERLEAVED_EVENT_OFFSET as u32,
                    len: (CYW43_BDC_HEADER_BYTES + CYW43_BRCMF_EVENT_MIN_PACKET_LEN) as u16,
                    flags: DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_EVENT,
                },
            };
        }
        DriverTaskCompletionRecord {
            sequence: command.sequence,
            code: DriverTaskCompletionCode::FrameReady.as_u16(),
            detail: 0,
            result: 0,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        }
    }

