    #[cfg(feature = "kernel")]
    fn drive_cyw43_pending_data_tx_for_test(max_turns: usize) -> Cyw43DataTxTurnOutcome {
        let mut outcome = Cyw43DataTxTurnOutcome::Pending;
        for _ in 0..max_turns {
            begin_cyw43_outer_event_turn();
            outcome = advance_cyw43_pending_data_tx(CYW43_WIFI_DRIVER_TASK_CONTRACT);
            if outcome != Cyw43DataTxTurnOutcome::Pending {
                return outcome;
            }
        }
        outcome
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_supervisor_ticket_identity_is_immutable_and_stale_generation_is_rejected() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
        let descriptor = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME,
            flags: DRIVER_RUNTIME_CYW43_FLAG_CONTROL_PRE_TX_DRAIN,
            total_len: 4,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        supervisor
            .install_pending_action(
                descriptor,
                Cyw43RetainedPayload::Control { len: 4 },
                b"ABCD",
                Some(b"ABCD"),
                "cyw43-supervisor-ticket-test",
                "ticket-test",
            )
            .expect("first immutable ticket installs");
        let ticket = supervisor.pending.as_ref().expect("ticket retained").ticket;
        assert_eq!(ticket.id, 1);
        assert_eq!(ticket.generation, supervisor.generation);
        assert_eq!(ticket.payload_digest, cyw43_payload_digest(b"ABCD"));
        assert_eq!(
            supervisor.install_empty_action(descriptor, "overwrite"),
            Err(DriverTaskNetError::RuntimeInit(
                "cyw43-pending-action-overwrite"
            ))
        );

        supervisor.generation = supervisor.generation.wrapping_add(1);
        assert_eq!(
            supervisor.service_pending_action(),
            Cyw43RetainedActionOutcome::Poisoned("cyw43-stale-action-generation")
        );
        assert_eq!(CYW43_SUPERVISOR_RING_TURNS.load(Ordering::Acquire), 0);
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_supervisor_ticket_loss_preserves_the_gate_eight_causal_record() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        begin_cyw43_bootstrap_causal_fault_capture();
        let descriptor = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE,
            flags: DRIVER_RUNTIME_CYW43_FLAG_CONTROL_PRE_TX_DRAIN,
            total_len: 12,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
        supervisor
            .install_empty_action(descriptor, "cyw43-control-txglomalign")
            .expect("Gate 8 action installs");
        supervisor
            .pending
            .as_mut()
            .expect("Gate 8 action remains retained")
            .issuance = Cyw43ActionIssuance::AwaitingCompletion {
            request: 0x8000_1001,
        };

        assert_eq!(
            supervisor.service_pending_action(),
            Cyw43RetainedActionOutcome::Poisoned("cyw43-active-ticket-fingerprint"),
        );
        let causal = bootstrap_causal_cyw43_runtime_command_fault_status()
            .expect("terminal ticket loss remains visible after recovery");
        assert_eq!(causal.stage, "cyw43-control-txglomalign");
        assert_eq!(causal.op, DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE);
        assert_eq!(causal.reason, "cyw43-runtime-command-no-reply");

        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_recovery_uses_the_accepted_association_and_key_payload_digests() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();

        let credentials =
            WifiCredentials::new("cohesix", "passphrase").expect("valid test credentials");
        let mut association = begin_cyw43_pending_association_join(credentials, 0)
            .expect("association ticket is retained");
        let association_digest = association.payload_digest;
        association.tx_frame[0] ^= 0xff;
        assert_ne!(
            cyw43_payload_digest(&association.tx_frame[..usize::from(association.frame_len)]),
            association_digest,
            "the fixture must corrupt the retained bytes after ticket acceptance"
        );
        let association_recovery =
            latch_cyw43_pending_association_recovery(&association, Cyw43RecoveryCause::Association)
                .expect("current association owner publishes recovery");
        assert_eq!(association_recovery.payload_digest, association_digest);

        reset_cyw43_status_flags();
        let mut key = test_pending_pre_secure_key(Cyw43PreSecureKeyPhase::Ptk, 71);
        let key_digest = key.payload_digest;
        key.tx_frame[0] ^= 0xff;
        assert_ne!(
            cyw43_payload_digest(&key.tx_frame[..usize::from(key.frame_len)]),
            key_digest,
            "the fixture must corrupt the retained key bytes after ticket acceptance"
        );
        latch_cyw43_wsec_key_recovery(&key, Cyw43RecoveryCause::IssuedOwnerUnknown, None);
        assert_eq!(
            CYW43_DEFERRED_RECOVERY
                .lock()
                .expect("current key owner publishes recovery")
                .payload_digest,
            key_digest,
            "recovery identity is the immutable accepted digest, never mutated storage"
        );

        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn logical_op11_owner_yields_competing_lanes_without_consuming_the_outer_turn() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let mut ring_page = [0u8; crate::hal::driver_task::DRIVER_TASK_RING_PAGE_BYTES];
        let mut shared_page = [0u8; crate::hal::driver_task::DRIVER_TASK_RING_PAGE_BYTES];
        let _ring_guard = test_publish_cyw43_ring(&mut ring_page);
        crate::hal::driver_task::publish_driver_task_shared_frame(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            0,
            1,
            shared_page.as_mut_ptr() as usize,
        );
        assert!(
            crate::hal::driver_task::test_publish_driver_task_ring_endpoint(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
            )
        );
        CYW43_LINKED_RUNTIME_READY.store(1, Ordering::Release);
        CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.store(1, Ordering::Release);

        let credentials =
            WifiCredentials::new("cohesix", "passphrase").expect("valid association credentials");
        let pending_key = test_pending_pre_secure_key(Cyw43PreSecureKeyPhase::Ptk, 37);
        let owner_stage = pending_key.stage;
        let owner_id = pending_key.id;
        let mut host_eapol =
            Cyw43HostEapolSession::new(credentials).expect("host EAPOL session starts");
        host_eapol.pending_key_install = Some(pending_key);
        *CYW43_HOST_EAPOL_SESSION.lock() = Some(host_eapol);
        CYW43_HOST_EAPOL_ACTIVE.store(1, Ordering::Release);

        begin_cyw43_outer_event_turn();
        let first_owner_turn = service_cyw43_host_eapol_slice_with_outcome(credentials, 1, 1);
        assert!(first_owner_turn.progress.is_some());
        assert_eq!(cyw43_outer_event_turn_operation_count(), 1);
        let acquired_owner = cyw43_logical_control_owner_diagnostic()
            .expect("the production host-EAPOL path acquires logical op11 ownership");
        assert_eq!(acquired_owner.stage, owner_stage);
        assert_eq!(acquired_owner.expected_id, owner_id);

        begin_cyw43_outer_event_turn();
        let operations_before_poll = cyw43_outer_event_turn_operation_count();
        assert!(matches!(
            run_cyw43_runtime_descriptor_turn_raw(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                1,
                "cyw43-host-eapol-control-poll",
                DriverRuntimeCyw43CommandDescriptor {
                    op: DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL,
                    ..DriverRuntimeCyw43CommandDescriptor::empty()
                },
                &[],
            ),
            Err(DriverTaskNetError::RuntimePending(
                "cyw43-logical-control-owner-busy"
            ))
        ));
        assert_eq!(
            cyw43_outer_event_turn_operation_count(),
            operations_before_poll,
            "a generic op10 poll cannot consume the active op11 owner's turn",
        );

        let pending = begin_cyw43_pending_association_join(credentials, 0)
            .expect("association competitor retains its immutable ticket");
        let association_deadline = pending.deadline;
        let mut association = Cyw43AssociationSupervisor {
            generation: 0,
            retry_level: 0,
            auth_mode: Some(Cyw43AssociationAuthMode::HostEapol),
            phase: Cyw43AssociationPhase::Join(pending),
        };
        assert!(latch_cyw43_bssid_maintenance(
            Cyw43MaintenanceBssidContext {
                purpose: Cyw43MaintenanceBssidPurpose::PreAssociation { attempt: 1 },
                station_mac: EthernetAddress([0x02, 0, 0, 0, 0, 1]),
                poll: 1,
            },
        ));

        begin_cyw43_outer_event_turn();
        let operations_before = CYW43_TEST_PROGRESS_OPERATION_COUNT.load(Ordering::Acquire);
        let association_outcome = association.service(Some(credentials), 1);
        assert!(!association_outcome.activity);
        assert!(!association_outcome.claimed_runtime_turn);
        assert!(association_outcome.host_eapol_allowed);
        assert_eq!(cyw43_outer_event_turn_operation_count(), 0);
        let Cyw43AssociationPhase::Join(retained_join) = association.phase else {
            panic!("competing association ticket must remain retained");
        };
        assert_eq!(retained_join.deadline, association_deadline);
        assert_eq!(cyw43_outer_event_turn_operation_count(), 0);
        let resumed_owner_turn = service_cyw43_host_eapol_slice_with_outcome(credentials, 1, 2);
        assert!(resumed_owner_turn.progress.is_some());
        assert_eq!(cyw43_outer_event_turn_operation_count(), 1);
        assert!(CYW43_MAINTENANCE_CURSOR.lock().action.is_some());
        assert!(CYW43_DEFERRED_RECOVERY.lock().is_none());
        assert!(!crate::hal::driver_task::cyw43_sdio_pair_restart_required());

        let owner_after_resume =
            cyw43_logical_control_owner_diagnostic().expect("logical owner remains active");
        assert_eq!(owner_after_resume.stage, owner_stage);
        assert_eq!(owner_after_resume.expected_id, owner_id);
        assert_eq!(owner_after_resume.blocked_turns, 3);
        assert_eq!(
            CYW43_TEST_PROGRESS_OPERATION_COUNT
                .load(Ordering::Acquire)
                .saturating_sub(operations_before),
            1,
            "two competitors perform zero operations; only the owner reaches HAL",
        );
        assert_eq!(
            cyw43_logical_control_owner_diagnostic()
                .expect("pending owner remains immutable")
                .stage,
            owner_stage,
        );
        assert!(CYW43_HOST_EAPOL_SESSION
            .lock()
            .as_ref()
            .and_then(|session| session.pending_key_install)
            .is_some_and(|pending| pending.id == owner_id && pending.stage == owner_stage));
        assert!(!driver_task_runtime_pre_poll_allowed(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
        ));

        CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.store(0, Ordering::Release);
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_association_and_key_payload_drift_fence_the_real_ring_ticket() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");

        reset_cyw43_status_flags();
        let mut association_ring = [0u8; crate::hal::driver_task::DRIVER_TASK_RING_PAGE_BYTES];
        let mut association_shared = [0u8; crate::hal::driver_task::DRIVER_TASK_RING_PAGE_BYTES];
        let association_ring_guard = test_publish_cyw43_ring(&mut association_ring);
        crate::hal::driver_task::publish_driver_task_shared_frame(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            0,
            1,
            association_shared.as_mut_ptr() as usize,
        );
        assert!(
            crate::hal::driver_task::test_publish_driver_task_ring_endpoint(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
            )
        );
        assert!(
            crate::hal::driver_task::register_driver_task_pointer_free_ring_service(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                DriverTaskHotPath::Cyw43Wifi.as_u32() as usize,
                cyw43_supervisor_ring_test_service,
            )
        );
        CYW43_LINKED_RUNTIME_READY.store(1, Ordering::Release);
        CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.store(1, Ordering::Release);
        let credentials =
            WifiCredentials::new("cohesix", "passphrase").expect("valid test credentials");
        let mut association = begin_cyw43_pending_association_join(credentials, 0)
            .expect("association ticket is retained");
        let association_digest = association.payload_digest;
        let association_descriptor = association.tx_descriptor;
        let association_id = association.id;
        let association_submitted_before =
            crate::hal::driver_task::driver_task_counter_snapshot(CYW43_WIFI_DRIVER_TASK_CONTRACT)
                .map_or(0, |snapshot| snapshot.submitted_turns);

        begin_cyw43_outer_event_turn();
        assert!(matches!(
            advance_cyw43_pending_association_join(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                &mut association,
            ),
            Cyw43AssociationJoinStep::Pending { .. }
        ));
        assert_eq!(cyw43_outer_event_turn_operation_count(), 1);
        let association_request = association
            .request
            .expect("the association request is retained by the real controller");
        let association_submitted =
            crate::hal::driver_task::driver_task_counter_snapshot(CYW43_WIFI_DRIVER_TASK_CONTRACT)
                .expect("association controller counters exist")
                .submitted_turns;
        assert_eq!(
            association_submitted.saturating_sub(association_submitted_before),
            1
        );
        assert_eq!(CYW43_SUPERVISOR_RING_TURNS.load(Ordering::Acquire), 0);
        association.tx_frame[0] ^= 0xff;

        begin_cyw43_outer_event_turn();
        assert_eq!(
            advance_cyw43_pending_association_join(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                &mut association,
            ),
            Cyw43AssociationJoinStep::RecoveryRequired
        );
        assert_eq!(cyw43_outer_event_turn_operation_count(), 0);
        assert_eq!(CYW43_SUPERVISOR_RING_TURNS.load(Ordering::Acquire), 0);
        assert_eq!(
            crate::hal::driver_task::driver_task_counter_snapshot(CYW43_WIFI_DRIVER_TASK_CONTRACT,)
                .expect("association submitted count remains stable")
                .submitted_turns,
            association_submitted,
        );
        let recovery = CYW43_DEFERRED_RECOVERY
            .lock()
            .expect("association drift publishes exact recovery authority");
        assert_eq!(recovery.cause, Cyw43RecoveryCause::IssuedOwnerUnknown);
        assert_eq!(recovery.payload_digest, association_digest);
        assert_eq!(recovery.descriptor, association_descriptor);
        assert_eq!(recovery.ticket_id, u64::from(association_id));
        assert_eq!(recovery.sequence, 0);
        assert_ne!(association_request, 0);

        CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.store(0, Ordering::Release);
        drop(association_ring_guard);

        reset_cyw43_status_flags();
        let mut key_ring = [0u8; crate::hal::driver_task::DRIVER_TASK_RING_PAGE_BYTES];
        let mut key_shared = [0u8; crate::hal::driver_task::DRIVER_TASK_RING_PAGE_BYTES];
        let key_ring_guard = test_publish_cyw43_ring(&mut key_ring);
        crate::hal::driver_task::publish_driver_task_shared_frame(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            0,
            1,
            key_shared.as_mut_ptr() as usize,
        );
        assert!(
            crate::hal::driver_task::test_publish_driver_task_ring_endpoint(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
            )
        );
        assert!(
            crate::hal::driver_task::register_driver_task_pointer_free_ring_service(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                DriverTaskHotPath::Cyw43Wifi.as_u32() as usize,
                cyw43_supervisor_ring_test_service,
            )
        );
        CYW43_LINKED_RUNTIME_READY.store(1, Ordering::Release);
        CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.store(1, Ordering::Release);
        let mut key = test_pending_pre_secure_key(Cyw43PreSecureKeyPhase::Ptk, 71);
        let key_digest = key.payload_digest;
        let key_descriptor = key.tx_descriptor;
        let key_submitted_before =
            crate::hal::driver_task::driver_task_counter_snapshot(CYW43_WIFI_DRIVER_TASK_CONTRACT)
                .map_or(0, |snapshot| snapshot.submitted_turns);

        begin_cyw43_outer_event_turn();
        assert!(matches!(
            advance_cyw43_wsec_key_control_exchange_slice(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                &mut key,
            ),
            Ok(Cyw43IncrementalKeyPollResult::Pending { .. })
        ));
        assert_eq!(cyw43_outer_event_turn_operation_count(), 1);
        let key_request = key
            .request
            .expect("the key request is retained by the real controller");
        let key_submitted =
            crate::hal::driver_task::driver_task_counter_snapshot(CYW43_WIFI_DRIVER_TASK_CONTRACT)
                .expect("key controller counters exist")
                .submitted_turns;
        assert_eq!(key_submitted.saturating_sub(key_submitted_before), 1);
        assert_eq!(CYW43_SUPERVISOR_RING_TURNS.load(Ordering::Acquire), 0);
        key.tx_frame[0] ^= 0xff;

        begin_cyw43_outer_event_turn();
        assert_eq!(
            advance_cyw43_wsec_key_control_exchange_slice(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                &mut key,
            ),
            Err(DriverTaskNetError::RuntimePending(
                "cyw43-wsec-key-payload-drift"
            ))
        );
        assert_eq!(cyw43_outer_event_turn_operation_count(), 0);
        assert_eq!(CYW43_SUPERVISOR_RING_TURNS.load(Ordering::Acquire), 0);
        assert_eq!(
            crate::hal::driver_task::driver_task_counter_snapshot(CYW43_WIFI_DRIVER_TASK_CONTRACT,)
                .expect("key submitted count remains stable")
                .submitted_turns,
            key_submitted,
        );
        let recovery = CYW43_DEFERRED_RECOVERY
            .lock()
            .expect("key drift publishes exact recovery authority");
        assert_eq!(recovery.cause, Cyw43RecoveryCause::IssuedOwnerUnknown);
        assert_eq!(recovery.payload_digest, key_digest);
        assert_eq!(recovery.descriptor, key_descriptor);
        assert_eq!(recovery.ticket_id, 71);
        assert_eq!(recovery.sequence, 0);
        assert_ne!(key_request, 0);
        assert!(key.logical_epoch_stale);

        CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.store(0, Ordering::Release);
        drop(key_ring_guard);
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_supervisor_issued_owner_unknown_is_poisoned_without_replay() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let mut ring_page = [0u8; crate::hal::driver_task::DRIVER_TASK_RING_PAGE_BYTES];
        let _ring_guard = test_publish_cyw43_ring(&mut ring_page);
        assert!(
            crate::hal::driver_task::test_publish_driver_task_ring_endpoint(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
            )
        );
        assert!(
            crate::hal::driver_task::register_driver_task_pointer_free_ring_service(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                DriverTaskHotPath::Cyw43Wifi.as_u32() as usize,
                cyw43_owner_unknown_ring_test_service,
            )
        );
        CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.store(1, Ordering::Release);
        let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
        supervisor
            .install_empty_action(
                DriverRuntimeCyw43CommandDescriptor {
                    op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
                    ..DriverRuntimeCyw43CommandDescriptor::empty()
                },
                "cyw43-owner-unknown-test",
            )
            .expect("immutable action installs");
        let mut outcome = Cyw43RetainedActionOutcome::Pending;
        for _ in 0..CYW43_RUNTIME_MIN_RETAINED_TURNS {
            begin_cyw43_outer_event_turn();
            outcome = supervisor.service_pending_action();
            assert!(cyw43_outer_event_turn_operation_count() <= 1);
            if matches!(outcome, Cyw43RetainedActionOutcome::Poisoned(_)) {
                break;
            }
            assert_eq!(outcome, Cyw43RetainedActionOutcome::Pending);
        }
        assert_eq!(
            outcome,
            Cyw43RetainedActionOutcome::Poisoned("cyw43-issued-owner-unknown")
        );
        assert_eq!(CYW43_SUPERVISOR_RING_TURNS.load(Ordering::Acquire), 1);
        let retained_calls = CYW43_TEST_PROGRESS_OPERATION_COUNT.load(Ordering::Acquire);
        assert_ne!(retained_calls, 0);
        assert!(supervisor.pending.is_none());
        begin_cyw43_outer_event_turn();
        assert_eq!(
            supervisor.service_pending_action(),
            Cyw43RetainedActionOutcome::Failed(DriverTaskNetError::RuntimeInit(
                "cyw43-pending-action-missing"
            ))
        );
        assert_eq!(
            CYW43_TEST_PROGRESS_OPERATION_COUNT.load(Ordering::Acquire),
            retained_calls,
            "an issued-unknown action must never be replayed"
        );
        assert_eq!(
            CYW43_SUPERVISOR_RING_TURNS.load(Ordering::Acquire),
            1,
            "the possibly-issued controller action must never run twice",
        );
        CYW43_TEST_ENFORCE_OUTER_EVENT_TURN.store(0, Ordering::Release);
        reset_cyw43_status_flags();
    }

