        let completion = DriverTaskCompletionRecord {
            sequence: 42,
            code: DriverTaskCompletionCode::FrameReady.as_u16(),
            detail: 0,
            result: 20,
            frame: DriverFrameDescriptor {
                offset: 1024,
                len: 20,
                flags: 0x0002,
            },
        };

        let response =
            cyw43_control_response_completion(completion, 4).expect("response frame must fit");

