    #[cfg(feature = "kernel")]
    #[test]
    fn rx_idle_trace_v10_decodes_actual_dpc_rearms_and_retains_v9() {
        let mut v10 = [0u8; CYW43_RX_IDLE_TRACE_V10_BYTES];
        v10[0..4].copy_from_slice(&CYW43_RX_IDLE_TRACE_MAGIC.to_le_bytes());
        v10[4..6].copy_from_slice(&CYW43_RX_IDLE_TRACE_VERSION.to_le_bytes());
        v10[180..184].copy_from_slice(&17u32.to_le_bytes());
        v10[184..188].copy_from_slice(&2u32.to_le_bytes());
        v10[188..192].copy_from_slice(&3u32.to_le_bytes());
        v10[192..196].copy_from_slice(&19u32.to_le_bytes());
        let decoded = cyw43_rx_idle_trace(&v10).expect("v10 trace must decode");
        assert_eq!(decoded.version, CYW43_RX_IDLE_TRACE_VERSION);
        assert_eq!(decoded.dpc_events_consumed, 17);
        assert_eq!(decoded.dpc_epoch_errors, 2);
        assert_eq!(decoded.dpc_sequence_errors, 3);
        assert_eq!(decoded.dpc_owner_rearms, 19);
        assert_eq!(
            cyw43_rx_idle_trace(&v10[..CYW43_RX_IDLE_TRACE_V9_BYTES]),
            None
        );

        let mut v9 = [0u8; CYW43_RX_IDLE_TRACE_V9_BYTES];
        v9[0..4].copy_from_slice(&CYW43_RX_IDLE_TRACE_MAGIC.to_le_bytes());
        v9[4..6].copy_from_slice(&CYW43_RX_IDLE_TRACE_VERSION_V9.to_le_bytes());
        v9[180..184].copy_from_slice(&7u32.to_le_bytes());
        let decoded = cyw43_rx_idle_trace(&v9).expect("v9 trace must remain supported");
        assert_eq!(decoded.version, CYW43_RX_IDLE_TRACE_VERSION_V9);
        assert_eq!(decoded.dpc_events_consumed, 7);
        assert_eq!(decoded.dpc_owner_rearms, 0);

        let mut v8 = [0u8; CYW43_RX_IDLE_TRACE_V8_BYTES];
        v8[0..4].copy_from_slice(&CYW43_RX_IDLE_TRACE_MAGIC.to_le_bytes());
        v8[4..6].copy_from_slice(&CYW43_RX_IDLE_TRACE_VERSION_V8.to_le_bytes());
        let decoded = cyw43_rx_idle_trace(&v8).expect("v8 trace must remain supported");
        assert_eq!(decoded.version, CYW43_RX_IDLE_TRACE_VERSION_V8);
        assert_eq!(decoded.dpc_events_consumed, 0);
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn sdio_dpc_diagnostic_derives_exact_ring_service_totals() {
        let diagnostic = cyw43_sdio_dpc_diagnostic_from(
            crate::hal::driver_task::DriverTaskSdioDpcRingSnapshot {
                epoch: 7,
                producer: 12,
                consumer: 11,
                flags: DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED,
                overruns: 2,
                ack_failures: 1,
            },
            Cyw43DpcClientCounters {
                consumed: 11,
                rearms: 10,
                epoch_errors: 3,
                sequence_errors: 4,
            },
        );
        assert_eq!(diagnostic.generation, 7);
        assert_eq!(diagnostic.captures, 14);
        assert_eq!(diagnostic.published, 12);
        assert_eq!(diagnostic.consumed, 11);
        assert_eq!(diagnostic.sample_consumer, 11);
        assert_eq!(diagnostic.rearms, 10);
        assert_eq!(diagnostic.epoch_errors, 3);
        assert_eq!(diagnostic.sequence_errors, 4);
        assert!(!diagnostic.ring_poisoned);
        assert!(!diagnostic.client_sample_stale);
        assert!(diagnostic.poisoned);
        assert!(diagnostic.masked);

        let mismatch = cyw43_sdio_dpc_diagnostic_from(
            crate::hal::driver_task::DriverTaskSdioDpcRingSnapshot {
                epoch: 8,
                producer: 13,
                consumer: 13,
                flags: 0,
                overruns: 0,
                ack_failures: 0,
            },
            Cyw43DpcClientCounters {
                consumed: 12,
                rearms: 13,
                epoch_errors: 0,
                sequence_errors: 0,
            },
        );
        assert_eq!(mismatch.sample_consumer, 12);
        assert!(!mismatch.ring_poisoned);
        assert!(mismatch.client_sample_stale);
        assert!(mismatch.poisoned, "stale client sample must fail closed");

        let ring_poisoned = cyw43_sdio_dpc_diagnostic_from(
            crate::hal::driver_task::DriverTaskSdioDpcRingSnapshot {
                epoch: 9,
                producer: 14,
                consumer: 14,
                flags: DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED,
                overruns: 0,
                ack_failures: 0,
            },
            Cyw43DpcClientCounters {
                consumed: 14,
                rearms: 14,
                epoch_errors: 0,
                sequence_errors: 0,
            },
        );
        assert_eq!(ring_poisoned.sample_consumer, 14);
        assert!(ring_poisoned.ring_poisoned);
        assert!(!ring_poisoned.client_sample_stale);
        assert!(ring_poisoned.poisoned);
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_durable_work_reason_mask_covers_every_production_source() {
        macro_rules! assert_reason {
            ($field:ident, $reason:ident) => {{
                let mut inputs = Cyw43ServiceWorkInputs::default();
                inputs.$field = true;
                assert_eq!(
                    inputs.reason_mask(),
                    $reason,
                    concat!(stringify!($field), " must own exactly one reason bit"),
                );
            }};
        }

        assert_eq!(
            Cyw43ServiceWorkInputs::default().reason_mask(),
            0,
            "exact idle must have no durable-work reason",
        );
        assert_reason!(dpc, CYW43_SERVICE_WORK_DPC);
        assert_reason!(root_wake, CYW43_SERVICE_WORK_ROOT_WAKE);
        assert_reason!(pre_poll, CYW43_SERVICE_WORK_PRE_POLL);
        assert_reason!(data_tx, CYW43_SERVICE_WORK_DATA_TX);
        assert_reason!(arp_tx, CYW43_SERVICE_WORK_ARP_TX);
        assert_reason!(tx_rx_fairness, CYW43_SERVICE_WORK_TX_RX_FAIRNESS);
        assert_reason!(runtime_descriptor, CYW43_SERVICE_WORK_RUNTIME_DESCRIPTOR);
        assert_reason!(root_rx, CYW43_SERVICE_WORK_ROOT_RX);
        assert_reason!(control_reply, CYW43_SERVICE_WORK_CONTROL_REPLY);
        assert_reason!(logical_owner, CYW43_SERVICE_WORK_LOGICAL_OWNER);
        assert_reason!(terminal_drain, CYW43_SERVICE_WORK_TERMINAL_DRAIN);
        assert_reason!(host_eapol, CYW43_SERVICE_WORK_HOST_EAPOL);
        assert_reason!(hal_lease, CYW43_SERVICE_WORK_HAL_LEASE);
        assert_reason!(prompt, CYW43_SERVICE_WORK_PROMPT);
        assert_reason!(maintenance, CYW43_SERVICE_WORK_MAINTENANCE);
        assert_reason!(recovery, CYW43_SERVICE_WORK_RECOVERY);

        let all = Cyw43ServiceWorkInputs {
            dpc: true,
            root_wake: true,
            pre_poll: true,
            data_tx: true,
            arp_tx: true,
            tx_rx_fairness: true,
            runtime_descriptor: true,
            root_rx: true,
            control_reply: true,
            logical_owner: true,
            terminal_drain: true,
            host_eapol: true,
            hal_lease: true,
            prompt: true,
            maintenance: true,
            recovery: true,
        };
        assert_eq!(
            all.reason_mask(),
            (1u64 << 16) - 1,
            "the complete source set must be gap-free and non-overlapping",
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_durable_work_snapshot_samples_live_rx_and_tx_without_nested_locks() {
        let _guard = CYW43_STATUS_TEST_LOCK
            .lock()
            .expect("cyw43 status test lock");
        reset_cyw43_status_flags();
        set_cyw43_service_work_snapshot_test_override(None);
        let generation = 73;
        CYW43_CONNECTION_EPOCH.store(generation, Ordering::Release);

        assert!(submit_cyw43_driver_task_eth_frame(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            b"durable-work",
        ));
        assert!(store_cyw43_pending_rx_token(
            DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_DATA,
            test_rx_token(&test_cyw43_tcp_frame()),
        ));

        let snapshot = cyw43_service_work_snapshot();
        assert_eq!(snapshot.generation(), generation);
        assert_ne!(
            snapshot.reason_mask() & CYW43_SERVICE_WORK_DATA_TX,
            0,
            "the live immutable TX parent must remain durable",
        );
        assert_ne!(
            snapshot.reason_mask() & CYW43_SERVICE_WORK_ROOT_RX,
            0,
            "the copied current-generation RX must remain durable",
        );

        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_durable_work_requires_one_completed_non_recovery_physical_lifetime() {
        let recovery_without_lifetime =
            Cyw43ServiceWorkSnapshot::for_test(74, 19, 0, CYW43_SERVICE_WORK_RECOVERY);
        assert!(
            recovery_without_lifetime.more_work(),
            "recovery remains visible to passive supervisor diagnostics"
        );
        assert!(
            !recovery_without_lifetime.ordinary_network_admissible(),
            "epoch zero must never authorize an ordinary Network turn"
        );
        assert!(!recovery_without_lifetime.schedulable_network_work());

        let recovery_with_old_lifetime =
            Cyw43ServiceWorkSnapshot::for_test(74, 19, 11, CYW43_SERVICE_WORK_RECOVERY);
        assert!(
            !recovery_with_old_lifetime.ordinary_network_admissible(),
            "an old completed lifetime must not turn recovery into steady-state authority"
        );
        assert!(!recovery_with_old_lifetime.schedulable_network_work());

        let current_data =
            Cyw43ServiceWorkSnapshot::for_test(74, 19, 11, CYW43_SERVICE_WORK_DATA_TX);
        assert!(current_data.ordinary_network_admissible());
        assert!(current_data.schedulable_network_work());

        let replacement_not_bound = Cyw43ServiceWorkSnapshot::for_test_with_bound_lifetime(
            74,
            19,
            12,
            11,
            CYW43_SERVICE_WORK_DATA_TX,
        );
        assert!(
            !replacement_not_bound.ordinary_network_admissible(),
            "a current owner record cannot self-authorize a replacement lifetime"
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_service_snapshot_rejects_invalid_physical_lifetime_metadata() {
        let invalid_magic = pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
            magic: 0,
            begun_epoch: 13,
            completed_epoch: 13,
            failed_epoch: 0,
        };
        assert_eq!(
            cyw43_completed_physical_lifetime_epoch_from_record(Some(invalid_magic)),
            0,
            "matching epoch words cannot manufacture authority without the ABI magic"
        );

        let failed = pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
            begun_epoch: 13,
            completed_epoch: 13,
            failed_epoch: 13,
            ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
        };
        assert_eq!(
            cyw43_completed_physical_lifetime_epoch_from_record(Some(failed)),
            0,
            "a failed current lifetime must remain invalid"
        );

        let completed = pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
            begun_epoch: 13,
            completed_epoch: 13,
            ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
        };
        assert_eq!(
            cyw43_completed_physical_lifetime_epoch_from_record(Some(completed)),
            13
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_root_wake_is_a_wifi_only_steady_network_hint() {
        struct SnapshotReset;

        impl Drop for SnapshotReset {
            fn drop(&mut self) {
                set_cyw43_service_work_snapshot_test_override(None);
            }
        }

        let _reset = SnapshotReset;
        reset_cyw43_status_flags();
        assert!(crate::hal::driver_task::test_configure_cyw43_root_wake(
            true, 3,
        ));
        assert!(crate::hal::driver_task::cyw43_root_wake_pending());
        set_cyw43_service_work_snapshot_test_override(Some(Cyw43ServiceWorkSnapshot::for_test(
            75,
            20,
            12,
            CYW43_SERVICE_WORK_ROOT_WAKE,
        )));
        assert!(cyw43_steady_network_work_pending(
            CYW43_WIFI_DRIVER_TASK_CONTRACT
        ));
        assert!(!cyw43_steady_network_work_pending(
            GENET_DRIVER_TASK_CONTRACT
        ));

        assert!(!crate::hal::driver_task::clear_and_recheck_cyw43_root_wake_after_empty_rx(3));
        assert!(!crate::hal::driver_task::cyw43_root_wake_pending());
        let snapshot = crate::hal::driver_task::cyw43_root_wake_snapshot()
            .expect("CYW43 root-wake slot exists");
        assert!(!snapshot.pending);
        assert_ne!(snapshot.clears, 0);
        assert_eq!(snapshot.rechecks, 1);
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_root_wake_clears_only_on_exact_empty_data_poll_terminal() {
        let idle = DriverTaskCompletionCode::Idle.as_u16();
        assert!(cyw43_root_wake_clear_required(
            DRIVER_RUNTIME_CYW43_OP_RX_POLL,
            idle,
            Some(0),
        ));
        assert!(!cyw43_root_wake_clear_required(
            DRIVER_RUNTIME_CYW43_OP_RX_POLL,
            idle,
            Some(1),
        ));
        assert!(!cyw43_root_wake_clear_required(
            DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL,
            idle,
            Some(0),
        ));
        assert!(!cyw43_root_wake_clear_required(
            DRIVER_RUNTIME_CYW43_OP_RX_POLL,
            DriverTaskCompletionCode::Fault.as_u16(),
            Some(0),
        ));
        assert!(!cyw43_root_wake_clear_required(
            DRIVER_RUNTIME_CYW43_OP_RX_POLL,
            idle,
            None,
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn steady_network_dpc_urgency_rejects_stale_and_faulted_states() {
        let expected_generation =
            cyw43_sdio_dpc_expected_generation().expect("generated CYW43/SDIO link epoch");
        let healthy_ring = crate::hal::driver_task::DriverTaskSdioDpcRingSnapshot {
            epoch: expected_generation,
            producer: 12,
            consumer: 11,
            flags: DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_CARD_IRQ_MASKED,
            overruns: 0,
            ack_failures: 0,
        };
        assert!(cyw43_sdio_dpc_ring_work_pending(
            healthy_ring,
            Some(expected_generation)
        ));

        let mut stale_ring = healthy_ring;
        stale_ring.epoch ^= 1;
        let mut poisoned_ring = healthy_ring;
        poisoned_ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_POISONED;
        let mut overrun_ring = healthy_ring;
        overrun_ring.flags |= DRIVER_RUNTIME_DPC_EVENT_RING_FLAG_OVERRUN;
        let mut counted_overrun_ring = healthy_ring;
        counted_overrun_ring.overruns = 1;
        let mut ack_failed_ring = healthy_ring;
        ack_failed_ring.ack_failures = 1;
        let mut idle_ring = healthy_ring;
        idle_ring.producer = idle_ring.consumer;
        idle_ring.flags = 0;

        for (reason, ring, expected) in [
            ("missing-generation", healthy_ring, None),
            ("stale-generation", stale_ring, Some(expected_generation)),
            ("poisoned", poisoned_ring, Some(expected_generation)),
            ("overrun-flag", overrun_ring, Some(expected_generation)),
            (
                "overrun-counter",
                counted_overrun_ring,
                Some(expected_generation),
            ),
            ("ack-failed", ack_failed_ring, Some(expected_generation)),
            ("idle", idle_ring, Some(expected_generation)),
        ] {
            assert!(
                !cyw43_sdio_dpc_ring_work_pending(ring, expected),
                "{reason} DPC state must not earn EventPump urgency"
            );
        }

        let healthy_diagnostic = Cyw43SdioDpcDiagnostic {
            generation: expected_generation,
            captures: 12,
            published: 12,
            consumed: 11,
            sample_consumer: 11,
            rearms: 11,
            overruns: 0,
            epoch_errors: 0,
            sequence_errors: 0,
            ack_failures: 0,
            ring_poisoned: false,
            client_sample_stale: false,
            poisoned: false,
            masked: true,
        };
        assert!(cyw43_sdio_dpc_diagnostic_work_pending(
            healthy_diagnostic,
            Some(expected_generation)
        ));

        for (reason, snapshot) in [
            (
                "stale-generation",
                Cyw43SdioDpcDiagnostic {
                    generation: expected_generation ^ 1,
                    ..healthy_diagnostic
                },
            ),
            (
                "overrun-counter",
                Cyw43SdioDpcDiagnostic {
                    overruns: 1,
                    ..healthy_diagnostic
                },
            ),
            (
                "epoch-error",
                Cyw43SdioDpcDiagnostic {
                    epoch_errors: 1,
                    ..healthy_diagnostic
                },
            ),
            (
                "sequence-error",
                Cyw43SdioDpcDiagnostic {
                    sequence_errors: 1,
                    ..healthy_diagnostic
                },
            ),
            (
                "ack-failed",
                Cyw43SdioDpcDiagnostic {
                    ack_failures: 1,
                    ..healthy_diagnostic
                },
            ),
            (
                "ring-poisoned",
                Cyw43SdioDpcDiagnostic {
                    ring_poisoned: true,
                    ..healthy_diagnostic
                },
            ),
            (
                "client-sample-stale",
                Cyw43SdioDpcDiagnostic {
                    client_sample_stale: true,
                    ..healthy_diagnostic
                },
            ),
            (
                "aggregate-poisoned",
                Cyw43SdioDpcDiagnostic {
                    poisoned: true,
                    ..healthy_diagnostic
                },
            ),
            (
                "consumer-mismatch",
                Cyw43SdioDpcDiagnostic {
                    sample_consumer: 10,
                    ..healthy_diagnostic
                },
            ),
        ] {
            assert!(
                !cyw43_sdio_dpc_diagnostic_work_pending(snapshot, Some(expected_generation)),
                "{reason} diagnostic must not earn EventPump urgency"
            );
        }
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn dpc_client_counters_require_same_generation_v9_sample() {
        let _lock = CYW43_STATUS_TEST_LOCK
            .lock()
            .expect("cyw43 status test lock");
        reset_cyw43_status_flags();
        assert_eq!(cyw43_dpc_client_counters(4), None);

        CYW43_DPC_CLIENT_CONSUMED.store(6, Ordering::Relaxed);
        CYW43_DPC_CLIENT_REARMS.store(5, Ordering::Relaxed);
        CYW43_DPC_CLIENT_EPOCH_ERRORS.store(1, Ordering::Relaxed);
        CYW43_DPC_CLIENT_SEQUENCE_ERRORS.store(2, Ordering::Relaxed);
        CYW43_DPC_CLIENT_GENERATION.store(4, Ordering::Release);
        assert_eq!(
            cyw43_dpc_client_counters(4),
            Some(Cyw43DpcClientCounters {
                consumed: 6,
                rearms: 5,
                epoch_errors: 1,
                sequence_errors: 2,
            })
        );
        assert_eq!(cyw43_dpc_client_counters(5), None);
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn host_eapol_poll_progress_counts_trace_activity() {
        let empty_progress = DriverTaskCompletionRecord {
            sequence: 1,
            code: DriverTaskCompletionCode::Progress.as_u16(),
            detail: 0,
            result: 0,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        };
        assert!(!cyw43_poll_completion_made_service_progress(
            empty_progress,
            None
        ));

        let nonempty_progress = DriverTaskCompletionRecord {
            result: 1,
            ..empty_progress
        };
        assert!(cyw43_poll_completion_made_service_progress(
            nonempty_progress,
            None
        ));

        let traced_idle = DriverTaskCompletionRecord {
            sequence: 2,
            code: DriverTaskCompletionCode::Idle.as_u16(),
            detail: 0,
            result: 0,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        };
        assert!(!cyw43_poll_completion_made_service_progress(
            traced_idle,
            Some(Cyw43RxIdleTrace {
                valid: true,
                ..Cyw43RxIdleTrace::default()
            })
        ));
        assert!(cyw43_poll_completion_made_service_progress(
            traced_idle,
            Some(Cyw43RxIdleTrace {
                valid: true,
                queue_depth: 1,
                ..Cyw43RxIdleTrace::default()
            })
        ));
        assert!(cyw43_poll_completion_made_service_progress(
            traced_idle,
            Some(Cyw43RxIdleTrace {
                valid: true,
                source_flags: CYW43_RX_IDLE_TRACE_SOURCE_FLAG_PRE_ASSERTED,
                ..Cyw43RxIdleTrace::default()
            })
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn host_eapol_firstread_class_splits_quiet_and_asserted_sources() {
        let mut progress = Cyw43HostEapolProgress::default();
        assert_eq!(cyw43_host_eapol_firstread_class(&progress), "none");

        progress.record_rx_idle_completion(DriverTaskCompletionRecord {
            sequence: 1,
            code: DriverTaskCompletionCode::Idle.as_u16(),
            detail: DRIVER_RUNTIME_CYW43_RX_IDLE_DETAIL_FIRSTREAD_EMPTY,
            result: DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_MAGIC
                | 64
                | ((CYW43_SDIO_EXPECTED_IENX as u32)
                    << DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_IEN_SHIFT)
                | DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_FUNCTION2_READY,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        });
        assert_eq!(
            cyw43_host_eapol_firstread_class(&progress),
            "preassoc-cadence-empty"
        );

        progress.last_rx_trace.source_flags = CYW43_RX_IDLE_TRACE_SOURCE_FLAG_PRE_ASSERTED;
        assert_eq!(
            cyw43_host_eapol_firstread_class(&progress),
            "source-asserted-empty"
        );
        assert!(cyw43_host_eapol_source_asserted(&progress));

        progress.last_rx_trace.source_flags = CYW43_RX_IDLE_TRACE_SOURCE_FLAG_EVER_ASSERTED;
        assert_eq!(
            cyw43_host_eapol_firstread_class(&progress),
            "source-asserted-empty"
        );
        assert!(cyw43_host_eapol_source_asserted(&progress));

        progress.last_rx_trace.source_flags = 0;
        progress.last_rx_trace.pre_source_result = DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_MAGIC
            | 64
            | ((CYW43_SDIO_EXPECTED_IENX as u32)
                << DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_IEN_SHIFT)
            | DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_FUNCTION2_READY
            | DRIVER_RUNTIME_CYW43_RX_SOURCE_RESULT_FRAME_INDICATED;
        assert!(cyw43_host_eapol_source_asserted(&progress));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn host_eapol_firstread_cadence_services_pre_assoc_and_post_start() {
        assert!(cyw43_host_eapol_rx_firstread_due(0, 0, false));
        assert!(cyw43_host_eapol_rx_firstread_due(1, 0, false));
        assert!(!cyw43_host_eapol_rx_firstread_due(2, 0, false));
        assert!(cyw43_host_eapol_rx_firstread_due(4096, 0, false));
        assert!(cyw43_host_eapol_rx_firstread_due(
            CYW43_HOST_EAPOL_START_INTERVAL_POLLS,
            0,
            false
        ));
        assert!(!cyw43_host_eapol_rx_firstread_due(4097, 0, false));
        assert!(cyw43_host_eapol_rx_firstread_due(
            CYW43_HOST_EAPOL_START_FIRST_POLL,
            0,
            true
        ));
        assert!(!cyw43_host_eapol_rx_firstread_due(
            CYW43_HOST_EAPOL_START_FIRST_POLL + 1,
            0,
            true
        ));
        assert!(!cyw43_host_eapol_rx_firstread_due(
            CYW43_HOST_EAPOL_START_FIRST_POLL,
            1,
            true
        ));
        assert!(cyw43_host_eapol_rx_firstread_due(
            CYW43_HOST_EAPOL_START_FIRST_POLL + 1,
            1,
            true
        ));
        assert!(cyw43_host_eapol_rx_firstread_due(
            CYW43_HOST_EAPOL_START_FIRST_POLL + 1024,
            1,
            true
        ));
        assert!(!cyw43_host_eapol_rx_firstread_due(
            CYW43_HOST_EAPOL_START_FIRST_POLL + 1025,
            1,
            true
        ));
        let mut progress = Cyw43HostEapolProgress::default();
        progress.polls = 4097;
        assert!(!cyw43_host_eapol_rx_firstread_due_from_progress(
            progress.polls as usize,
            0,
            &progress
        ));
        progress.last_rx_source = Some(Cyw43RxSourceResult {
            probe_len: 64,
            interrupt_enable: CYW43_SDIO_EXPECTED_IENX,
            frame_indicated: true,
            host_interrupt: true,
            card_interrupt: false,
            function2_ready: true,
            passive: false,
            cached: false,
        });
        assert!(cyw43_host_eapol_rx_firstread_due_from_progress(
            progress.polls as usize,
            0,
            &progress
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn host_eapol_firstread_timer_slots_are_bounded() {
        let credentials = crate::net::WifiCredentials::new("cohesix", "passphrase")
            .expect("valid wifi credentials");
        let mut session =
            Cyw43HostEapolSession::new(credentials).expect("host eapol session starts");
        session.record_time(100);

        assert!(cyw43_host_eapol_rx_firstread_due_from_session(
            2,
            0,
            &mut session,
            100
        ));
        assert!(!cyw43_host_eapol_rx_firstread_due_from_session(
            2,
            0,
            &mut session,
            100
        ));
        assert!(cyw43_host_eapol_rx_firstread_due_from_session(
            2,
            0,
            &mut session,
            101
        ));
        assert!(!cyw43_host_eapol_rx_firstread_due_from_session(
            2,
            0,
            &mut session,
            101
        ));
        assert!(cyw43_host_eapol_rx_firstread_due_from_session(
            2,
            0,
            &mut session,
            104
        ));

        session.progress.associated = true;
        session.associated_ms = Some(200);
        session.last_eapol_start_ms = Some(200);
        assert!(!cyw43_host_eapol_rx_firstread_due_from_session(
            CYW43_HOST_EAPOL_START_FIRST_POLL,
            1,
            &mut session,
            200
        ));
        assert!(cyw43_host_eapol_rx_firstread_due_from_session(
            CYW43_HOST_EAPOL_START_FIRST_POLL,
            1,
            &mut session,
            201
        ));
        assert!(!cyw43_host_eapol_rx_firstread_due_from_session(
            CYW43_HOST_EAPOL_START_FIRST_POLL,
            1,
            &mut session,
            201
        ));
        assert!(cyw43_host_eapol_rx_firstread_due_from_session(
            CYW43_HOST_EAPOL_START_FIRST_POLL,
            1,
            &mut session,
            204
        ));
    }

