    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_parent_retry_authority_is_limited_to_single_action_preissue_faults() {
        let preissue = DriverTaskCompletionRecord {
            sequence: 17,
            code: DriverTaskCompletionCode::Fault.as_u16(),
            detail: CYW43_SDIO_DESCRIPTOR_TRANSFER_FAILED_DETAIL,
            result: 0x0100_0000,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        };
        for op in [
            DRIVER_RUNTIME_CYW43_OP_FIRMWARE_CHUNK,
            DRIVER_RUNTIME_CYW43_OP_NVRAM_CHUNK,
            DRIVER_RUNTIME_CYW43_OP_NVRAM_TAIL,
            DRIVER_RUNTIME_CYW43_OP_CONTROL_FRAME,
            DRIVER_RUNTIME_CYW43_OP_ETH_TX,
            DRIVER_RUNTIME_CYW43_OP_RX_POLL,
            DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL,
        ] {
            assert!(
                cyw43_parent_action_completion_allows_same_command_retry(op, preissue),
                "single-action op {op} may retry only after proven entry inhibit"
            );
            for stage in 2..=6 {
                assert!(!cyw43_parent_action_completion_allows_same_command_retry(
                    op,
                    DriverTaskCompletionRecord {
                        result: stage << 24,
                        ..preissue
                    },
                ));
            }
        }
        for op in [
            DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP,
            DRIVER_RUNTIME_CYW43_OP_RELEASE,
            DRIVER_RUNTIME_CYW43_OP_CONTROL_EXCHANGE,
        ] {
            assert!(
                !cyw43_parent_action_completion_allows_same_command_retry(op, preissue),
                "composite op {op} cannot inherit nested-child retry authority"
            );
        }
        assert!(!cyw43_parent_action_completion_allows_same_command_retry(
            DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL,
            DriverTaskCompletionRecord {
                detail: CYW43_SDIO_FUNCTION2_NOT_READY_DETAIL,
                ..preissue
            },
        ));
        assert!(!cyw43_parent_action_completion_allows_same_command_retry(
            DRIVER_RUNTIME_CYW43_OP_CONTROL_POLL,
            DriverTaskCompletionRecord::progress(17, 1),
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn optional_control_phases_never_advance_on_transport_faults() {
        let transport_fault = DriverTaskCompletionRecord {
            sequence: 19,
            code: DriverTaskCompletionCode::Fault.as_u16(),
            detail: CYW43_SDIO_DESCRIPTOR_TRANSFER_FAILED_DETAIL,
            result: 0x0100_0000,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        };
        let semantic_reject = DriverTaskCompletionRecord {
            detail: CYW43_CONTROL_EXCHANGE_FAULT_DETAIL,
            result: CYW43_BCME_UNSUPPORTED_STATUS,
            ..transport_fault
        };
        assert!(cyw43_runtime_command_fault_uart_trace_enabled(
            "cyw43-control-rsn-mfp",
            transport_fault,
        ));
        assert!(!cyw43_runtime_command_fault_uart_trace_enabled(
            "cyw43-control-rsn-mfp",
            semantic_reject,
        ));
        for phase in [
            Cyw43ControlPhase::ScanChannelTime,
            Cyw43ControlPhase::ScanUnassocTime,
            Cyw43ControlPhase::Txbf,
            Cyw43ControlPhase::ConnectArpOl,
            Cyw43ControlPhase::ConnectArpoe,
            Cyw43ControlPhase::ConnectNdoe,
            Cyw43ControlPhase::Mfp,
            Cyw43ControlPhase::HostEapolAllmulti,
            Cyw43ControlPhase::HostEapolPromisc,
        ] {
            let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
            supervisor.control_phase = phase;
            assert!(!cyw43_control_phase_allows_optional_fault(
                phase,
                transport_fault,
            ));
            assert!(cyw43_control_phase_allows_optional_fault(
                phase,
                semantic_reject,
            ));
            assert!(
                !supervisor.control_optional_fault(phase, transport_fault),
                "transport fault cannot be swallowed at {phase:?}"
            );
            assert_eq!(supervisor.control_phase, phase);

            assert!(
                supervisor.control_optional_fault(phase, semantic_reject),
                "valid firmware reject remains optional at {phase:?}"
            );
            assert_ne!(supervisor.control_phase, phase);
            if phase == Cyw43ControlPhase::HostEapolPromisc {
                assert_eq!(
                    supervisor.control_phase,
                    Cyw43ControlPhase::PreJoinDrain {
                        remaining: CYW43_CONTROL_PLANE_POLL_ATTEMPTS as u16,
                        idle_streak: 0,
                    },
                    "optional promisc rejection must still enter the pre-Join fence"
                );
            }
        }
        assert!(cyw43_control_phase_allows_optional_fault(
            Cyw43ControlPhase::UlpSdioCtrl,
            semantic_reject,
        ));
        assert!(cyw43_control_phase_allows_optional_fault(
            Cyw43ControlPhase::EventMaskExt(Cyw43EventMaskContinuation::Initial),
            semantic_reject,
        ));
        let badarg = DriverTaskCompletionRecord {
            result: CYW43_BCME_BADARG_STATUS,
            ..semantic_reject
        };
        assert!(!cyw43_control_phase_allows_optional_fault(
            Cyw43ControlPhase::UlpSdioCtrl,
            badarg,
        ));
        assert!(!cyw43_control_phase_allows_optional_fault(
            Cyw43ControlPhase::EventMaskExt(Cyw43EventMaskContinuation::Initial),
            badarg,
        ));
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn optional_control_semantic_rejects_do_not_replace_causal_fault() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        test_clear_cyw43_runtime_replay_status();
        begin_cyw43_bootstrap_causal_fault_capture();
        let causal = Cyw43RuntimeCommandFaultStatus {
            stage: "cyw43-transport-init",
            op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            flags: 0,
            target_addr: 0,
            payload_offset: 0,
            payload_len: 0,
            total_len: 0,
            control_cmd: 0,
            control_id: 0,
            control_header_mode: "none",
            control_response_len: 0,
            detail: 0x5319,
            reason: "cyw43-transport-high-speed",
            result: 0,
        };
        record_cyw43_runtime_command_fault_status(causal);
        let descriptor = cyw43_control_exchange_descriptor(
            24,
            CYW43_WLC_SET_VAR,
            7,
            Cyw43ControlHeaderMode::Extended,
            false,
        );

        for result in [CYW43_BCME_BADARG_STATUS, CYW43_BCME_UNSUPPORTED_STATUS] {
            let semantic_reject =
                cyw43_control_fault_completion(19, CYW43_CONTROL_EXCHANGE_FAULT_DETAIL, result);
            assert!(cyw43_control_phase_allows_optional_fault(
                Cyw43ControlPhase::Txbf,
                semantic_reject,
            ));
            emit_cyw43_runtime_command_fault_with_retention(
                CYW43_WIFI_DRIVER_TASK_CONTRACT,
                "cyw43-control-post-up-txbf",
                descriptor,
                semantic_reject,
                None,
                false,
            );
            assert_eq!(latest_cyw43_runtime_command_fault_status(), Some(causal));
            assert_eq!(
                bootstrap_causal_cyw43_runtime_command_fault_status(),
                Some(causal),
            );
        }

        let transport_fault = DriverTaskCompletionRecord {
            sequence: 20,
            code: DriverTaskCompletionCode::Fault.as_u16(),
            detail: CYW43_SDIO_DESCRIPTOR_TRANSFER_FAILED_DETAIL,
            result: 0x0100_0000,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        };
        assert!(!cyw43_control_phase_allows_optional_fault(
            Cyw43ControlPhase::Txbf,
            transport_fault,
        ));
        emit_cyw43_runtime_command_fault_with_retention(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            "cyw43-control-post-up-txbf",
            descriptor,
            transport_fault,
            None,
            true,
        );
        let latest = latest_cyw43_runtime_command_fault_status()
            .expect("a transport fault at the optional phase remains causal telemetry");
        assert_eq!(latest.stage, "cyw43-control-post-up-txbf");
        assert_eq!(latest.detail, CYW43_SDIO_DESCRIPTOR_TRANSFER_FAILED_DETAIL);
        assert_eq!(latest.result, 0x0100_0000);
        assert_eq!(
            bootstrap_causal_cyw43_runtime_command_fault_status(),
            Some(causal),
            "the first exact bootstrap terminal remains immutable",
        );

        test_clear_cyw43_runtime_replay_status();
        reset_cyw43_status_flags();
    }

