    #[cfg(feature = "kernel")]
    #[test]
    fn pair_restart_gate_blocker_does_not_infer_reciprocal_owner_intake() {
        let cyw43 = DriverTaskRingProgressSnapshot {
            marker_valid: true,
            sequence: 3,
            phase: pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_SDIO_PAIR_RESTART_REQUIRED,
            phase_name: "cyw43-sdio-pair-restart-required",
            aux0: DRIVER_RUNTIME_CYW43_COMMAND_AUX,
        };

        assert!(wifi_cyw43_sdio_pair_restart_blocks_gate_one(
            Some(cyw43),
            false,
        ));
        assert!(
            !wifi_cyw43_sdio_pair_restart_blocks_gate_one(Some(cyw43), true),
            "direct power-sequence proof must remain authoritative",
        );
        for cyw43_progress in [
            None,
            Some(DriverTaskRingProgressSnapshot {
                marker_valid: false,
                ..cyw43
            }),
            Some(DriverTaskRingProgressSnapshot {
                phase: pi4_driver_abi::DRIVER_RUNTIME_RING_PROGRESS_CYW43_SDIO_OWNER_WAIT_TIMEOUT,
                ..cyw43
            }),
            Some(DriverTaskRingProgressSnapshot { aux0: 0, ..cyw43 }),
        ] {
            assert!(
                !wifi_cyw43_sdio_pair_restart_blocks_gate_one(cyw43_progress, false,),
                "partial or mutated pair-restart evidence must fail closed",
            );
        }
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn sdio_engine_init_status_preserves_exact_fault_detail() {
        assert_eq!(
            sdio_engine_init_detail_status(DRIVER_RUNTIME_SDIO_INIT_DETAIL_WIFI_PWRSEQ_FAILED),
            Some("wifi-pwrseq-failed")
        );
        assert_eq!(
            sdio_engine_init_detail_status(
                DRIVER_RUNTIME_SDIO_INIT_DETAIL_WIFI_PWRSEQ_GET_CONFIG_FAILED,
            ),
            Some("wifi-pwrseq-get-config-failed")
        );
        assert_eq!(
            sdio_engine_init_detail_status(
                DRIVER_RUNTIME_SDIO_INIT_DETAIL_WIFI_PWRSEQ_SET_CONFIG_FAILED,
            ),
            Some("wifi-pwrseq-set-config-failed")
        );
        assert_eq!(
            sdio_engine_init_detail_status(
                DRIVER_RUNTIME_SDIO_INIT_DETAIL_WIFI_PWRSEQ_ASSERT_LOW_FAILED,
            ),
            Some("wifi-pwrseq-assert-low-failed")
        );
        assert_eq!(
            sdio_engine_init_detail_status(
                DRIVER_RUNTIME_SDIO_INIT_DETAIL_WIFI_PWRSEQ_RELEASE_HIGH_FAILED,
            ),
            Some("wifi-pwrseq-release-high-failed")
        );
        assert_eq!(
            sdio_engine_init_detail_status(DRIVER_RUNTIME_SDIO_INIT_DETAIL_STATUS_CLEAR_FAILED),
            Some("status-clear-failed")
        );
        assert_eq!(
            sdio_engine_init_detail_status(
                DRIVER_RUNTIME_RING_PROGRESS_RESOURCE_HOT_PATH_MISMATCH as u16,
            ),
            Some("resource-hot-path-mismatch")
        );
        assert_eq!(
            sdio_engine_init_completion_status(
                Some(DriverTaskCompletionRecord {
                    sequence: 2,
                    code: DriverTaskCompletionCode::Fault.as_u16(),
                    detail: DRIVER_RUNTIME_SDIO_INIT_DETAIL_CLOCK_FAILED,
                    result: 0,
                    frame: DriverFrameDescriptor {
                        offset: 0,
                        len: 0,
                        flags: 0,
                    },
                }),
                false,
            ),
            "clock-failed"
        );
        assert!(sdio_engine_init_completion_pending(None));
        assert!(!sdio_engine_init_completion_pending(Some(
            DriverTaskCompletionRecord::progress(2, 1)
        )));
        let protocol_reason = DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_GLOBAL_STATUS
            | DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_GPIO_TOKEN;
        assert_eq!(
            sdio_pwrseq_protocol_reason_bits(Some(DriverTaskCompletionRecord {
                sequence: 2,
                code: DriverTaskCompletionCode::Fault.as_u16(),
                detail: DRIVER_RUNTIME_SDIO_INIT_DETAIL_WIFI_PWRSEQ_SET_CONFIG_FAILED,
                result: DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_CLASS
                    | (protocol_reason << DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_REASON_SHIFT),
                frame: DriverFrameDescriptor {
                    offset: 0,
                    len: 0,
                    flags: 0,
                },
            })),
            Some(protocol_reason)
        );
        assert_eq!(
            sdio_pwrseq_protocol_reason_bits(Some(DriverTaskCompletionRecord {
                sequence: 2,
                code: DriverTaskCompletionCode::Fault.as_u16(),
                detail: DRIVER_RUNTIME_SDIO_INIT_DETAIL_CLOCK_FAILED,
                result: DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_CLASS
                    | (protocol_reason << DRIVER_RUNTIME_SDIO_PWRSEQ_PROTOCOL_REASON_SHIFT),
                frame: DriverFrameDescriptor {
                    offset: 0,
                    len: 0,
                    flags: 0,
                },
            })),
            None
        );
    }

