    #[test]
    fn gate8_stability_requires_secure_association_and_quiescent_control_lane() {
        let mut inputs = Cyw43Gate8Inputs {
            pair_scrub_epoch: 0,
            generation: 14,
            linked_pair_ready: true,
            control_program_valid: true,
            control_program_current: true,
            pair_failure: false,
            terminal_failure: false,
            join_owner_active: true,
            primary_join_ready: false,
            primary_join_current: false,
            associated: false,
            link_up: false,
            post_assoc_bssid_success: false,
            post_assoc_bssid_failure: false,
            open_network: false,
            host_eapol_active: true,
            host_eapol_required: false,
            host_eapol_secure: false,
            host_eapol_work_pending: true,
            maintenance_current: true,
            maintenance_pending: false,
            maintenance_required: 0,
            maintenance_completed: 0,
            maintenance_failed: 0,
            logical_control_owner_active: true,
            rejoin_pending: false,
            data_rx_admitted: false,
            control_plane_ready: false,
            data_handoff_generation_token: cyw43_epoch_token(14),
            data_handoff_generation_current: true,
            prompt_poll_active: false,
            prompt_poll_net_data: false,
            prompt_poll_request_assigned: false,
            prompt_poll_generation_current: true,
            root_rx_pending: false,
            data_tx_pending: false,
            arp_tx_pending: false,
            root_rx_queue_saturated: false,
            root_rx_drop_since_baseline: false,
            runtime_rx_overflow_since_baseline: false,
        };
        let join = evaluate_cyw43_gate8(inputs);
        assert_eq!(
            join.subgates[2].status,
            Cyw43Gate8SubgateStatus::Pending,
            "an accepted current Join owner is pending, never a terminal failure"
        );
        assert_eq!(join.subgates[2].blocker, "join-owner-active");

        inputs.join_owner_active = false;
        inputs.primary_join_ready = true;
        inputs.primary_join_current = true;
        inputs.associated = true;
        inputs.link_up = true;
        inputs.post_assoc_bssid_success = true;
        inputs.host_eapol_active = false;
        inputs.host_eapol_secure = true;
        inputs.host_eapol_work_pending = false;
        inputs.logical_control_owner_active = false;
        inputs.maintenance_required = CYW43_MAINTENANCE_POST_KEY_MASK;
        inputs.maintenance_completed = CYW43_MAINTENANCE_POST_KEY_MASK;
        inputs.data_rx_admitted = true;
        inputs.control_plane_ready = true;
        let stable = evaluate_cyw43_gate8(inputs);
        assert!(stable.stable());
        assert_eq!(
            stable
                .subgates
                .map(|subgate| (subgate.token, subgate.status)),
            [
                ("8a-pair-generation", Cyw43Gate8SubgateStatus::Pass),
                ("8b-control-program", Cyw43Gate8SubgateStatus::Pass),
                ("8c-join-terminal", Cyw43Gate8SubgateStatus::Pass),
                ("8d-association-link", Cyw43Gate8SubgateStatus::Pass),
                ("8e-bssid-refresh", Cyw43Gate8SubgateStatus::Pass),
                ("8f-eapol-keys", Cyw43Gate8SubgateStatus::Pass),
                ("8g-post-key-maintenance", Cyw43Gate8SubgateStatus::Pass,),
                ("8h-data-admission", Cyw43Gate8SubgateStatus::Pass),
            ]
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate8_ready_waits_for_queued_eapol_events_and_frames() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let generation = 41;
        mark_cyw43_gate8_ready_for_test(generation);
        assert!(cyw43_gate8_publication_quiescent(generation));

        cyw43_store_pending_host_eapol_event_record(Cyw43PendingHostEapolEvent {
            generation,
            state_admitted: true,
            event: Cyw43EventFrame {
                event_type: CYW43_EVENT_AUTH,
                status: CYW43_EVENT_STATUS_TIMEOUT,
                ..Cyw43EventFrame::default()
            },
            flags: DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_EVENT,
            len: CYW43_BRCMF_EVENT_MIN_PACKET_LEN as u16,
        });
        assert!(cyw43_host_eapol_runtime_work_pending());
        assert!(!cyw43_gate8_publication_quiescent(generation));
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[6],
            cyw43_gate8_record(
                "8g-post-key-maintenance",
                Cyw43Gate8SubgateStatus::Pending,
                "host-eapol-owner-active",
            ),
            "a queued firmware event cannot sit behind a published Ready boundary"
        );

        CYW43_HOST_EAPOL_PENDING_EVENTS.lock().clear();
        let mut eapol = [0u8; MAX_FRAME_LEN];
        let station = CYW43_DRIVER_TASK_MAC.0;
        let ap = [0xf0, 0x72, 0xea, 0x4c, 0xc7, 0xa5];
        let eapol_len =
            cyw43_host_eapol::write_test_m1_frame(&mut eapol, &station, &ap).expect("test M1");
        assert!(store_cyw43_pending_rx_token(
            DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_DATA,
            test_rx_token(&eapol[..eapol_len]),
        ));
        assert!(cyw43_pending_pre_secure_eapol_available());
        assert!(cyw43_host_eapol_runtime_work_pending());
        assert_eq!(
            cyw43_host_eapol_work_diagnostic(),
            Cyw43HostEapolWorkDiagnostic {
                generation,
                pending: true,
                blocker: "queued-eapol",
                open_network: false,
                deferred_reauth: false,
                prompt_poll: false,
                pending_events: 0,
                pending_eapol_frames: 1,
                pending_tx_submit: false,
                pending_key_install: false,
                pending_tx_drain: false,
                bssid_obligation: false,
            },
            "wifi diag must identify the exact leaf behind the aggregate 8g fence"
        );
        assert!(!cyw43_gate8_publication_quiescent(generation));
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[6],
            cyw43_gate8_record(
                "8g-post-key-maintenance",
                Cyw43Gate8SubgateStatus::Pending,
                "host-eapol-owner-active",
            ),
            "a queued current-generation EAPOL frame must drain before Ready"
        );

        CYW43_PENDING_RX_QUEUE.lock().clear();
        assert!(!cyw43_host_eapol_runtime_work_pending());
        assert_eq!(cyw43_host_eapol_work_diagnostic().blocker, "none");
        assert!(cyw43_gate8_publication_quiescent(generation));

        CYW43_OPEN_NETWORK_ACTIVE.store(1, Ordering::Release);
        cyw43_store_pending_host_eapol_event_record(Cyw43PendingHostEapolEvent {
            generation,
            state_admitted: true,
            event: Cyw43EventFrame {
                event_type: CYW43_EVENT_LINK,
                status: CYW43_EVENT_STATUS_SUCCESS,
                flags: CYW43_EVENT_FLAG_LINK,
                ..Cyw43EventFrame::default()
            },
            flags: DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_EVENT,
            len: CYW43_BRCMF_EVENT_MIN_PACKET_LEN as u16,
        });
        assert!(
            !cyw43_host_eapol_runtime_work_pending(),
            "open association state is applied at capture and has no host-EAPOL queue owner"
        );
        CYW43_HOST_EAPOL_PENDING_EVENTS.lock().clear();
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn retained_pre_recovery_gate8_tracks_latest_complete_snapshot_and_resets() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let mut inputs = stable_cyw43_gate8_inputs_for_test(23);
        inputs.primary_join_ready = false;
        inputs.primary_join_current = false;
        inputs.associated = false;
        inputs.link_up = false;
        let pending = evaluate_cyw43_gate8(inputs);
        record_cyw43_pre_recovery_gate8(pending);
        assert_eq!(cyw43_retained_pre_recovery_gate8(), Some(pending));

        crate::hal::driver_task::request_cyw43_sdio_pair_restart();
        let mut recovery_inputs = stable_cyw43_gate8_inputs_for_test(23);
        recovery_inputs.pair_failure = true;
        record_cyw43_pre_recovery_gate8(evaluate_cyw43_gate8(recovery_inputs));
        assert_eq!(
            cyw43_retained_pre_recovery_gate8(),
            Some(pending),
            "sticky recovery cannot overwrite the causal frontier with generic 8a failure"
        );
        crate::hal::driver_task::reset_cyw43_sdio_pair_recovery_for_test();

        let stable = evaluate_cyw43_gate8(stable_cyw43_gate8_inputs_for_test(23));
        record_cyw43_pre_recovery_gate8(stable);
        assert_eq!(cyw43_retained_pre_recovery_gate8(), Some(stable));

        reset_cyw43_status_flags();
        assert_eq!(cyw43_retained_pre_recovery_gate8(), None);
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate8_keeps_bssid_and_maintenance_terminals_in_logical_retry() {
        let ready = stable_cyw43_gate8_inputs_for_test(31);

        let mut bssid_failed = ready;
        bssid_failed.post_assoc_bssid_success = false;
        bssid_failed.post_assoc_bssid_failure = true;
        assert_eq!(
            evaluate_cyw43_gate8(bssid_failed).subgates[4],
            cyw43_gate8_record(
                "8e-bssid-refresh",
                Cyw43Gate8SubgateStatus::Pending,
                "bssid-refresh-retry-pending",
            )
        );

        let mut keys_failed = ready;
        keys_failed.host_eapol_required = true;
        keys_failed.host_eapol_secure = false;
        assert_eq!(
            evaluate_cyw43_gate8(keys_failed).subgates[5],
            cyw43_gate8_record(
                "8f-eapol-keys",
                Cyw43Gate8SubgateStatus::Fail,
                "host-eapol-required",
            )
        );

        let mut maintenance_failed = ready;
        maintenance_failed.maintenance_completed &= !CYW43_MAINTENANCE_SCB;
        maintenance_failed.maintenance_failed |= CYW43_MAINTENANCE_SCB;
        assert_eq!(
            evaluate_cyw43_gate8(maintenance_failed).subgates[6],
            cyw43_gate8_record(
                "8g-post-key-maintenance",
                Cyw43Gate8SubgateStatus::Pending,
                "post-key-maintenance-retry-pending",
            )
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate8_bssid_blocker_reports_host_eapol_prerequisite_before_owner() {
        let ready = stable_cyw43_gate8_inputs_for_test(37);

        let mut eapol_pending = ready;
        eapol_pending.post_assoc_bssid_success = false;
        eapol_pending.host_eapol_active = true;
        eapol_pending.host_eapol_secure = false;
        eapol_pending.host_eapol_work_pending = true;
        assert_eq!(
            evaluate_cyw43_gate8(eapol_pending).subgates[4],
            cyw43_gate8_record(
                "8e-bssid-refresh",
                Cyw43Gate8SubgateStatus::Pending,
                "host-eapol-prerequisite-pending",
            )
        );

        let mut eapol_required = eapol_pending;
        eapol_required.host_eapol_active = false;
        eapol_required.host_eapol_required = true;
        eapol_required.host_eapol_work_pending = false;
        eapol_required.post_assoc_bssid_failure = true;
        assert_eq!(
            evaluate_cyw43_gate8(eapol_required).subgates[4],
            cyw43_gate8_record(
                "8e-bssid-refresh",
                Cyw43Gate8SubgateStatus::Fail,
                "host-eapol-prerequisite-required",
            ),
            "the host-EAPOL prerequisite must outrank an impossible pre-secure BSSID owner"
        );
        assert!(
            !evaluate_cyw43_gate8(eapol_required).current_work_pending,
            "terminal host-EAPOL failure cannot advertise resumable Gate 8 work"
        );

        let mut bssid_owner_pending = ready;
        bssid_owner_pending.post_assoc_bssid_success = false;
        assert_eq!(
            evaluate_cyw43_gate8(bssid_owner_pending).subgates[4],
            cyw43_gate8_record(
                "8e-bssid-refresh",
                Cyw43Gate8SubgateStatus::Pending,
                "bssid-owner-terminal-pending",
            ),
            "BSSID-owner telemetry is valid only after secure keys make it issuable"
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate8_data_handoff_evaluator_reports_every_arbitration_and_loss_blocker() {
        let ready = stable_cyw43_gate8_inputs_for_test(17);
        assert!(evaluate_cyw43_gate8(ready).stable());

        let pending_cases = [
            {
                let mut inputs = ready;
                inputs.rejoin_pending = true;
                (inputs, "rejoin-pending")
            },
            {
                let mut inputs = ready;
                inputs.data_handoff_generation_current = false;
                (inputs, "data-handoff-commit-pending")
            },
            {
                let mut inputs = ready;
                inputs.data_handoff_generation_token = cyw43_epoch_token(16);
                (inputs, "data-handoff-commit-pending")
            },
            {
                let mut inputs = ready;
                inputs.prompt_poll_active = true;
                (inputs, "prompt-owner-active")
            },
            {
                let mut inputs = ready;
                inputs.root_rx_queue_saturated = true;
                (inputs, "root-rx-drain-pending")
            },
            {
                let mut inputs = ready;
                inputs.data_rx_admitted = false;
                (inputs, "data-rx-admission-pending")
            },
            {
                let mut inputs = ready;
                inputs.control_plane_ready = false;
                (inputs, "control-plane-ready-pending")
            },
        ];

        for (inputs, blocker) in pending_cases {
            let diagnostic = evaluate_cyw43_gate8(inputs);
            assert_eq!(
                diagnostic.subgates[7],
                cyw43_gate8_record(
                    "8h-data-admission",
                    Cyw43Gate8SubgateStatus::Pending,
                    blocker,
                ),
            );
            assert!(diagnostic.current_work_pending);
        }

        let fail_cases = [
            {
                let mut inputs = ready;
                inputs.prompt_poll_active = true;
                inputs.prompt_poll_net_data = true;
                inputs.prompt_poll_request_assigned = true;
                inputs.prompt_poll_generation_current = false;
                (inputs, "prompt-generation-stale")
            },
            {
                let mut inputs = ready;
                inputs.prompt_poll_active = true;
                inputs.prompt_poll_net_data = true;
                inputs.root_rx_pending = true;
                (inputs, "requestless-net-data-root-work-conflict")
            },
            {
                let mut inputs = ready;
                inputs.prompt_poll_active = true;
                inputs.prompt_poll_net_data = true;
                inputs.data_tx_pending = true;
                (inputs, "requestless-net-data-root-work-conflict")
            },
            {
                let mut inputs = ready;
                inputs.prompt_poll_active = true;
                inputs.prompt_poll_net_data = true;
                inputs.arp_tx_pending = true;
                (inputs, "requestless-net-data-root-work-conflict")
            },
            {
                let mut inputs = ready;
                inputs.root_rx_drop_since_baseline = true;
                (inputs, "root-rx-drop-since-generation")
            },
            {
                let mut inputs = ready;
                inputs.runtime_rx_overflow_since_baseline = true;
                (inputs, "runtime-rx-overflow-since-generation")
            },
        ];

        for (inputs, blocker) in fail_cases {
            let diagnostic = evaluate_cyw43_gate8(inputs);
            assert_eq!(
                diagnostic.subgates[7],
                cyw43_gate8_record("8h-data-admission", Cyw43Gate8SubgateStatus::Fail, blocker,),
            );
            assert!(!diagnostic.current_work_pending);
        }

        let mut ordinary_traffic = ready;
        ordinary_traffic.prompt_poll_active = true;
        ordinary_traffic.prompt_poll_net_data = true;
        ordinary_traffic.prompt_poll_request_assigned = true;
        ordinary_traffic.root_rx_pending = true;
        ordinary_traffic.data_tx_pending = true;
        ordinary_traffic.arp_tx_pending = true;
        assert!(
            evaluate_cyw43_gate8(ordinary_traffic).stable(),
            "an exact NetData continuation and bounded root work remain stable"
        );

        let mut fresh_requestless = ready;
        fresh_requestless.prompt_poll_active = true;
        fresh_requestless.prompt_poll_net_data = true;
        assert!(
            evaluate_cyw43_gate8(fresh_requestless).stable(),
            "fresh request-less NetData is safe while no priority root work exists"
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate8_consumer_commit_preserves_current_backlog_and_fails_later_loss() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let generation = 73;
        mark_cyw43_gate8_ready_for_test(generation);
        invalidate_cyw43_data_handoff();

        let flags = DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_DATA;
        let frame = test_cyw43_dhcp_frame(2, CYW43_DHCP_SERVER_PORT, CYW43_DHCP_CLIENT_PORT);
        for index in 0..CYW43_PENDING_RX_QUEUE_CAP {
            let mut queued = frame;
            queued[18] = index as u8;
            assert!(store_cyw43_pending_rx_token(flags, test_rx_token(&queued)));
        }
        record_cyw43_pending_rx_drop(
            "preconsumer-test",
            generation,
            flags,
            Some(&test_rx_token(&frame)),
            CYW43_PENDING_RX_QUEUE_CAP,
        );

        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Pending,
                "data-handoff-commit-pending",
            ),
            "pre-consumer pressure is not post-handoff loss"
        );
        assert!(commit_cyw43_data_handoff_if_ready(generation));
        let committed = cyw43_data_handoff_diagnostic();
        assert!(committed.committed);
        assert_eq!(
            committed.root_rx_queue_len, CYW43_PENDING_RX_QUEUE_CAP as u32,
            "current-generation backlog remains available to the first NetStack poll"
        );
        assert_eq!(committed.stale_rx_purged_total, 0);
        assert_eq!(committed.root_rx_drops, committed.baseline_root_rx_drops);
        assert_eq!(
            committed
                .boot_first_loss
                .expect("boot-first loss evidence retained")
                .reason,
            "preconsumer-test"
        );
        assert!(committed.postcommit_first_loss.is_none());
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Pending,
                "root-rx-drain-pending",
            ),
        );
        assert!(take_cyw43_pending_rx_token().is_some());
        assert!(cyw43_gate8_diagnostic().stable());
        assert!(
            !cyw43_current_generation_data_consumer_open(),
            "8h candidate proof cannot open data before Ready publication"
        );
        assert!(publish_cyw43_gate8_data_consumer_for_test(generation));
        assert!(cyw43_current_generation_data_consumer_open());

        assert!(store_cyw43_pending_rx_token(flags, test_rx_token(&frame)));
        assert!(
            commit_cyw43_data_handoff_if_ready(generation),
            "same-generation commit is idempotent"
        );
        assert_eq!(
            cyw43_data_handoff_diagnostic().root_rx_queue_len,
            CYW43_PENDING_RX_QUEUE_CAP as u32,
            "an idempotent commit must not purge postcommit traffic"
        );
        while take_cyw43_pending_rx_token().is_some() {}

        record_cyw43_pending_rx_drop(
            "postcommit-test",
            generation,
            flags,
            Some(&test_rx_token(&frame)),
            0,
        );
        let failed = cyw43_data_handoff_diagnostic();
        assert_eq!(
            failed
                .boot_first_loss
                .expect("boot-first loss remains retained")
                .reason,
            "preconsumer-test"
        );
        assert_eq!(
            failed
                .postcommit_first_loss
                .expect("postcommit first loss is independently retained")
                .reason,
            "postcommit-test"
        );
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Fail,
                "root-rx-drop-since-generation",
            ),
        );
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn pending_rx_rejects_stale_generation_and_does_not_charge_current_gate8() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let stale_generation = 80;
        CYW43_CONNECTION_EPOCH.store(stale_generation, Ordering::Release);
        invalidate_cyw43_data_handoff();
        let flags = DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_DATA;
        let frame = test_cyw43_dhcp_frame(2, CYW43_DHCP_SERVER_PORT, CYW43_DHCP_CLIENT_PORT);
        assert!(store_cyw43_pending_rx_token(flags, test_rx_token(&frame)));

        let current_generation = stale_generation.wrapping_add(1);
        CYW43_CONNECTION_EPOCH.store(current_generation, Ordering::Release);
        assert!(
            take_cyw43_pending_rx_token().is_none(),
            "a token captured in the superseded generation is never delivered"
        );
        let stale = cyw43_data_handoff_diagnostic();
        assert_eq!(stale.root_rx_queue_len, 0);
        assert_eq!(stale.stale_rx_purged_total, 1);
        assert_eq!(
            stale.last_stale_purge_epoch_token,
            cyw43_epoch_token(current_generation)
        );
        assert_eq!(stale.last_stale_purge_count, 1);

        mark_cyw43_gate8_ready_for_test(current_generation);
        record_cyw43_pending_rx_drop(
            "delayed-old-generation-loss",
            stale_generation,
            flags,
            Some(&test_rx_token(&frame)),
            0,
        );
        assert!(
            cyw43_gate8_diagnostic().stable(),
            "a sampled old-generation loss cannot be charged to current Gate 8h"
        );
        assert!(
            cyw43_data_handoff_diagnostic()
                .postcommit_first_loss
                .is_none(),
            "old-generation loss cannot overwrite current postcommit evidence"
        );

        record_cyw43_pending_rx_drop(
            "current-generation-loss",
            current_generation,
            flags,
            Some(&test_rx_token(&frame)),
            0,
        );
        let current = cyw43_data_handoff_diagnostic();
        assert_eq!(
            current
                .postcommit_first_loss
                .expect("current postcommit loss retained")
                .reason,
            "current-generation-loss"
        );
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Fail,
                "root-rx-drop-since-generation",
            ),
        );
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn live_gate8_data_handoff_allows_traffic_and_fails_generation_local_loss() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let generation = 41;
        mark_cyw43_gate8_ready_for_test(generation);
        assert!(cyw43_gate8_diagnostic().stable());

        let flags = DRIVER_RUNTIME_CYW43_FRAME_FLAG_CHANNEL_DATA;
        let frame = test_cyw43_dhcp_frame(2, CYW43_DHCP_SERVER_PORT, CYW43_DHCP_CLIENT_PORT);
        assert!(store_cyw43_pending_rx_token(flags, test_rx_token(&frame)));
        assert!(submit_cyw43_driver_task_eth_frame(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            b"gate8-data-tx",
        ));
        assert!(queue_cyw43_arp_frame([0u8; 42]));
        CYW43_RX_RUNTIME_QUEUE_COUNT.store(1, Ordering::Release);
        *CYW43_PENDING_PROMPT_POLL.lock() = Some(Cyw43PendingPromptPoll {
            ticket_id: 0x4741_5445,
            owner: Cyw43PromptPollOwner::NetData,
            generation,
            descriptor: DriverRuntimeCyw43CommandDescriptor {
                op: DRIVER_RUNTIME_CYW43_OP_RX_POLL,
                flags: CYW43_DATA_RX_STEADY_POLL_FLAGS,
                ..DriverRuntimeCyw43CommandDescriptor::empty()
            },
            request: Some(0x92),
            issued: true,
            deadline: cyw43_poll_deadline_from_millis_or_polls(
                cyw43_linked_action_child_lease_ms(DRIVER_RUNTIME_CYW43_OP_RX_POLL),
                cyw43_linked_action_fallback_polls(DRIVER_RUNTIME_CYW43_OP_RX_POLL),
            ),
            child_reply_latched: false,
            child_reply_renewals: 0,
        });
        assert!(cyw43_net_data_pre_poll_continuation_pending(
            CYW43_WIFI_DRIVER_TASK_CONTRACT
        ));
        assert!(
            cyw43_gate8_diagnostic().stable(),
            "exact NetData, non-full root RX, pending TX/ARP, and runtime backlog are normal traffic"
        );

        {
            let mut prompt = CYW43_PENDING_PROMPT_POLL.lock();
            let prompt = prompt.as_mut().expect("NetData prompt retained");
            prompt.request = None;
            prompt.issued = false;
        }
        assert!(!cyw43_net_data_pre_poll_continuation_pending(
            CYW43_WIFI_DRIVER_TASK_CONTRACT
        ));
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Fail,
                "requestless-net-data-root-work-conflict",
            ),
        );
        *CYW43_PENDING_PROMPT_POLL.lock() = None;
        assert!(take_cyw43_pending_rx_token().is_some());
        *CYW43_PENDING_DATA_TX.lock() = None;
        CYW43_PENDING_ARP_TX.lock().clear();
        CYW43_RX_RUNTIME_QUEUE_COUNT.store(0, Ordering::Release);

        let drops_at_baseline = CYW43_PENDING_RX_DROPS.load(Ordering::Acquire);
        for index in 0..CYW43_PENDING_RX_QUEUE_CAP {
            let mut queued = frame;
            queued[18] = index as u8;
            assert!(store_cyw43_pending_rx_token(flags, test_rx_token(&queued)));
        }
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Pending,
                "root-rx-drain-pending",
            ),
        );
        assert_eq!(
            CYW43_PENDING_RX_DROPS.load(Ordering::Acquire),
            drops_at_baseline,
            "reaching the declared cap is diagnosed before an actual drop"
        );
        for _ in 0..CYW43_PENDING_RX_QUEUE_CAP {
            assert!(take_cyw43_pending_rx_token().is_some());
        }
        assert!(cyw43_gate8_diagnostic().stable());

        record_cyw43_pending_rx_drop("postcommit-test", generation, flags, None, 0);
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Fail,
                "root-rx-drop-since-generation",
            ),
        );
        let next_generation = generation.wrapping_add(1);
        mark_cyw43_gate8_ready_for_test(next_generation);
        assert!(
            cyw43_gate8_diagnostic().stable(),
            "a recovery generation starts from current cumulative telemetry"
        );

        record_cyw43_pending_rx_drop("post-recovery-test", next_generation, flags, None, 0);
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Fail,
                "root-rx-drop-since-generation",
            ),
        );

        let overflow_generation = next_generation.wrapping_add(1);
        mark_cyw43_gate8_ready_for_test(overflow_generation);
        assert!(cyw43_gate8_diagnostic().stable());
        record_cyw43_runtime_overflow_episodes(1);
        CYW43_RX_RUNTIME_QUEUE_OVERFLOW_SEEN.store(1, Ordering::Release);
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Fail,
                "runtime-rx-overflow-since-generation",
            ),
        );

        let recovered_overflow_generation = overflow_generation.wrapping_add(1);
        mark_cyw43_gate8_ready_for_test(recovered_overflow_generation);
        assert!(
            cyw43_gate8_diagnostic().stable(),
            "boot telemetry remains sticky but the new generation baseline is clean"
        );
        record_cyw43_runtime_overflow_episodes(1);
        assert!(
            cyw43_gate8_diagnostic().stable(),
            "repeating the same cumulative runtime sample is not a new episode"
        );
        record_cyw43_runtime_overflow_episodes(0);
        assert!(cyw43_gate8_diagnostic().stable());
        record_cyw43_runtime_overflow_episodes(1);
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Fail,
                "runtime-rx-overflow-since-generation",
            ),
            "a post-reset runtime overflow is a new generation-local loss episode"
        );

        let saturated_drop_generation = recovered_overflow_generation.wrapping_add(1);
        CYW43_PENDING_RX_DROPS.store(u32::MAX, Ordering::Release);
        mark_cyw43_gate8_ready_for_test(saturated_drop_generation);
        assert!(
            cyw43_gate8_diagnostic().stable(),
            "a saturated boot counter is clean at the exact new-generation baseline"
        );
        record_cyw43_pending_rx_drop("test-injected", saturated_drop_generation, 0, None, 0);
        assert_eq!(
            CYW43_PENDING_RX_DROPS.load(Ordering::Acquire),
            u32::MAX,
            "the cumulative diagnostic saturates instead of wrapping"
        );
        assert_eq!(
            cyw43_gate8_diagnostic().subgates[7],
            cyw43_gate8_record(
                "8h-data-admission",
                Cyw43Gate8SubgateStatus::Fail,
                "root-rx-drop-since-generation",
            ),
            "the exact-generation loss latch remains fail-closed at counter saturation"
        );

        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn runtime_overflow_episode_counts_equal_first_sample_after_pair_restart() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        CYW43_PAIR_SCRUB_EPOCH.store(41, Ordering::Release);

        record_cyw43_runtime_overflow_episodes(1);
        assert_eq!(
            CYW43_RX_RUNTIME_OVERFLOW_EPISODES.load(Ordering::Acquire),
            1
        );

        CYW43_PAIR_SCRUB_EPOCH.store(42, Ordering::Release);
        record_cyw43_runtime_overflow_episodes(1);
        assert_eq!(
            CYW43_RX_RUNTIME_OVERFLOW_EPISODES.load(Ordering::Acquire),
            2,
            "the first post-restart sample is new even when it equals the prior runtime"
        );

        CYW43_PAIR_SCRUB_EPOCH.store(43, Ordering::Release);
        record_cyw43_runtime_overflow_episodes(3);
        assert_eq!(
            CYW43_RX_RUNTIME_OVERFLOW_EPISODES.load(Ordering::Acquire),
            5,
            "the whole first post-restart sample belongs to the new pair"
        );

        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate8_stability_preserves_the_one_repair_limit_until_gate10() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        mark_cyw43_gate8_ready_for_test(23);
        let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
        supervisor.phase = Cyw43BootstrapPhase::Complete;
        supervisor.ready_generation = Some(0);
        supervisor.ready_pair_scrub_epoch = Some(CYW43_PAIR_SCRUB_EPOCH.load(Ordering::Acquire));
        supervisor.pair_restarts = CYW43_SUPERVISOR_PAIR_RESTART_LIMIT;
        let _sdio_lifetime_guard = test_bind_completed_physical_lifetime(&mut supervisor, 1);
        retain_first_cyw43_deferred_recovery_diagnostic(
            Cyw43DeferredRecovery::pair_signal(23, 99),
            "cyw43-host-eapol-control-poll",
        );

        let snapshot = cyw43_gate8_diagnostic();
        assert!(supervisor.mark_gate8_generation_stable(snapshot));
        assert_eq!(supervisor.gate8_generation, Some(23));
        assert_eq!(
            supervisor.pair_restarts, 1,
            "Gate 8 must not erase a repair already spent in this boot episode"
        );
        assert_eq!(
            supervisor.pair_restart_limit,
            CYW43_SUPERVISOR_PAIR_RESTART_LIMIT
        );
        assert!(
            cyw43_deferred_recovery_diagnostic().is_some(),
            "revocable Gate 8 snapshot acceptance must retain first-cause telemetry"
        );
        assert!(!supervisor.mark_gate8_generation_stable(snapshot));
        assert!(!supervisor.commit_gate8_ready_publication(24));
        assert!(
            cyw43_deferred_recovery_diagnostic().is_some(),
            "a rejected Ready publication must not erase first-cause telemetry"
        );
        assert!(supervisor.commit_gate8_ready_publication(23));
        assert_eq!(cyw43_deferred_recovery_diagnostic(), None);

        assert!(!supervisor.mark_ready_generation_stable(false));
        assert_eq!(supervisor.pair_restarts, 1);
        assert!(supervisor.mark_ready_generation_stable(true));
        assert_eq!(supervisor.pair_restarts, 0);
        assert_eq!(
            supervisor.pair_restart_limit,
            CYW43_SUPERVISOR_PAIR_RESTART_LIMIT
        );
        assert_eq!(supervisor.stable_generation, Some(23));
        assert!(!supervisor.mark_ready_generation_stable(true));

        supervisor.arm_generation_recovery("post-stability-independent-fault");
        assert_eq!(supervisor.gate8_generation, None);
        assert_eq!(supervisor.stable_generation, None);
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate8_ready_continuity_keeps_bounded_post_secure_maintenance_online() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let generation = 23;
        mark_cyw43_gate8_ready_for_test(generation);
        let pair_scrub_epoch = CYW43_PAIR_SCRUB_EPOCH.load(Ordering::Acquire);
        let snapshot = cyw43_gate8_diagnostic();
        let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
        supervisor.phase = Cyw43BootstrapPhase::Complete;
        supervisor.ready_generation = Some(0);
        supervisor.ready_pair_scrub_epoch = Some(pair_scrub_epoch);
        let _sdio_lifetime_guard = test_bind_completed_physical_lifetime(&mut supervisor, 1);
        assert!(supervisor.mark_gate8_generation_stable(snapshot));
        assert!(supervisor.gate8_generation_still_operational(snapshot));

        let credentials = crate::net::WifiCredentials::new("cohesix", "passphrase")
            .expect("valid wifi credentials");
        let mut session =
            Cyw43HostEapolSession::new(credentials).expect("host EAPOL session starts");
        session.progress.connection_epoch = generation;
        session.progress.associated = true;
        session.progress.link_up = true;
        session.progress.secure_keys_ready = true;
        session.bssid_refreshed_after_assoc = true;
        begin_cyw43_group_gtk_install(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            &mut session,
            test_group_install_keys(),
            &[0x5a; 113],
            true,
        )
        .expect("begin post-secure group GTK transaction");
        assert_eq!(
            session
                .pending_key_install
                .as_ref()
                .expect("post-secure GTK remains retained")
                .stage,
            "cyw43-host-eapol-post-secure-gtk",
        );
        *CYW43_HOST_EAPOL_SESSION.lock() = Some(session);
        let maintenance = cyw43_gate8_diagnostic();
        assert!(maintenance.subgates[..6]
            .iter()
            .all(|subgate| subgate.status == Cyw43Gate8SubgateStatus::Pass));
        assert_eq!(
            maintenance.subgates[6],
            cyw43_gate8_record(
                "8g-post-key-maintenance",
                Cyw43Gate8SubgateStatus::Pending,
                "host-eapol-owner-active",
            ),
        );
        assert!(
            !supervisor.gate8_generation_still_stable(),
            "initial/Gate10 quiescence remains stricter than Ready continuity",
        );
        assert!(
            supervisor.gate8_generation_still_operational(maintenance),
            "same-generation post-secure control work keeps the published consumer online",
        );
        assert!(cyw43_current_generation_data_consumer_open());

        CYW43_PENDING_RX_DROP_EPOCH_TOKEN.store(cyw43_epoch_token(generation), Ordering::Release);
        assert!(
            !supervisor.gate8_generation_still_operational(cyw43_gate8_diagnostic()),
            "post-publication data loss remains a material continuity failure",
        );

        CYW43_PENDING_RX_DROP_EPOCH_TOKEN.store(0, Ordering::Release);
        *CYW43_HOST_EAPOL_SESSION.lock() = None;
        CYW43_LINK_UP.store(0, Ordering::Release);
        assert!(
            !supervisor.gate8_generation_still_operational(cyw43_gate8_diagnostic()),
            "carrier loss cannot hide behind the retained publication token",
        );
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate8_commit_separates_pair_epoch_from_connection_generation_and_rejects_torn_snapshot() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        CYW43_PAIR_SCRUB_EPOCH.store(7, Ordering::Release);
        mark_cyw43_gate8_ready_for_test(23);
        let snapshot = cyw43_gate8_diagnostic();
        assert_eq!(snapshot.pair_scrub_epoch, 7);
        assert_eq!(snapshot.generation, 23);

        let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
        supervisor.phase = Cyw43BootstrapPhase::Complete;
        supervisor.ready_generation = Some(0);
        supervisor.ready_pair_scrub_epoch = Some(7);
        let _sdio_lifetime_guard = test_bind_completed_physical_lifetime(&mut supervisor, 1);
        assert!(
            supervisor.mark_gate8_generation_stable(snapshot),
            "normal first Join may advance the logical generation without changing the pair epoch"
        );

        assert!(supervisor.retract_gate8_generation(23));
        let torn = cyw43_gate8_diagnostic();
        CYW43_CONNECTION_EPOCH.store(24, Ordering::Release);
        assert!(
            !supervisor.mark_gate8_generation_stable(torn),
            "a connection epoch change between capture and commit must reject the snapshot"
        );
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate8_and_gate10_reject_missing_active_failed_or_replaced_physical_lifetimes() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        let generation = 37;
        mark_cyw43_gate8_ready_for_test(generation);
        let snapshot = cyw43_gate8_diagnostic();
        let completed = pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
            begun_epoch: 4,
            completed_epoch: 4,
            ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
        };
        let invalid_lifetimes = [
            (
                "missing",
                pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty(),
            ),
            (
                "active",
                pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
                    begun_epoch: 4,
                    ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
                },
            ),
            (
                "failed",
                pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
                    begun_epoch: 4,
                    failed_epoch: 4,
                    ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
                },
            ),
            (
                "replaced",
                pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord {
                    begun_epoch: 5,
                    completed_epoch: 5,
                    ..pi4_driver_abi::DriverRuntimeSdioPhysicalLifetimeRecord::empty()
                },
            ),
        ];

        for (label, record) in invalid_lifetimes {
            let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
            supervisor.phase = Cyw43BootstrapPhase::Complete;
            supervisor.ready_generation = Some(0);
            supervisor.ready_pair_scrub_epoch =
                Some(CYW43_PAIR_SCRUB_EPOCH.load(Ordering::Acquire));
            supervisor.physical_lifetime_epoch = Some(4);
            CYW43_BOUND_PHYSICAL_LIFETIME_EPOCH.store(4, Ordering::Release);
            let mut sdio_lifetime_guard = test_publish_sdio_ring();
            sdio_lifetime_guard.publish_physical_lifetime(record);
            assert!(
                !supervisor.mark_gate8_generation_stable(snapshot),
                "Gate 8 admitted a {label} physical lifetime",
            );
        }

        let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
        supervisor.phase = Cyw43BootstrapPhase::Complete;
        supervisor.ready_generation = Some(0);
        supervisor.ready_pair_scrub_epoch = Some(CYW43_PAIR_SCRUB_EPOCH.load(Ordering::Acquire));
        let mut sdio_lifetime_guard = test_bind_completed_physical_lifetime(&mut supervisor, 4);
        assert!(supervisor.mark_gate8_generation_stable(snapshot));

        for (label, record) in invalid_lifetimes {
            sdio_lifetime_guard.publish_physical_lifetime(record);
            assert!(
                !supervisor.commit_gate8_ready_publication(generation),
                "Ready publication admitted a {label} physical lifetime",
            );
            assert!(
                !supervisor.gate8_generation_still_stable(),
                "Gate 8 stability crossed a {label} physical lifetime",
            );
            assert!(
                !supervisor.gate8_generation_still_operational(cyw43_gate8_diagnostic()),
                "an operational data consumer crossed a {label} physical lifetime",
            );
            assert!(
                !supervisor.mark_ready_generation_stable(true),
                "Gate 10 admitted a {label} physical lifetime",
            );
            sdio_lifetime_guard.publish_physical_lifetime(completed);
            assert!(
                supervisor.physical_lifetime_current(),
                "the valid baseline lifetime was not restored after {label}",
            );
        }
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn gate10_reset_requires_the_current_accepted_gate8_generation() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        reset_cyw43_status_flags();
        mark_cyw43_gate8_ready_for_test(52);
        let snapshot = cyw43_gate8_diagnostic();
        let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
        supervisor.phase = Cyw43BootstrapPhase::Complete;
        supervisor.ready_generation = Some(0);
        supervisor.ready_pair_scrub_epoch = Some(CYW43_PAIR_SCRUB_EPOCH.load(Ordering::Acquire));
        let _sdio_lifetime_guard = test_bind_completed_physical_lifetime(&mut supervisor, 1);
        assert!(supervisor.mark_gate8_generation_stable(snapshot));

        CYW43_CONNECTION_EPOCH.store(53, Ordering::Release);
        assert!(!supervisor.mark_ready_generation_stable(true));
        assert_eq!(supervisor.stable_generation, None);
        reset_cyw43_status_flags();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_firmware_recovery_preserves_completion_detail() {
        let completion = DriverTaskCompletionRecord {
            sequence: 7,
            code: DriverTaskCompletionCode::Fault.as_u16(),
            detail: 0x5102,
            result: 0,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        };
        let err = Cyw43FirmwareInitError::Command(Cyw43CommandSubmitError::Completion(completion));

        assert_eq!(err.recoverable_completion(), Some(completion));
        assert_eq!(err.same_command_retry_completion(), None);
        let transfer_failed = DriverTaskCompletionRecord {
            sequence: 9,
            code: DriverTaskCompletionCode::Fault.as_u16(),
            detail: 0x5103,
            result: 0,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        };
        let retry =
            Cyw43FirmwareInitError::Command(Cyw43CommandSubmitError::Completion(transfer_failed));
        assert_eq!(retry.recoverable_completion(), Some(transfer_failed));
        assert_eq!(retry.same_command_retry_completion(), None);
        assert_eq!(
            retry.generation_recovery_completion(),
            Some(transfer_failed)
        );
        let not_issued = DriverTaskCompletionRecord {
            result: 1 << 24,
            ..transfer_failed
        };
        let retry =
            Cyw43FirmwareInitError::Command(Cyw43CommandSubmitError::Completion(not_issued));
        assert_eq!(retry.same_command_retry_completion(), Some(not_issued));
        assert_eq!(retry.generation_recovery_completion(), None);

        assert_eq!(
            Cyw43CommandSubmitError::Completion(not_issued)
                .not_issued_same_command_retry_completion(),
            Some(not_issued)
        );
        assert_eq!(
            Cyw43CommandSubmitError::Completion(transfer_failed)
                .not_issued_same_command_retry_completion(),
            None
        );
        let issued_crc = DriverTaskCompletionRecord {
            result: (3 << 24) | SDHCI_INT_DATA_CRC,
            ..transfer_failed
        };
        assert_eq!(
            Cyw43CommandSubmitError::Completion(issued_crc)
                .not_issued_same_command_retry_completion(),
            None
        );
        let post_issue_inhibit = DriverTaskCompletionRecord {
            result: (6 << 24) | 0x2,
            ..transfer_failed
        };
        assert_eq!(
            Cyw43CommandSubmitError::Completion(post_issue_inhibit)
                .not_issued_same_command_retry_completion(),
            None
        );
        assert_eq!(
            Cyw43FirmwareInitError::Command(Cyw43CommandSubmitError::Completion(
                post_issue_inhibit,
            ))
            .generation_recovery_completion(),
            Some(post_issue_inhibit)
        );
        let rejected = DriverTaskCompletionRecord {
            sequence: 8,
            code: DriverTaskCompletionCode::Fault.as_u16(),
            detail: 0x5302,
            result: 0,
            frame: DriverFrameDescriptor {
                offset: 0,
                len: 0,
                flags: 0,
            },
        };
        assert_eq!(
            Cyw43FirmwareInitError::Command(Cyw43CommandSubmitError::Completion(rejected))
                .recoverable_completion(),
            None
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn sdio_fault_telemetry_decode_matches_runtime_wire_layout() {
        let mut bytes = [0u8; SDIO_FAULT_TELEMETRY_BYTES];
        put_le_u32(&mut bytes, 0, SDIO_FAULT_TELEMETRY_MAGIC);
        put_le_u32(&mut bytes, 4, SDIO_FAULT_TELEMETRY_VERSION);
        put_le_u32(&mut bytes, SDIO_FAULT_TELEMETRY_ARG_OFFSET, 0x9401_0000);
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_CMD_FLAGS_OFFSET,
            53 | (0x0021 << 16),
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_LEN_BLOCK_OFFSET,
            512 | (512 << 16),
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_COUNT_MODE_OFFSET,
            1 | (0x0002 << 16),
        );
        put_le_u32(&mut bytes, SDIO_FAULT_TELEMETRY_PRESENT_OFFSET, 0x0003_0000);
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_INT_STATUS_OFFSET,
            0x0020_8040,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_RESPONSE0_OFFSET,
            0x0000_0100,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_HOST_CLOCK_OFFSET,
            0x1234_0e06,
        );
        put_le_u32(&mut bytes, SDIO_FAULT_TELEMETRY_FAILURE_OFFSET, 0x0500_0100);
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_BLOCK_REG_OFFSET,
            0x0001_0200,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_PAYLOAD_EDGE_OFFSET,
            0x0033_2211,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_PAYLOAD_SUM_OFFSET,
            0x0000_4444,
        );
        put_le_u32(&mut bytes, SDIO_FAULT_TELEMETRY_DMA_CS_OFFSET, 0x0000_0002);
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_DMA_CONBLK_OFFSET,
            0xc010_2000,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_DMA_NEXTCB_OFFSET,
            0xc010_2020,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_ARGUMENT_REG_OFFSET,
            0x9401_0000,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_TRANSFER_COMMAND_REG_OFFSET,
            0x352a_0022,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_TIMEOUT_GAP_REG_OFFSET,
            0x0000_000e,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_INT_ENABLE_REG_OFFSET,
            0x02ff_010b,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_SIGNAL_ENABLE_REG_OFFSET,
            0x0000_0100,
        );
        put_le_u32(
            &mut bytes,
            SDIO_FAULT_TELEMETRY_HOST_CONTROL2_REG_OFFSET,
            0x0000_0400,
        );
        for (offset, value) in [
            (SDIO_FAULT_TELEMETRY_DMA_TI_OFFSET, 0x000b_0148),
            (SDIO_FAULT_TELEMETRY_DMA_SOURCE_OFFSET, 0xc100_1080),
            (SDIO_FAULT_TELEMETRY_DMA_DEST_OFFSET, 0x7e30_0020),
            (SDIO_FAULT_TELEMETRY_DMA_LEN_OFFSET, 0x0000_0780),
            (SDIO_FAULT_TELEMETRY_DMA_STRIDE_OFFSET, 0),
            (SDIO_FAULT_TELEMETRY_DMA_DEBUG_OFFSET, 0x0000_0007),
        ] {
            put_le_u32(&mut bytes, offset, value);
        }

        let snapshot = SdioFaultTelemetry::decode(&bytes).expect("valid telemetry");

        assert_eq!(snapshot.cmd, 53);
        assert_eq!(snapshot.flags, 0x0021);
        assert!(snapshot.cmd53_write());
        assert_eq!(snapshot.cmd53_function(), 1);
        assert!(snapshot.cmd53_increment());
        assert!(!snapshot.cmd53_block_mode());
        assert_eq!(snapshot.len, 512);
        assert_eq!(snapshot.block_size, 512);
        assert_eq!(snapshot.block_count, 1);
        assert_eq!(snapshot.transfer_mode, 0x0002);
        assert_eq!(snapshot.host_control, 0x06);
        assert_eq!(snapshot.power_control, 0x0e);
        assert_eq!(snapshot.clock_control, 0x1234);
        assert_eq!(snapshot.failure_result, 0x0500_0100);
        assert_eq!(snapshot.payload_first, 0x11);
        assert_eq!(snapshot.payload_last, 0x22);
        assert_eq!(snapshot.payload_xor, 0x33);
        assert_eq!(snapshot.payload_sum, 0x4444);
        assert_eq!(snapshot.dma_cs, 0x0000_0002);
        assert_eq!(snapshot.dma_conblk, 0xc010_2000);
        assert_eq!(snapshot.dma_nextcb, 0xc010_2020);
        let registers =
            SdioFaultTelemetryRegisters::decode(&bytes).expect("valid v3 register telemetry");
        assert_eq!(registers.argument, 0x9401_0000);
        assert_eq!(registers.transfer_command, 0x352a_0022);
        assert_eq!(registers.timeout_control, 0x0e);
        assert_eq!(registers.block_gap_control, 0);
        assert_eq!(registers.int_enable, 0x02ff_010b);
        assert_eq!(registers.signal_enable, 0x0000_0100);
        assert_eq!(registers.host_control2, 0x0400);
        assert_eq!(registers.dma_ti, 0x000b_0148);
        assert_eq!(registers.dma_source, 0xc100_1080);
        assert_eq!(registers.dma_dest, 0x7e30_0020);
        assert_eq!(registers.dma_len, 0x0000_0780);
        assert_eq!(registers.dma_stride, 0);
        assert_eq!(registers.dma_debug, 7);
        assert_eq!(
            sdio_transfer_failure_stage_label(snapshot.failure_result),
            "response"
        );
        assert_eq!(
            sdio_transfer_failure_reason_label(snapshot.failure_result),
            "sdio-r5-response"
        );
        assert_eq!(sdio_transfer_failure_r5(snapshot.failure_result), 0x0100);

        assert!(
            SdioFaultTelemetry::decode(&bytes[..SDIO_FAULT_TELEMETRY_BYTES.saturating_sub(1)])
                .is_none()
        );
        assert!(SdioFaultTelemetryRegisters::decode(
            &bytes[..SDIO_FAULT_TELEMETRY_BYTES.saturating_sub(1)]
        )
        .is_none());
        for version in [
            SDIO_FAULT_TELEMETRY_VERSION.saturating_sub(1),
            SDIO_FAULT_TELEMETRY_VERSION.saturating_add(1),
        ] {
            let mut mismatched = bytes;
            put_le_u32(&mut mismatched, 4, version);
            assert!(SdioFaultTelemetry::decode(&mismatched).is_none());
            assert!(SdioFaultTelemetryRegisters::decode(&mismatched).is_none());
        }
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn sdio_transfer_failure_reason_decodes_data_crc_finish() {
        let result = 0x0400_0000 | SDHCI_INT_ERROR | SDHCI_INT_DATA_CRC | 0x40;

        assert_eq!(sdio_transfer_failure_stage_label(result), "data-end");
        assert_eq!(
            sdio_transfer_failure_reason_label(result),
            "sdhci-transfer-finish-data-crc"
        );
        let post_issue = 0x0600_0002;
        assert_eq!(
            sdio_transfer_failure_stage_label(post_issue),
            "post-issue-quiesce"
        );
        assert_eq!(
            sdio_transfer_failure_reason_label(post_issue),
            "sdhci-post-issue-quiesce"
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn sdio_owner_fault_decodes_function2_byte_count_separately_from_host_block_count() {
        let txglomalign = SdioFaultTelemetry {
            arg: 0xa500_0030,
            cmd: 53,
            flags: 0,
            len: 48,
            block_size: 48,
            block_count: 1,
            transfer_mode: 0x0002,
            present_state: 0,
            int_status: 0,
            response0: 0,
            host_control: 0x06,
            power_control: 0x0f,
            clock_control: 0x0307,
            failure_result: 0x0420_8000,
            block_size_count_reg: 0x0001_0030,
            payload_first: 0,
            payload_last: 0,
            payload_xor: 0,
            payload_sum: 0,
            dma_cs: 0,
            dma_conblk: 0,
            dma_nextcb: 0,
        };

        assert_eq!(txglomalign.cmd53_function(), 2);
        assert_eq!(txglomalign.cmd53_addr(), CYW43_BACKPLANE_32BIT_FLAG);
        assert!(txglomalign.cmd53_write());
        assert!(txglomalign.cmd53_increment());
        assert!(!txglomalign.cmd53_block_mode());
        assert_eq!(txglomalign.cmd53_count(), 48);
        assert_eq!(txglomalign.cmd53_descriptor_block_count(), 0);
        assert_eq!(txglomalign.block_count, 1);
        assert_eq!(sdio_fault_transfer_mode_label(txglomalign), "byte");
        assert_eq!(
            sdio_host_control_mode_label(txglomalign.host_control),
            "4bit+hispd-unexpected"
        );
        assert_eq!(
            sdio_host_control_mode_label(SDHCI_HOST_CONTROL_4BIT),
            "4bit+bcm2835-no-hispd"
        );
        assert_eq!(
            sdio_clock_control_state_label(txglomalign.clock_control),
            "internal+stable+card"
        );

        let block_mode = SdioFaultTelemetry {
            arg: (1 << 31) | (2 << 28) | (1 << 27) | (CYW43_BACKPLANE_32BIT_FLAG << 9) | 3,
            len: 1536,
            block_size: 512,
            block_count: 3,
            block_size_count_reg: 0x0003_0200,
            ..txglomalign
        };
        assert!(block_mode.cmd53_block_mode());
        assert_eq!(block_mode.cmd53_count(), 3);
        assert_eq!(block_mode.cmd53_descriptor_block_count(), 3);
        assert_eq!(block_mode.block_count, 3);
        assert_eq!(sdio_fault_transfer_mode_label(block_mode), "block");
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_owner_retry_label_reports_generation_safe_replay_contract() {
        let primary = SdioFaultTelemetry {
            arg: (1 << 31) | (1 << 28) | (1 << 27) | (1 << 26),
            cmd: 53,
            flags: 0,
            len: 2048,
            block_size: 64,
            block_count: 32,
            transfer_mode: 0x0022,
            present_state: 0,
            int_status: 0,
            response0: 0,
            host_control: 0x06,
            power_control: 0x0f,
            clock_control: 0x5007,
            failure_result: 0x0500_0800,
            block_size_count_reg: 0,
            payload_first: 0,
            payload_last: 0,
            payload_xor: 0,
            payload_sum: 0,
            dma_cs: 0,
            dma_conblk: 0,
            dma_nextcb: 0,
        };
        let byte = SdioFaultTelemetry {
            arg: (1 << 31) | (1 << 28) | (1 << 26) | 64,
            cmd: 53,
            flags: 0,
            len: 64,
            block_size: 64,
            block_count: 1,
            transfer_mode: 0x0002,
            present_state: 0,
            int_status: 0,
            response0: 0,
            host_control: 0x00,
            power_control: 0x0f,
            clock_control: 0x0007,
            failure_result: 0x0500_0800,
            block_size_count_reg: 0,
            payload_first: 0,
            payload_last: 0,
            payload_xor: 0,
            payload_sum: 0,
            dma_cs: 0,
            dma_conblk: 0,
            dma_nextcb: 0,
        };
        assert_eq!(
            cyw43_owner_retry_label(primary, 0x5103, 0x0400_0000),
            "no-replay-issued-unknown"
        );
        assert_eq!(
            cyw43_owner_retry_label(
                SdioFaultTelemetry {
                    host_control: 0x00,
                    clock_control: 0x0007,
                    ..primary
                },
                0x5103,
                0x0400_0000,
            ),
            "no-replay-issued-unknown"
        );
        assert_eq!(
            cyw43_owner_retry_label(byte, 0x5103, 0x0400_0000),
            "no-replay-issued-unknown"
        );
        assert_eq!(
            cyw43_owner_retry_label(byte, 0x5329, 0x0400_0000),
            "generation-recovery-required"
        );
        assert_eq!(
            cyw43_owner_retry_label(byte, 0x5103, 0x0100_0000),
            "pre-issue-retry-admissible"
        );
        let card_command = SdioFaultTelemetry {
            cmd: 5,
            len: 0,
            block_size: 1,
            block_count: 0,
            ..byte
        };
        assert_eq!(
            cyw43_owner_retry_label(card_command, 0x5325, 0x0100_0000),
            "none"
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_owner_primary_lanes_cover_ai_control_and_atomic_pmucontrol_word() {
        let descriptor = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        let snapshot = SdioFaultTelemetry {
            arg: (1 << 28) | (1 << 26) | (CYW43_BACKPLANE_32BIT_FLAG << 9) | 4,
            cmd: 53,
            flags: 0,
            len: 4,
            block_size: 4,
            block_count: 1,
            transfer_mode: 0x0010,
            present_state: 0,
            int_status: 0,
            response0: 0,
            host_control: 0,
            power_control: 0x0f,
            clock_control: 0x3947,
            failure_result: 0x0201_8000,
            block_size_count_reg: 0x0001_0004,
            payload_first: 0,
            payload_last: 0,
            payload_xor: 0,
            payload_sum: 0,
            dma_cs: 0,
            dma_conblk: 0,
            dma_nextcb: 0,
        };

        assert!(cyw43_owner_ai_control_primary(descriptor, snapshot, 0x5325));
        assert!(!cyw43_owner_ai_control_primary(
            descriptor,
            SdioFaultTelemetry {
                arg: snapshot.arg & !(1 << 26),
                ..snapshot
            },
            0x5325
        ));
        let release = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_RELEASE,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        assert!(cyw43_owner_ai_control_primary(
            release,
            SdioFaultTelemetry {
                arg: (1 << 28) | (0x0a408 << 9),
                cmd: 52,
                len: 1,
                ..snapshot
            },
            0x531f
        ));
        let firmware_prep = DriverRuntimeCyw43CommandDescriptor {
            op: DRIVER_RUNTIME_CYW43_OP_FIRMWARE_PREP,
            ..DriverRuntimeCyw43CommandDescriptor::empty()
        };
        let pmu_bus_addr = (CYW43_CHIPCOMMON_PMUCONTROL_ADDR & CYW43_BACKPLANE_ADDRESS_MASK)
            | CYW43_BACKPLANE_32BIT_FLAG;
        for (detail, write) in [(0x5333, false), (0x5334, true)] {
            let arg =
                (1 << 28) | (1 << 26) | (pmu_bus_addr << 9) | 4 | if write { 1 << 31 } else { 0 };
            assert_eq!(
                cyw43_owner_probe_pmucontrol_primary_target(
                    firmware_prep,
                    SdioFaultTelemetry {
                        arg,
                        cmd: 53,
                        len: 4,
                        block_size: 4,
                        block_count: 1,
                        ..snapshot
                    },
                    detail,
                ),
                Some(CYW43_CHIPCOMMON_PMUCONTROL_ADDR),
            );
        }
        assert_eq!(
            cyw43_owner_probe_pmucontrol_primary_target(
                firmware_prep,
                SdioFaultTelemetry {
                    arg: (1 << 31) | (1 << 28) | (1 << 26) | (pmu_bus_addr << 9) | 4,
                    cmd: 53,
                    len: 4,
                    ..snapshot
                },
                0x5333,
            ),
            None,
            "read detail cannot describe a CMD53 write"
        );
        assert_eq!(
            cyw43_owner_probe_pmucontrol_primary_target(
                firmware_prep,
                SdioFaultTelemetry {
                    arg: (1 << 28) | (pmu_bus_addr << 9) | 0xa5,
                    cmd: 52,
                    len: 1,
                    ..snapshot
                },
                0x5333,
            ),
            None,
            "the retired CMD52 byte lane cannot satisfy PMUCONTROL proof"
        );
        assert_eq!(
            cyw43_owner_probe_pmucontrol_primary_target(
                firmware_prep,
                SdioFaultTelemetry {
                    arg: (1 << 31) | (1 << 28) | (1 << 26) | ((pmu_bus_addr + 1) << 9) | 4,
                    cmd: 53,
                    len: 4,
                    ..snapshot
                },
                0x5334,
            ),
            None,
            "PMUCONTROL word proof requires the exact Function-1 address 0x8600"
        );
        assert_eq!(
            cyw43_owner_probe_pmucontrol_primary_target(
                firmware_prep,
                SdioFaultTelemetry {
                    arg: (1 << 31) | (1 << 28) | (pmu_bus_addr << 9) | 4,
                    cmd: 53,
                    len: 4,
                    ..snapshot
                },
                0x5334,
            ),
            None,
            "PMUCONTROL word proof requires an incrementing CMD53"
        );
        assert_eq!(
            cyw43_owner_probe_pmucontrol_primary_target(
                firmware_prep,
                SdioFaultTelemetry {
                    arg: (1 << 31) | (1 << 28) | (1 << 26) | (pmu_bus_addr << 9) | 3,
                    cmd: 53,
                    len: 4,
                    ..snapshot
                },
                0x5334,
            ),
            None,
            "PMUCONTROL word proof requires a four-byte command count"
        );

        let pmu_write_snapshot = SdioFaultTelemetry {
            arg: (1 << 31) | (1 << 28) | (1 << 26) | (pmu_bus_addr << 9) | 4,
            cmd: 53,
            len: 4,
            block_size: 4,
            block_count: 1,
            failure_result: 0x0500_0800,
            ..snapshot
        };
        let emission = derive_cyw43_sdio_owner_fault_emission(
            "cyw43-firmware-prep",
            firmware_prep,
            0x5334,
            pmu_write_snapshot.failure_result,
            pmu_write_snapshot,
        );
        assert_eq!(
            emission.status.effective_target,
            CYW43_CHIPCOMMON_PMUCONTROL_ADDR,
        );
        assert_eq!(emission.status.chunk_offset, u32::MAX);
        assert_eq!(emission.status.payload_offset, u32::MAX);
        assert_eq!(
            emission.status.owner_window,
            "probe-pmucontrol-cmd53-word-primary",
        );
        assert_eq!(emission.status.retry, "no-replay-issued-unknown");
        assert_eq!(emission.status.cmd, 53);
        assert_eq!(emission.status.function, 1);
        assert_eq!(emission.status.addr, pmu_bus_addr);
        assert!(emission.status.increment);
        assert!(emission.status.write);
        assert!(!emission.status.block_mode);
        assert_eq!(emission.status.len, 4);
        assert_eq!(emission.status.cmd53_count, 4);
        assert_eq!(emission.status.detail, 0x5334);
        assert_eq!(emission.status.r5, 0x0800);

        let pmu_read_snapshot = SdioFaultTelemetry {
            arg: (1 << 28) | (1 << 26) | (pmu_bus_addr << 9) | 4,
            failure_result: 0x0500_0800,
            ..pmu_write_snapshot
        };
        let read_emission = derive_cyw43_sdio_owner_fault_emission(
            "cyw43-firmware-prep",
            firmware_prep,
            0x5333,
            pmu_read_snapshot.failure_result,
            pmu_read_snapshot,
        );
        assert_eq!(
            read_emission.status.effective_target,
            CYW43_CHIPCOMMON_PMUCONTROL_ADDR,
        );
        assert_eq!(
            read_emission.status.owner_window,
            "probe-pmucontrol-cmd53-word-primary",
        );
        assert_eq!(read_emission.status.retry, "no-replay-issued-unknown");
        assert_eq!(read_emission.status.cmd, 53);
        assert_eq!(read_emission.status.function, 1);
        assert_eq!(read_emission.status.addr, pmu_bus_addr);
        assert!(read_emission.status.increment);
        assert!(!read_emission.status.write);
        assert!(!read_emission.status.block_mode);
        assert_eq!(read_emission.status.len, 4);
        assert_eq!(read_emission.status.cmd53_count, 4);
        assert_eq!(read_emission.status.detail, 0x5333);

        assert_eq!(
            cyw43_owner_probe_pmucontrol_primary_target(
                DriverRuntimeCyw43CommandDescriptor {
                    op: DRIVER_RUNTIME_CYW43_OP_RELEASE,
                    ..DriverRuntimeCyw43CommandDescriptor::empty()
                },
                pmu_write_snapshot,
                0x5334,
            ),
            None,
            "only the firmware-prep owner may issue PMUCONTROL probes"
        );
    }

