    #[cfg(feature = "kernel")]
    #[test]
    fn host_eapol_wsec_key_uses_oldgood_control_reply_window() {
        assert_eq!(CYW43_HOST_EAPOL_WSEC_KEY_POLL_ATTEMPTS, 16_384);
        assert_eq!(CYW43_HOST_EAPOL_GTK_WSEC_KEY_POLL_ATTEMPTS, 16_384);
        assert_eq!(CYW43_HOST_EAPOL_POST_SECURE_WSEC_KEY_POLL_ATTEMPTS, 512);
        assert_eq!(CYW43_CONTROL_PLANE_REPLY_TIMEOUT_MS, 1_000);
        assert_eq!(CYW43_HOST_EAPOL_WSEC_KEY_REPLY_TIMEOUT_MS, 5_000);
        assert_eq!(CYW43_HOST_EAPOL_GTK_WSEC_KEY_REPLY_TIMEOUT_MS, 5_000);
        assert_eq!(CYW43_HOST_EAPOL_POST_SECURE_WSEC_KEY_REPLY_TIMEOUT_MS, 250);
        assert_eq!(CYW43_HOST_EAPOL_WSEC_KEY_LATE_REPLY_WINDOWS, 3);
        assert_eq!(CYW43_HOST_EAPOL_GTK_WSEC_KEY_LATE_REPLY_WINDOWS, 2);
        assert_eq!(CYW43_HOST_EAPOL_M2_TX_DRAIN_POLLS, 8);
        assert_eq!(CYW43_HOST_EAPOL_M2_TX_DRAIN_TIMEOUT_MS, 0);
        assert_eq!(CYW43_HOST_EAPOL_TX_DRAIN_POLLS, 2_000);
        assert_eq!(CYW43_HOST_EAPOL_TX_DRAIN_TIMEOUT_MS, 2_000);
        assert_eq!(
            cyw43_host_eapol_tx_drain_window("m4-before-wsec"),
            (
                CYW43_HOST_EAPOL_TX_DRAIN_TIMEOUT_MS,
                CYW43_HOST_EAPOL_TX_DRAIN_POLLS
            )
        );
        assert_eq!(
            cyw43_host_eapol_tx_drain_window("post-secure-m4-before-wsec"),
            (
                CYW43_HOST_EAPOL_TX_DRAIN_TIMEOUT_MS,
                CYW43_HOST_EAPOL_TX_DRAIN_POLLS
            )
        );
        assert_eq!(
            cyw43_host_eapol_tx_drain_window("m2-before-m3"),
            (
                CYW43_HOST_EAPOL_M2_TX_DRAIN_TIMEOUT_MS,
                CYW43_HOST_EAPOL_M2_TX_DRAIN_POLLS
            )
        );
        assert_eq!(
            cyw43_control_exchange_poll_attempts("cyw43-host-eapol-ptk", "wsec_key"),
            CYW43_HOST_EAPOL_WSEC_KEY_POLL_ATTEMPTS
        );
        assert_eq!(
            cyw43_control_exchange_timeout_ms("cyw43-host-eapol-ptk", "wsec_key"),
            CYW43_HOST_EAPOL_WSEC_KEY_REPLY_TIMEOUT_MS
        );
        assert_eq!(
            cyw43_control_exchange_poll_attempts("cyw43-host-eapol-gtk", "wsec_key"),
            CYW43_HOST_EAPOL_GTK_WSEC_KEY_POLL_ATTEMPTS
        );
        assert_eq!(
            cyw43_control_exchange_timeout_ms("cyw43-host-eapol-gtk", "wsec_key"),
            CYW43_HOST_EAPOL_GTK_WSEC_KEY_REPLY_TIMEOUT_MS
        );
        assert_eq!(
            cyw43_control_exchange_poll_attempts("cyw43-host-eapol-post-secure-ptk", "wsec_key"),
            CYW43_HOST_EAPOL_POST_SECURE_WSEC_KEY_POLL_ATTEMPTS
        );
        assert_eq!(
            cyw43_control_exchange_timeout_ms("cyw43-host-eapol-post-secure-ptk", "wsec_key"),
            CYW43_HOST_EAPOL_POST_SECURE_WSEC_KEY_REPLY_TIMEOUT_MS
        );
        assert_eq!(
            cyw43_control_exchange_poll_attempts("cyw43-host-eapol-post-secure-gtk", "wsec_key"),
            CYW43_HOST_EAPOL_POST_SECURE_WSEC_KEY_POLL_ATTEMPTS
        );
        assert_eq!(
            cyw43_control_exchange_timeout_ms("cyw43-host-eapol-post-secure-gtk", "wsec_key"),
            CYW43_HOST_EAPOL_POST_SECURE_WSEC_KEY_REPLY_TIMEOUT_MS
        );
        assert!(!cyw43_control_uses_host_eapol_wsec_key_reply_window(
            "cyw43-host-eapol-post-secure-ptk",
            "wsec_key"
        ));
        assert!(
            cyw43_control_uses_post_secure_host_eapol_wsec_key_reply_window(
                "cyw43-host-eapol-post-secure-ptk",
                "wsec_key"
            )
        );
        assert_eq!(
            cyw43_host_eapol_wsec_key_late_reply_window_limit("cyw43-host-eapol-ptk"),
            CYW43_HOST_EAPOL_WSEC_KEY_LATE_REPLY_WINDOWS
        );
        assert_eq!(
            cyw43_host_eapol_wsec_key_late_reply_window_limit("cyw43-host-eapol-gtk"),
            CYW43_HOST_EAPOL_GTK_WSEC_KEY_LATE_REPLY_WINDOWS
        );
        assert_eq!(
            cyw43_host_eapol_wsec_key_late_reply_window_limit("cyw43-host-eapol-post-secure-gtk"),
            CYW43_HOST_EAPOL_WSEC_KEY_LATE_REPLY_WINDOWS
        );
        assert_eq!(
            cyw43_control_exchange_poll_attempts("cyw43-control-security-wpa2-psk", "wsec"),
            CYW43_CONTROL_PLANE_POLL_ATTEMPTS
        );
        assert_eq!(
            cyw43_control_exchange_timeout_ms("cyw43-control-security-wpa2-psk", "wsec"),
            CYW43_CONTROL_PLANE_REPLY_TIMEOUT_MS
        );
        assert_eq!(
            cyw43_control_exchange_poll_attempts("cyw43-control-wpa-auth-final", "wpa_auth"),
            CYW43_CONTROL_PLANE_POLL_ATTEMPTS
        );
        assert_eq!(
            cyw43_control_exchange_timeout_ms("cyw43-control-wpa-auth-final", "wpa_auth"),
            CYW43_CONTROL_PLANE_REPLY_TIMEOUT_MS
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn host_eapol_wsec_key_continues_after_stale_nonmatching_reply() {
        let _guard = CYW43_STATUS_TEST_LOCK.lock().expect("status test lock");
        test_clear_cyw43_runtime_replay_status();
        assert!(cyw43_host_eapol_wsec_key_continuation_fault("cyw43-host-eapol-ptk").is_none());

        let descriptor = cyw43_control_exchange_descriptor(
            209,
            CYW43_WLC_SET_VAR,
            39,
            Cyw43ControlHeaderMode::Extended,
            true,
        );
        record_cyw43_control_split_failure(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            "cyw43-host-eapol-ptk",
            descriptor,
            "cyw43-control-reply-nonmatching",
            None,
            CYW43_WLC_SET_VAR,
            39,
            Cyw43ControlHeaderMode::Extended,
            0,
            "wsec_key",
            1,
            0,
        );

        let fault = cyw43_host_eapol_wsec_key_continuation_fault("cyw43-host-eapol-ptk")
            .expect("stale nonmatching PTK wsec_key fault should continue polling");
        assert_eq!(fault.stage, "cyw43-host-eapol-ptk");
        assert_eq!(fault.reason, "cyw43-control-reply-nonmatching");
        assert!(
            cyw43_host_eapol_wsec_key_continuation_fault("cyw43-control-txglomalign").is_none()
        );

        emit_cyw43_runtime_command_fault(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            "cyw43-host-eapol-ptk",
            descriptor,
            cyw43_control_fault_completion(
                1027,
                CYW43_CONTROL_EXCHANGE_FAULT_DETAIL,
                cyw43_control_exchange_timeout_result(
                    CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_NONMATCHING_REPLY,
                    1,
                ),
            ),
            None,
        );
        let fault = cyw43_host_eapol_wsec_key_continuation_fault("cyw43-host-eapol-ptk")
            .expect("encoded nonmatching timeout should keep the PTK reply window open");
        assert_eq!(fault.reason, "cyw43-control-exchange");
        assert_eq!(fault.result, 0x4308_0001);
        assert_eq!(
            cyw43_control_exchange_timeout_result_reason(fault.result),
            Some(CYW43_CONTROL_EXCHANGE_TIMEOUT_REASON_NONMATCHING_REPLY)
        );

        record_cyw43_control_split_failure(
            CYW43_WIFI_DRIVER_TASK_CONTRACT,
            "cyw43-host-eapol-ptk",
            cyw43_control_exchange_descriptor(
                209,
                CYW43_WLC_SET_VAR,
                40,
                Cyw43ControlHeaderMode::Extended,
                false,
            ),
            "cyw43-control-reply-nonmatching",
            None,
            CYW43_WLC_SET_VAR,
            40,
            Cyw43ControlHeaderMode::Extended,
            0,
            "wsec_key",
            1,
            0,
        );
        assert!(cyw43_host_eapol_wsec_key_continuation_fault("cyw43-host-eapol-ptk").is_none());
        clear_cyw43_runtime_command_fault_status();
    }

