    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_control_request_iovar_info_extracts_txglomalign_value() {
        let mut frame = [0u8; MAX_DRIVER_TASK_FRAME_BYTES];
        let mut payload = [0u8; 20];
        payload[..15].copy_from_slice(b"bus:txglomalign");
        payload[16..20].copy_from_slice(&8u32.to_le_bytes());
        let len = cyw43_write_bcdc_frame(
            &mut frame,
            CYW43_WLC_SET_VAR,
            CYW43_BCDC_FLAG_SET,
            1,
            &payload,
        )
        .expect("txglomalign BCDC frame should fit");
        let info = cyw43_control_iovar_info(&frame[..len], CYW43_WLC_SET_VAR)
            .expect("txglomalign iovar should decode");
        let (digest_len, digest_scope) = cyw43_control_request_digest_len(len, Some(info));

        assert_eq!(len, 36);
        assert_eq!(info.name, "bus:txglomalign");
        assert_eq!(info.data_len, 4);
        assert_eq!(info.value_u32, Some(8));
        assert_eq!(
            cyw43_read_le_u16(&frame[..len], 8),
            Some(CYW43_BCDC_FLAG_SET)
        );
        assert_eq!(digest_len, len);
        assert_eq!(digest_scope, "full");
        assert_eq!(Cyw43ControlHeaderMode::Plain.runtime_flags(), 0);
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_control_request_digest_redacts_large_iovar_body() {
        let mut frame = [0u8; MAX_DRIVER_TASK_FRAME_BYTES];
        let mut payload = [0u8; 24];
        payload[..8].copy_from_slice(b"wsec_key");
        payload[9..].fill(0xa5);
        let len = cyw43_write_bcdc_frame(
            &mut frame,
            CYW43_WLC_SET_VAR,
            CYW43_BCDC_FLAG_SET,
            9,
            &payload,
        )
        .expect("wsec_key BCDC frame should fit");
        let info = cyw43_control_iovar_info(&frame[..len], CYW43_WLC_SET_VAR)
            .expect("wsec_key iovar should decode");
        let (digest_len, digest_scope) = cyw43_control_request_digest_len(len, Some(info));

        assert_eq!(info.name, "wsec_key");
        assert_eq!(info.data_len, 15);
        assert_eq!(info.value_u32, None);
        assert_eq!(digest_len, CYW43_BCDC_HEADER_BYTES + "wsec_key".len() + 1);
        assert_eq!(digest_scope, "header-iovar");
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn sdio_owner_recovery_preserves_ready_state_before_full_replay() {
        static LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
        let _guard = LOCK
            .lock()
            .expect("sdio owner recovery tests must serialize ready flag");

        SDIO_LINKED_RUNTIME_READY.store(0, Ordering::Release);
        assert!(!sdio_owner_recovery_can_preserve_ready_state());
        SDIO_LINKED_RUNTIME_READY.store(1, Ordering::Release);
        assert!(sdio_owner_recovery_can_preserve_ready_state());
        SDIO_LINKED_RUNTIME_READY.store(0, Ordering::Release);
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn bootstrap_causal_fault_preserves_first_cause_until_boundary() {
        let _guard = CYW43_STATUS_TEST_LOCK
            .lock()
            .expect("cyw43 causal fault tests must serialize");
        test_clear_cyw43_runtime_replay_status();

        let first = Cyw43RuntimeCommandFaultStatus {
            stage: "cyw43-firmware-release",
            op: DRIVER_RUNTIME_CYW43_OP_RELEASE,
            flags: 0,
            target_addr: 0x1800_3000,
            payload_offset: 0,
            payload_len: 0,
            total_len: 0,
            control_cmd: 0,
            control_id: 0,
            control_header_mode: "not-control",
            control_response_len: 0,
            detail: 0x531f,
            reason: "cyw43-armcr4-prereset-flush",
            result: 2,
        };
        let later = Cyw43RuntimeCommandFaultStatus {
            stage: "cyw43-transport-cmd5",
            op: DRIVER_RUNTIME_CYW43_OP_TRANSPORT_INIT,
            detail: 0x5325,
            reason: "sdio-card-ocr",
            result: 0x00ff_8000,
            ..first
        };
        let first_owner = Cyw43SdioOwnerFaultStatus {
            stage: first.stage,
            op: first.op,
            cmd: 53,
            arg: 0x1548_1004,
            function: 1,
            addr: 0x0000_a408,
            target_addr: first.target_addr,
            effective_target: first.target_addr,
            chunk_offset: 0,
            payload_offset: 0,
            increment: true,
            write: false,
            block_mode: false,
            len: 4,
            block_size: 64,
            block_count: 1,
            cmd53_count: 4,
            desc_block_count: 0,
            host_block_count: 1,
            transfer_mode: 0,
            host_control: 0,
            host_mode: "sdma",
            power_control: 0,
            clock_control: 0,
            clock_state: "stable",
            present_state: 0,
            int_status: 0,
            response0: 0,
            block_size_count_reg: 0,
            detail: first.detail,
            reason: first.reason,
            transfer_stage: "data-wait",
            transfer_status: 0,
            transfer_reason: "none",
            r5: 0,
            owner_window: "strict-ai-word",
            retry: "none",
            payload_first: 0,
            payload_last: 0,
            payload_xor: 0,
            payload_sum: 0,
            dma_cs: 0,
            dma_conblk: 0,
            dma_nextcb: 0,
        };
        let later_owner = Cyw43SdioOwnerFaultStatus {
            stage: later.stage,
            op: later.op,
            arg: 0x0000_0005,
            detail: later.detail,
            reason: later.reason,
            ..first_owner
        };

        begin_cyw43_bootstrap_causal_fault_capture();
        record_cyw43_runtime_command_fault_status(first);
        record_cyw43_sdio_owner_fault_status(first_owner);
        record_cyw43_runtime_command_fault_status(later);
        record_cyw43_sdio_owner_fault_status(later_owner);

        assert_eq!(latest_cyw43_runtime_command_fault_status(), Some(later));
        assert_eq!(latest_cyw43_sdio_owner_fault_status(), Some(later_owner));
        assert_eq!(
            bootstrap_causal_cyw43_runtime_command_fault_status(),
            Some(first)
        );
        assert_eq!(
            bootstrap_causal_cyw43_sdio_owner_fault_status(),
            Some(first_owner)
        );

        clear_cyw43_runtime_command_fault_status();
        assert_eq!(
            bootstrap_causal_cyw43_runtime_command_fault_status(),
            Some(first)
        );
        record_cyw43_runtime_command_fault_status(later);
        record_cyw43_sdio_owner_fault_status(later_owner);
        assert_eq!(
            bootstrap_causal_cyw43_runtime_command_fault_status(),
            Some(first),
            "retained retries must not erase the first causal fault",
        );
        assert_eq!(
            bootstrap_causal_cyw43_sdio_owner_fault_status(),
            Some(first_owner),
        );

        begin_cyw43_bootstrap_causal_fault_capture();
        assert_eq!(bootstrap_causal_cyw43_runtime_command_fault_status(), None);
        assert_eq!(bootstrap_causal_cyw43_sdio_owner_fault_status(), None);
        record_cyw43_runtime_command_fault_status(later);
        finish_cyw43_bootstrap_causal_fault_capture();
        record_cyw43_runtime_command_fault_status(first);
        assert_eq!(bootstrap_causal_cyw43_runtime_command_fault_status(), None);

        test_clear_cyw43_runtime_replay_status();
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_firmware_streaming_uses_bounded_boot_chunks() {
        let desc_size = core::mem::size_of::<DriverRuntimeCyw43CommandDescriptor>();
        assert_eq!(
            cyw43_runtime_stream_payload_limit(desc_size).ok(),
            Some(CYW43_RUNTIME_FIRMWARE_STREAM_CHUNK_BYTES)
        );
        assert_eq!(
            CYW43_RUNTIME_FIRMWARE_STREAM_CHUNK_BYTES,
            DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as usize
        );
        assert!(CYW43_RUNTIME_FIRMWARE_STREAM_CHUNK_BYTES > SDIO_CMD53_BYTE_MODE_MAX as usize);
        assert_eq!(CYW43_RUNTIME_FIRMWARE_STREAM_CHUNK_BYTES % 64, 0);
        assert_eq!(CYW43_RUNTIME_FIRMWARE_OWNER_RECOVERY_ATTEMPTS, 1);
        assert_eq!(CYW43_RUNTIME_FIRMWARE_OWNER_SAME_OFFSET_LIMIT, 1);
        assert_eq!(CYW43_RUNTIME_FIRMWARE_GENERATION_RECOVERY_ATTEMPTS, 2);
        assert_eq!(CYW43_RUNTIME_FIRMWARE_TAIL_PAD_ALIGNMENT, 4);
        assert_eq!(CYW43_RUNTIME_FIRMWARE_TAIL_PAD_MAX_BYTES, 32 * 1024);
        assert_eq!(CYW43_RUNTIME_FIRMWARE_STREAM_CHUNK_BYTES, 32 * 1024);
        assert_eq!(CYW43_RETAINED_NVRAM_BYTES, 8 * 1024);
        assert!(CYW43_RETAINED_NVRAM_BYTES < CYW43_RUNTIME_FIRMWARE_STREAM_CHUNK_BYTES);
        assert_eq!(
            609_309usize.div_ceil(CYW43_RUNTIME_FIRMWARE_STREAM_CHUNK_BYTES),
            19
        );
    }

    #[cfg(feature = "kernel")]
    #[test]
    fn cyw43_first_production_firmware_aperture_is_not_capped_by_nvram_arena() {
        static FIRMWARE: [u8; 609_309] = [0x5a; 609_309];
        static NVRAM: [u8; 1] = [b'\n'];

        let mut supervisor = Cyw43BootstrapSupervisor::new(ConsoleNetConfig::default());
        supervisor.bundle = Some(crate::hal::WifiFirmwareBundle::new(
            &FIRMWARE,
            &NVRAM,
            None,
            "brcm,bcm43455-fmac",
        ));
        supervisor.firmware_phase = Cyw43FirmwarePhase::FirmwareChunk { offset: 0 };

        supervisor
            .prepare_firmware_action()
            .expect("the first production-size firmware aperture must fit");
        let pending = supervisor
            .pending
            .as_ref()
            .expect("firmware action must remain retained");
        assert_eq!(
            pending.ticket.payload_len,
            DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as usize
        );
        assert_eq!(
            pending.ticket.descriptor.payload_len,
            DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as u16
        );
        assert_eq!(
            pending.ticket.payload,
            Cyw43RetainedPayload::Firmware {
                offset: 0,
                len: DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as usize,
            }
        );
        assert_eq!(
            pending.ticket.payload_digest,
            cyw43_payload_digest(&FIRMWARE[..DRIVER_RUNTIME_SDIO_SHARED_PAYLOAD_BYTES as usize])
        );
    }

